/* ============================================================================
   LAW_DATA — keyed by ISO-2. Most countries default-prohibit everything except
   ketamine (a medicine) and CBD (often permitted); overrides capture the rest.
   ========================================================================== */
window.LAW_DATA = {
  AF: { n:"Afghanistan", def:'ill', st:{ ket:'med' }, nt:{ _:"Afghanistan under Taliban de facto authorities enforces a comprehensive prohibition on narcotics (April 2022 decree: opium, heroin, methamphetamine, cannabis, alcohol; March 2023 cannabis-cultivation/hashish ban), backed by Sharia governance, mass arrests (2,000+ by Aug 2022) and field eradication. There is no medical, research, decriminalized, or religious-use framework for psychedelics — all fall under the enforced ban (ill). Ketamine is treated as a medical anaesthetic (med). Cocaine and coca leaf are illegal and not traditionally present. Afghanistan actively uses the death penalty and Taliban rhetoric has invoked execution for cannabis cultivation, but the authoritative capital-punishment-for-drug-trafficking tracker does NOT list Afghanistan, and codified drug penalties are prison terms plus fines; being conservative, trafficking-tier substances are coded 'ill' rather than 'cap', with the death-penalty rhetoric noted under cannabis.", can:"Cannabis/hashish illegal and enforced. The Taliban's April 2022 decree banned all narcotics (opium, heroin, meth, cannabis, alcohol); a March 2023 ban specifically targeted cannabis cultivation and hashish production. Codified penalties are prison (months to years) plus fines, though Taliban officials have also invoked 'up to the death sentence' for cultivation under Sharia.", cbd:"No separate legal category for CBD; falls under the blanket cannabis/narcotics prohibition. No regulated CBD market.", dmt:"No religious/traditional carve-out; ayahuasca/DMT falls under the comprehensive enforced narcotics prohibition.", ket:"Treated as a medical anaesthetic (WHO essential medicine) and present in Afghan healthcare facilities with marked regional variation; non-medical use falls under the narcotics ban.", coca:"No traditional or legal status; coca leaf falls under the total narcotics ban (not produced/used domestically)." } },
  AL: { n:"Albania", def:'decrim', st:{ cbd:'ill', ket:'med', ibo:'ill', coc:'ill', coca:'ill' }, nt:{ _:"Albania prohibits all the listed psychoactives as controlled substances, but its Criminal Code (Art. 283) does not punish possession of a single personal-use dose, and consumption is not itself an offence — so personal possession of cannabis and the classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline) is effectively decriminalized, while production/distribution draws 5-10 years (up to 10-20 aggravated). The death penalty was abolished for all crimes (Protocol 13, 2007), so no 'cap'. Medical cannabis was legalized (Law 61/2023, expanded June 2025) but is EXPORT-ONLY with no domestic patient access; CBD is treated as medical cannabis domestically and not sold to consumers. Ketamine is a registered medical anaesthetic ('med'). Ibogaine, cocaine and raw coca leaf have no permissive or traditional-use regime and are treated as illegal/enforced. Confidence medium: the personal-use carve-out is judge-determined case-by-case with no statutory gram threshold and wide police discretion, and no Albania-specific entries appear in the major psychedelic-law trackers.", can:"Recreational illegal under 1994 Narcotics Law + Criminal Code, but possession of a single dose for personal use is not punishable as a crime (Art. 283; consumption itself is not a distinct offence). Medical cannabis legalized by Law 61/2023 and greatly expanded June 2025, but cultivation/processing is EXPORT-ONLY — no domestic patient access.", cbd:"No specific CBD regulation; domestically-produced CBD/hemp extracts are classed as medical cannabis (export-only) and not sold domestically; imported CBD risks being treated as a cannabis product by customs. No legal domestic consumer access.", psi:"Schedule I (1971 Convention). Possession of a small personal-use dose is not criminally punished (Art. 283 carve-out); production/distribution = 5-10 yrs. No medical/therapeutic program.", lsd:"Schedule I. Sources state simple possession for personal use is not punishable; manufacture/distribution carries 5-10 yrs under Art. 283.", mdma:"Schedule I. Same regime: personal single-dose possession not criminally punished; trafficking 5-10 yrs (up to 10-20 aggravated).", dmt:"Schedule I (incl. ayahuasca). Possession of a small personal dose not punishable; producing/selling/distributing = 5-10 yrs. No religious/ayahuasca exemption.", mes:"Controlled hallucinogen; no peyote/San Pedro religious or traditional-use exemption. Same Art. 283 personal-use carve-out applies in principle.", ket:"Registered medicine/anaesthetic (WHO Essential Medicine); medical use legal. Recreational/non-medical use prohibited.", ibo:"No specific Albanian regulation or approved medical use found; handled as a prohibited controlled substance with no patient access.", coc:"Refined cocaine controlled and enforced; trafficking 5-10 yrs (up to 10-20 aggravated). A narrow single-dose personal-use carve-out exists in law but cocaine is treated as enforced/illegal.", coca:"Raw coca leaf controlled; no traditional/indigenous exemption in Albania; treated as an illegal narcotic." } },
  DZ: { n:"Algeria", def:'ill', st:{ ket:'med' }, nt:{ _:"Algeria criminalizes essentially all listed substances under Act No. 04-18 (amended by Act 23-05), which sorts drugs into Class A (heroin, ecstasy/MDMA, cocaine - harshest), Class B (amphetamines) and Class C (cannabis, temazepam - lightest). Cannabis & CBD are illegal and enforced (no THC/CBD distinction; 2 months-2 years for personal use). Classic psychedelics (psilocybin, LSD, DMT/ayahuasca, mescaline) and ibogaine are 1971 UN Convention Schedule I substances with no medical/traditional exemption -> illegal. MDMA and cocaine sit in Class A. Ketamine is available as a regulated medical/anaesthetic agent (med). On the death penalty: capital punishment remains on the books but drug trafficking was specifically removed from capital offences by amendments since 2001, and Algeria has had an execution moratorium since 1993 (abolitionist-in-practice); a 2025 presidential pledge to restore the death penalty is not yet enacted, so 'cap' was NOT assigned. Trafficking nonetheless carries severe sentences (10-20 years, up to 20 for aggravated cases) + large fines. Psychedelic/ibogaine codes are inferred from UN-Convention status plus Algeria's Class-A framework rather than substance-specific Algerian sources, hence medium confidence.", can:"Illegal & enforced (Class C). Personal use 2 months-2 years prison + fine; trafficking 10-20 years. A medical-cannabis pathway exists on paper (Decree 07-228/2007, Health Law 18-11, Min. of Health authorization) but no cannabinoid drug has market approval and no functioning program exists.", cbd:"Prohibited; Algerian law makes no THC/CBD distinction, so CBD is treated as cannabis.", mdma:"Explicitly listed in Class A (ecstasy) with heroin/cocaine - harshest tier; trafficking 10-20 years.", ket:"Controlled medicine; available for medical/anaesthetic use via ANPP under strict prescription controls. Recreational use illegal.", ibo:"No specific legal carve-out or approved medical access; treated as a prohibited/unapproved controlled substance.", coc:"Class A substance (with heroin & ecstasy) - most severe penalties; trafficking 10-20 years + heavy fines.", coca:"No traditional/indigenous exemption; prohibited as a cocaine source." } },
  AD: { n:"Andorra", def:'ill', st:{ cbd:'tol', ket:'med' }, nt:{ _:"Andorra maintains a strict prohibitionist, zero-tolerance drug policy. Cannabis is illegal for both recreational and medical use (no medical program despite a 2021 exploratory study), with active enforcement via Penal Code Art. 284. All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline), cocaine, and coca leaf are illegal and enforced as criminal offences with no decriminalization, religious, or medical carve-outs. CBD sits in a legal grey area — not legally separated from THC cannabis but de-facto tolerated when sold as EU-authorized cosmetic products made outside the country. Ketamine follows the global registered-medicine norm (medical use permitted, recreational illegal). Ibogaine has no Andorra-specific framework and is conservatively treated as illegal (low data). The death penalty was abolished in 1990, so no capital provisions apply. Confidence is medium overall given limited publicly available primary Andorran drug-law sources; ibogaine specifically is low-data.", can:"Illegal/enforced. Penal Code Art. 284: personal possession up to 12 months jail + €1200 fine; public use fines up to €600. No medical cannabis program (2021 govt-commissioned study never led to legalization). Enforcement is active.", cbd:"Legal grey area — hemp/CBD not legally distinguished from THC cannabis, but de-facto tolerated and sold when marketed as cosmetics (products must be EU-authorized and produced outside Andorra).", ket:"Registered medicine norm (Andorra relies on EU/Spanish pharmaceutical supply); recreational use illegal.", ibo:"No Andorra-specific legal framework or clinics; conservatively treated as illegal in a zero-tolerance jurisdiction — low data.", coc:"Refined cocaine illegal/enforced; Penal Code sets minimum fines for 'toxic drugs' (cocaine, ecstasy).", coca:"No traditional/indigenous use; coca leaf treated as a prohibited drug." } },
  AO: { n:"Angola", def:'ill', st:{ ket:'med' }, nt:{ _:"Angola maintains blanket drug prohibition under Law No. 3/99 (1999) and the 2020 Penal Code, and reaffirmed prohibition of cannabis and other psychotropic substances at the 2022 UN CND. Cannabis and CBD are fully illegal for all purposes with no medical program. All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) fall under blanket prohibition as UN-1971-Convention substances with no Angola-specific carve-outs (Angola is not individually tracked by Psychedelic Alpha; no religious ayahuasca exemption). Refined cocaine is illegal and a serious trafficking offence; coca leaf is non-traditional and prohibited. Ketamine is a registered medical anaesthetic (WHO essential medicine) -> med. Trafficking carries long/possibly life sentences, but the death penalty was abolished (1992 constitution, reaffirmed 2010 Art. 59, ICCPR Second Optional Protocol ratified 2019), so 'cap' is not warranted. Confidence medium: cannabis/CBD and death-penalty facts are well-sourced for Angola; psychedelic classifications are inferred from blanket prohibition rather than substance-specific Angolan sources.", can:"Totally illegal (recreational + medical); no medical cannabis program. Most-consumed illegal drug; arrests infrequent but enforced.", cbd:"Banned regardless of THC content or hemp source; no CBD/hemp exemption.", ket:"WHO essential medicine; registered anaesthetic widely used in human/veterinary medicine in low/middle-income African settings. Recreational use illegal.", coc:"Refined cocaine illegal and treated as a serious trafficking offence with long prison terms; NOTE death penalty abolished (1992 constitution, ratified ICCPR Second Optional Protocol 2019) so no capital punishment despite heavy sentences.", coca:"Not traditional/native to Angola; falls under general narcotics prohibition (Law 3/99)." } },
  AR: { n:"Argentina", def:'decrim', st:{ can:'med', cbd:'med', ket:'med', ibo:'ill', coc:'ill', coca:'legal' }, nt:{ _:"Argentina prohibits the listed controlled substances under Law 23.737, but the 2009 Supreme Court 'Arriola' ruling decriminalized possession of small amounts of any drug for personal use (an inconsistently enforced grey area), so classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) and cannabis are best classed as decrim for personal use. Cannabis additionally has a real medical pathway (Law 27.350 / REPROCANN), and CBD is medical-only with ANMAT-registered products. Ketamine is a registered medicine (med). Coca leaf in natural state is expressly legal for chewing/infusion (Art. 15); refined cocaine is illegal/enforced. Ibogaine has no documented access pathway and is conservatively marked illegal. Trafficking of any controlled drug carries 4-15 year sentences but no death penalty.", can:"Recreational illegal but personal-use possession decriminalized (2009 Supreme Court 'Arriola' ruling). Strong medical framework: medical cannabis legal since Law 27.350/2017, patient self-cultivation via REPROCANN registry. Note 2025 tightening (Resolution 1780/2025; ARICCAME regulator dissolved) but patient rights retained.", cbd:"Medical-only. ANMAT-registered CBD medicines available in pharmacies (Convupidiol/Alef, Kanbis/Elea, plus state-made Cannava CBD); import needs ANMAT (RAEM) authorization + prescription.", psi:"Schedule I controlled (illegal on paper), but personal-use possession decriminalized de jure under the 2009 'Arriola' Supreme Court ruling (Art. 19 Constitution); enforcement inconsistent, no defined personal-use quantities.", lsd:"Schedule I; personal-use possession decriminalized under 'Arriola' (small quantities). Trafficking heavily penalized (Law 23.737).", mdma:"Schedule I; personal-use possession decriminalized under 'Arriola'. Recreational supply remains a criminal offence.", dmt:"DMT/harmine/harmaline are Schedule I (Law 19.303); ayahuasca not explicitly listed. No religious protection (Santo Daime petition rejected 2016). However a 2017 ruling held that raw-plant possession (B. caapi) is not itself criminal absent refinement intent; personal possession also covered by 'Arriola' decrim. Administering for money risks 4-15 yrs.", mes:"Mescaline is Schedule I, but raw cactus (San Pedro/peyote) possession ruled not criminal in 2017 absent intent to refine; personal possession decriminalized under 'Arriola'.", ket:"Controlled substance (added by Decree 299/2010) but a registered/approved anaesthetic medicine; non-medical use illegal.", ibo:"No specific medical/legal framework or approved therapeutic access identified; falls under general controlled-substance prohibition (Law 23.737). Conservative classification; personal possession could in theory benefit from 'Arriola' decrim but no real-world access pathway documented.", coc:"Refined cocaine illegal; production/trafficking 4-15 yrs (Law 23.737 Art. 5). Personal-use possession is de jure decriminalized under 'Arriola', but the substance remains prohibited and supply strongly enforced.", coca:"Coca leaf in natural state is expressly permitted under Art. 15 of Law 23.737 for chewing ('coqueo') or infusion; not treated as a narcotic. Cultivation and importation remain illegal." } },
  AM: { n:"Armenia", def:'ill', st:{ cbd:'tol', ket:'med' }, nt:{ _:"Armenia prohibits all classic recreational drugs and psychedelics under the 2003 Law on Narcotic Drugs and Psychotropic Substances (Lists 1-4); trafficking can carry up to life imprisonment, but the death penalty is fully abolished (no 'cap'). Personal possession of undefined 'small quantities' was reduced to an administrative fine (~2008), a notable leniency, but substances remain prohibited with no medical/religious access framework. Cannabis is illegal for recreational and medical use, though industrial hemp (<0.3% THC) was legalized in 2021; CBD sits in a legal grey area (hemp pathway exists, consumer products not explicitly authorized). Ketamine is a registered medicine. No coca-leaf tradition. Confidence medium: prohibition framework and death-penalty abolition are well-established, but per-substance list placement and CBD's exact consumer status are inferred from standard patterns rather than substance-specific 2024-2026 primary sources.", can:"Illegal for recreational and medical use. Industrial hemp (<0.3% THC) cultivation/export legalized 2021. Personal possession of small quantities reduced to an administrative fine since ~2008, but cannabis remains prohibited and trafficking is criminally enforced.", cbd:"Legal grey area: industrial-hemp production, sale and export (<0.3% THC) legalized in 2021, but CBD products for human consumption are not explicitly authorized. De-facto tolerated rather than clearly legal.", psi:"Controlled under the 2003 Law on Narcotic Drugs and Psychotropic Substances; possession of 'small quantities' for personal use is an administrative fine, but no medical/therapeutic access exists.", ket:"Controlled but a registered medicine/anaesthetic on Armenia's controlled-medicines register; recreational use illegal.", coc:"Illegal and enforced; Armenia is a minor cocaine transit point. Trafficking can carry up to life imprisonment. Death penalty fully abolished (Protocol 13 in force Feb 2024), so no capital punishment for drug offences.", coca:"No traditional/indigenous use; controlled substance, illegal." } },
  AU: { n:"Australia", def:'ill', st:{ can:'med', cbd:'med', psi:'med', mdma:'med', ket:'med', ibo:'med' }, nt:{ _:"Australia regulates drugs via the national Poisons Standard (SUSMP). Cannabis, LSD, DMT/ayahuasca, mescaline, coca leaf and refined cocaine are prohibited/controlled and enforced as criminal offences. Australia is a world leader on psychedelic medicine: psilocybin and MDMA were rescheduled to Schedule 8 on 1 July 2023 for prescribing by TGA-authorised psychiatrists (TRD and PTSD respectively). CBD (S4, low-dose S3), ketamine (S8, esketamine on PBS 2025) and ibogaine (S4 since 2010) are available medically. Cannabis is medical-by-prescription nationwide but recreationally illegal, with the ACT a decriminalised outlier. The ACT also decriminalised personal possession of most hard drugs (incl. cocaine, MDMA, heroin, LSD) from Oct 2023, but nationally these remain criminal.", can:"Recreational illegal & enforced nationally (Schedule 9 / state criminal offences); medical cannabis legal by prescription since 2016. ACT de-penalised personal possession (up to 50g) and home cultivation (2 plants/person) since Jan 2020; NSW/Vic retail pilots flagged for 2026.", cbd:"Medical only. Schedule 4 prescription medicine; low-dose CBD (<=150mg/day) down-scheduled to Schedule 3 pharmacist-only/OTC, but as of early 2026 no product is yet registered on the ARTG for S3 supply.", psi:"World-first medical access: rescheduled from Schedule 9 to Schedule 8 (controlled) on 1 July 2023 for prescribing by TGA-authorised psychiatrists for treatment-resistant depression. Otherwise Schedule 9 prohibited.", lsd:"Schedule 9 prohibited substance, criminal offence nationally. Personal possession (5 doses) decriminalised/civil-penalty only in the ACT since 28 Oct 2023.", mdma:"Rescheduled to Schedule 8 on 1 July 2023 for TGA Authorised Prescriber psychiatrists treating PTSD. Otherwise Schedule 9 prohibited. Personal-use possession also decriminalised in the ACT since Oct 2023 (1.5g).", dmt:"DMT/ayahuasca is a Schedule 9 prohibited substance in all states and territories; possession, use, import and supply are criminal offences. No religious-use exemption.", mes:"Mescaline (peyote/San Pedro) is a Schedule 9 prohibited substance; possession, use, cultivation and supply are criminal offences.", ket:"Registered medicine (Schedule 8 controlled drug); esketamine nasal spray (Spravato) listed on the PBS for treatment-resistant depression from 1 May 2025. Recreational use illegal.", ibo:"Schedule 4 prescription-only medicine since 2010 (so available medically); notably, ibogaine-containing plants are not separately scheduled, so possession/cultivation of the plant is not a controlled-substance offence.", coc:"Schedule 8 controlled drug; recreational possession/supply illegal and enforced (limited medical/dental use). Personal possession (1.5g) decriminalised to a civil penalty in the ACT since 28 Oct 2023.", coca:"Coca leaf is a Schedule 9 prohibited substance; no traditional-use exemption." } },
  AT: { n:"Austria", def:'ill', st:{ can:'med', cbd:'legal', psi:'decrim', ket:'med' }, nt:{ _:"Austria controls all listed substances under the Suchtmittelgesetz (SMG) and Suchtgiftverordnung. Since 2016, personal-use possession follows 'Therapie statt Strafe' (treatment instead of punishment), making cannabis and magic mushrooms effectively decriminalized for users, though no licensed recreational market exists. CBD/low-THC hemp products are sold legally. Ketamine is a registered medicine and esketamine (Spravato) gained reimbursement in Aug 2024. LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine, cocaine and coca leaf remain illegal and enforced, with research-only access and no routine medical pathway (a 2021 bid to reschedule MDMA/psilocybin for medical use failed).", can:"Recreational illegal but personal-use possession decriminalized since 2016 under 'Therapie statt Strafe' (treatment instead of punishment); medical cannabis available by prescription (Sativex/dronabinol/nabilone) though AGES supplies no flower to pharmacies/patients.", cbd:"Low-THC hemp and CBD products sold legally; industrial hemp cultivation permitted; long a grey area but clarified by 2026.", psi:"Psilocybin/psilocin mushrooms scheduled (Annex V.1 Suchtgiftverordnung; expressly in §27 SMG) but personal possession decriminalized since 2016 — mandatory free therapy rather than punishment.", mdma:"Schedule-9-type research-only; 2021 attempt to reschedule MDMA & psilocybin for medical use failed. Personal possession diverted to treatment under 2016 reform.", ket:"Ketamine is an authorised anaesthetic (off-label psychiatric use); esketamine (Spravato) EMA-approved and in Austria's reimbursement code since Aug 2024 under strict RE1 criteria; recreational use illegal.", ibo:"Not explicitly enumerated for Austria in available sources, but treated as controlled with no medical/therapeutic access pathway identified; classified illegal conservatively (lower confidence).", coca:"Coca leaf illegal as a non-Andean country, treated similarly to cocaine under the SMG." } },
  AZ: { n:"Azerbaijan", def:'ill', st:{ ket:'med' }, nt:{ _:"Azerbaijan prohibits and actively enforces against essentially all listed substances. Cannabis (recreational and medical) and CBD are illegal under Criminal Code Art. 234, with possession penalties up to 12 years and strict, sometimes politically motivated, enforcement. Classic psychedelics (psilocybin, LSD, MDMA, DMT) are explicitly on the prohibited List I; mescaline, ibogaine, cocaine, and coca leaf are likewise prohibited with no medical/religious access. Ketamine is the one exception - a registered controlled medicine (med), though recreational use is illegal. The death penalty was abolished in 1998 and replaced by life imprisonment, so no 'cap' classification applies despite multi-year trafficking sentences. Confidence is high for cannabis/CBD/the four classic psychedelics (directly sourced) and medium overall, since ketamine, ibogaine, mescaline, and coca leaf statuses are inferred from Azerbaijan's adherence to the UN scheduling framework rather than substance-specific national citations.", can:"Illegal recreational and medical (Criminal Code Art. 234). Strictly enforced; drug charges documented as politically weaponized (HRW/OCCRP). Possession <10g may be diverted to family/treatment via prosecutorial discretion, but no formal decriminalization.", cbd:"Treated identically to cannabis - no medical/recreational distinction; CBD products illegal and possession can carry up to 12 years. Hemp-for-fibre permitted only under strict state supervision.", psi:"On Azerbaijan's prohibited (List I) psychotropic substances list.", lsd:"On Azerbaijan's prohibited (List I) psychotropic substances list.", mdma:"On Azerbaijan's prohibited (List I) psychotropic substances list. No therapy/research access.", dmt:"On Azerbaijan's prohibited list; no ayahuasca religious exemption.", ket:"Registered anesthetic medicine in the post-Soviet healthcare system (controlled). Recreational use illegal; analogue methoxetamine/MXE explicitly banned.", coc:"Prohibited narcotic (List I), enforced under Art. 234; trafficking carries multi-year prison terms. Death penalty abolished 1998, so no capital status.", coca:"No traditional/indigenous use; treated as prohibited narcotic plant, illegal." } },
  BH: { n:"Bahrain", def:'ill', st:{ can:'cap', ket:'med', coc:'cap' }, nt:{ _:"Bahrain criminalizes all listed recreational drugs under Law No. 15 of 2007 on Narcotic Drugs and Psychotropic Substances. Article 30 authorizes the DEATH PENALTY for drug trafficking/dealing; trafficking otherwise draws life imprisonment plus fines up to 50,000 BHD, and personal possession up to ~2 years plus fines. Death sentences have genuinely been imposed for non-violent drug offences (including hashish/cannabis) since 2018, with people still on death row for drug charges, though the last actual executions were in 2019 (cap applied to the high-volume trafficking drugs cannabis and refined cocaine that documented capital cases involve; other prohibited substances marked ill conservatively, but all fall under the same trafficking-death-penalty regime). Cannabis (incl. CBD/hemp, no legal distinction) is Schedule I and illegal for recreational and medical use; a 2023 MOH 'Medicinal Cannabis Regulation' exists on paper but no functioning patient-access program is documented. Classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) and ibogaine are prohibited psychotropics with no medical/research or religious-use exemption. Ketamine is a regulated controlled medicine (medical use only) via the Ministry of Health's controlled-prescription system. Coca leaf has no traditional use and is treated as a prohibited narcotic.", can:"Schedule I under Law No. 15/2007; recreational & medical both illegal. A 2023 Ministry of Health 'Medicinal Cannabis Regulation' exists on paper but there is no documented functioning patient-access program; trafficking is capital-eligible (Art. 30) and courts have imposed death sentences for hashish/cannabis offences since 2018.", cbd:"No legal distinction from cannabis; CBD products prohibited and import banned by customs. Despite the 2023 medicinal-cannabis framework, no real CBD patient access is documented.", mdma:"Psychotropic substance under Law 15/2007; no medical/research access. Trafficking can carry death penalty or life imprisonment.", ket:"Regulated as a controlled medicine via MOH controlled-prescription system; medical use only, recreational use illegal.", coc:"Schedule I narcotic; import explicitly banned. Trafficking is capital-eligible under Art. 30 of Law 15/2007.", coca:"No traditional/indigenous use; treated as a prohibited narcotic." } },
  BD: { n:"Bangladesh", def:'ill', st:{ can:'cap', ket:'med', coc:'cap' }, nt:{ _:"Bangladesh maintains a hardline, actively enforced prohibitionist drug regime under the Narcotics Control Act 2018 (replacing the 1990 Act). The death penalty or life imprisonment applies to large-quantity trafficking: cannabis over 2kg and Category A drugs (heroin/cocaine) over 25g. All listed psychoactives are illegal; there is no medical-cannabis, CBD, or psychedelic-therapy framework. Ketamine is the sole exception, available as a registered hospital anaesthetic. Cannabis and refined cocaine are marked 'cap' due to explicit statutory death-penalty provisions; the remaining substances are 'ill' (illegal and enforced) absent sources confirming capital thresholds for them specifically.", can:"Illegal since ~1989; Narcotics Control Act 2018 gives courts discretionary power to impose the death penalty for possession over 2kg. De-facto tolerated only at the annual Lalon Shah folk/spiritual festival in Kushtia.", cbd:"No legal distinction from cannabis; illegal with no THC-free exemption.", psi:"Prohibited controlled substance; illegal and enforced.", lsd:"Banned controlled substance since 1990; first domestic seizures appeared ~2019, prosecuted as illegal.", ket:"Registered, widely available prescription anaesthetic (multiple local brands, WHO Essential Medicine); recreational use illegal.", coc:"Category A narcotic; death penalty possible for trafficking over 25g (confirmed by a Sept 2025 prosecution).", coca:"No traditional use or carve-out; treated as a prohibited narcotic, illegal." } },
  BB: { n:"Barbados", def:'ill', st:{ can:'med', cbd:'med', ket:'med' }, nt:{ _:"Barbados: cannabis decriminalized for small amounts (14g/$200 fine) with legal medical regime (since 2019, dispensary open 2025) and Rastafarian sacramental use; CBD available medically. All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline), ibogaine, cocaine and coca leaf are illegal and enforced under the Drug Abuse (Prevention and Control) Act Cap.131. Ketamine treated as a registered medicine. No death penalty for drug offences (capital punishment reserved for murder; de facto moratorium since 1984). Govt has acknowledged the drug law is outdated and pledged reform.", can:"Recreational illegal but decriminalized: possession up to 14g = BBD$200 fine, generally no criminal charge; cultivation still up to 5 yrs. Medical cannabis legal since Nov 2019 (Medicinal Cannabis Industry Act); first dispensary, Island Therapeutics Inc., opened June 2025. Sacramental Cannabis Act permits use by registered Rastafarians.", cbd:"No standalone CBD law; treated under the medicinal cannabis framework, lawful via regulated medical channels (prescription). Conservatively coded med rather than legal — no clear evidence of free OTC retail.", mdma:"Ecstasy/MDMA prosecuted but enforcement hampered by no defined trafficking threshold; ~3/4 of 2023 ecstasy cases charged as simple possession. Govt (Jan 2025) called drug laws outdated and pledged amendments.", ket:"No Barbados-specific statute found; treated as a registered medical anaesthetic (med). Flagged by NCSA as an emerging non-traditional drug of abuse (2026); recreational use illegal.", ibo:"Not named explicitly in legislation; falls under general controlled-substance prohibition with no medical/therapeutic access — coded ill, lower confidence.", coc:"Cocaine is a scheduled controlled drug under the Drug Abuse (Prevention and Control) Act Cap.131 with defined trafficking thresholds; enforced. Death penalty does NOT apply to drug offences (mandatory death penalty struck down 2018, reserved for murder; de facto moratorium since 1984).", coca:"No traditional/indigenous coca use in Barbados; coca leaf falls under controlled-drug prohibition, illegal." } },
  BY: { n:"Belarus", def:'ill', st:{ ket:'med' }, nt:{ _:"Belarus has one of Europe's harshest drug regimes. All substances in scope are illegal and aggressively enforced under Article 328 of the Criminal Code, with no medical cannabis or legal CBD. Only ketamine is permitted — as a List II controlled medicine for anesthetic/veterinary use. Aggravated trafficking carries 20–25 year sentences. The death penalty exists in Belarus but applies only to aggravated murder, terrorism and treason, NOT drug crimes, so 'cap' is not assigned. Mescaline and ibogaine are classed 'ill' by inference from the blanket prohibition (lower confidence); all others are well-documented.", can:"Fully illegal, no medical/recreational allowance; even industrial hemp <0.2% THC is restricted. Article 328 of the Criminal Code, aggressively enforced (10,000+ imprisoned for drug offences).", cbd:"Illegal — Belarus makes no cannabis/hemp distinction; no legal CBD products even at low/zero THC.", psi:"Illegal, controlled (Convention on Psychotropic Substances Schedule I; Belarus List 1).", dmt:"All forms (ayahuasca, synthetic) prohibited; possession/use 6 months to 15 years.", mes:"Mescaline / psychoactive cacti controlled and prohibited (inferred from comprehensive prohibition; lower confidence).", ket:"Registered List II controlled medicine (Ministry of Health Decree of 31.07.2009 N 89); legal for medical/anesthetic and veterinary use, recreational use illegal.", ibo:"No medical use; not explicitly enumerated in sources but treated as a controlled narcotic under Belarus's blanket prohibition (lower confidence).", coc:"Illegal narcotic under Article 328; severe sentences (up to 20–25 years for aggravated/organized trafficking or drug-caused death). Note: Belarus retains the death penalty but ONLY for aggravated murder, terrorism and treason — NOT drug offences." } },
  BE: { n:"Belgium", def:'ill', st:{ can:'med', cbd:'legal', ket:'med' }, nt:{ _:"Belgium prohibits all classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) and ibogaine as Schedule I substances with enforced criminal penalties (3 months-5 years), with no medical/therapeutic access programs. Ketamine is a registered medicine (med). Cocaine is illegal/enforced (instant EUR 1,000 fine); coca leaf has no permitted use (ill). Cannabis is decriminalized for personal possession (up to 3g/one plant, adults 18+) since 2003 but otherwise prohibited; medical cannabis is highly restricted (only Sativex licensed). CBD is lawful/regulated as a non-narcotic when from EU hemp at <=0.3% THC, though ingestibles face Novel Food limits.", can:"Illegal but personal possession up to 3g or one plant by adults 18+ decriminalized since 2003 (administrative fine ~EUR 120-330, generally not prosecuted absent aggravating factors). Instant fines (~EUR 150) since 2022. Medical cannabis extremely restricted: only Sativex licensed (MS spasticity, neurologist-only). No recreational or commercial framework.", cbd:"Not classified as a narcotic since 2019 reclassification. Legal/regulated if derived from EU-catalogue industrial hemp with <=0.3% THC (raised from 0.2% in 2023). External/cosmetic products permitted; magistral pharmacy CBD preparations allowed. Ingestible CBD constrained by EU Novel Food rules, but the compound itself is lawful.", psi:"Schedule I under Royal Decree of 1998 / 1971 Convention; illegal and enforced, penalties 3 months-5 years. No medical/therapy program (unlike Czechia/Germany compassionate use).", mdma:"Schedule I, illegal and enforced; instant fines of EUR 300 for ecstasy, actively issued at festivals (e.g. Tomorrowland). No approved MDMA-assisted therapy.", dmt:"DMT is controlled; ayahuasca preparations covered as DMT-containing preparations. Santo Daime sought a religious-freedom exemption but was convicted at all court levels (Bruges 2014, Ghent Court of Appeal 2015, further cases to 2017). No religious or therapeutic exemption exists; enforced.", ket:"Registered medicine (anesthetic); added to Belgium's controlled-substances list in 2013. Recreational use illegal.", ibo:"Ibogaine and isomers listed in Chapter 2 of the Royal Decree of 1998; possession/production/sale punishable by 3 months-5 years and fines. No legal treatment pathway. (National scheduling; not UN-controlled.)", coc:"Illegal and enforced; instant fine up to EUR 1,000 for possession. Refined cocaine is a Schedule I narcotic.", coca:"Raw coca leaf has no traditional or permitted use in Belgium; controlled as a cocaine-source/narcotic. Illegal." } },
  BZ: { n:"Belize", def:'ill', st:{ can:'decrim', cbd:'legal', dmt:'tol', ket:'med' }, nt:{ _:"Belize criminalizes psychedelics and cocaine as Class A drugs under the Misuse of Drugs Act (Cap. 103), with mandatory long sentences (incl. life for Class A trafficking) but no death penalty. Cannabis possession up to 10g on private premises was decriminalized in 2017; hemp-derived CBD (<=0.3% THC) is legal. Ketamine is a controlled hospital medicine. Ayahuasca/DMT is illegal on paper but de-facto tolerated, with retreat centers operating and prosecution rare.", can:"Misuse of Drugs (Amendment) Act No. 47 of 2017 decriminalized possession/use of up to 10g on private premises; cultivation, sale, import/export and public use remain criminal offences. Oct 2025 Caye Caulker referendum on local legalization rejected (~79% No); no national adult-use reform as of 2026.", cbd:"Hemp-derived CBD legal if THC <=0.3%; 2017 reform removed industrial hemp from controlled substances. Industry nascent, importation not allowed, only domestically grown CBD sold.", dmt:"DMT is a Class A drug (up to 5yr); no formal religious/indigenous exemption, but ayahuasca retreat centers operate openly and prosecution is very rare — de-facto tolerated gray area.", ket:"No Belize-specific reform; registered as a hospital anesthetic (emergency/pediatric/trauma use); non-medical use prohibited.", coc:"Class A; possession of >1g deemed trafficking; mandatory long sentences incl. life imprisonment for Class A trafficking. Belize has no death penalty for drug offences, so not capital.", coca:"No Andean/traditional coca use in Belize; raw coca leaf falls under the same Class A prohibition as cocaine." } },
  BJ: { n:"Benin", def:'ill', st:{ ket:'med' }, nt:{ _:"Benin prohibits all recreational/non-medical drug use under Law No. 87-009 (1987), Law No. 97-025 (1997) and Penal Code arts. 960+, implementing the 1961/1971/1988 UN conventions; enforced by OCERTID and prosecuted before CRIET. Cannabis, cocaine, and all classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) are illegal and enforced, with no medical-cannabis, decriminalization, or psychedelic-therapy carve-outs and no ayahuasca/peyote religious exception. Coca leaf and CBD fall under the same prohibition (CBD low confidence, no separate regime). Ketamine is a registered medicine (WHO Essential Medicines List, primary surgical anaesthetic) -> 'med'. Ibogaine has no Benin-specific legalization despite iboga's regional origins (Bwiti tradition is Gabonese, not Beninese) -> illegal, low confidence. The death penalty was abolished in 2016, so drug offences carry long prison terms but NOT capital punishment (not 'cap').", can:"Fully illegal, no medical/recreational distinction; active enforcement (seizures rose from 82 kg in 2006 to 2,444 kg in 2021). Only locally cultivated drug; Benin is a regional transshipment hub.", cbd:"No separate CBD regime identified; falls under blanket cannabis prohibition. Conservatively classed illegal; low confidence.", ket:"On WHO Essential Medicines List; primary surgical anaesthetic in West Africa, available as a registered hospital medicine. Recreational use prohibited.", ibo:"No Benin-specific scheduling or Bwiti/religious carve-out (the iboga/Bwiti tradition is centered in Gabon, not Benin); not an approved medicine. Defaulted to illegal under general psychotropics law; low confidence." } },
  BT: { n:"Bhutan", def:'ill', st:{ ket:'med' }, nt:{ _:"Bhutan prohibits cannabis (recreational and medical, no CBD carve-out) and all classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) and refined cocaine and coca leaf as Schedule I/II 'no medicinal value' substances under the Narcotic Drugs, Psychotropic Substances and Substance Abuse Act (NDPSSA; 2024 regulations, draft 2026 rules in consultation), enforced via the BFDA Controlled Substances and Medical Device Division. Substances with recognized medical value (Schedules III/IV) — including ketamine — are available under licence for medical/scientific use, so ketamine = med. The death penalty was abolished for all crimes in 2004 and is constitutionally banned (2008), so NO drug offence carries capital punishment; drug crimes are prison sentences (personal-use cannabis ~1-12 months; selling 5-9 years), hence 'ill' rather than 'cap' across the board. Per-substance psychedelic scheduling is inferred from the 'no medicinal value' Schedule I/II structure plus Bhutan's adherence to the UN conventions rather than a published name-by-name list, hence medium confidence.", can:"Cannabis is illegal (recreational and medical); grows wild but criminally controlled. Personal-use possession ~1-12 months prison, selling 5-9 years. No medical-cannabis access.", cbd:"No CBD/hemp carve-out; Bhutan does not distinguish CBD from cannabis, which is prohibited with no prescription pathway.", psi:"Classic hallucinogen treated as a Schedule I/II substance with no recognized medicinal value under the NDPSSA; no medical/research access in practice.", mdma:"Prohibited psychotropic (no medicinal value) under the NDPSSA; no clinical/therapy pathway.", dmt:"DMT/ayahuasca prohibited; no religious or therapeutic exemption.", mes:"Mescaline (peyote/San Pedro) prohibited; no indigenous/religious exemption.", ket:"Ketamine is a registered anaesthetic (medical value) regulated by BFDA's Controlled Substances Division; importable/usable under licence for medical/scientific purposes. Non-medical use illegal.", coca:"No traditional/indigenous use; coca leaf treated as a prohibited narcotic, illegal and enforced." } },
  BO: { n:"Bolivia", def:'ill', st:{ dmt:'decrim', mes:'decrim', ket:'med', coca:'legal' }, nt:{ _:"Bolivia follows a 'coca yes, cocaine no' model: raw coca leaf is fully legal (2009 Constitution; Coca General Law 906/2017), while refined cocaine and the classic controlled psychedelics (psilocybin, LSD, MDMA) are illegal Schedule I substances under Law 1008. Cannabis and CBD remain illegal with no enacted medical program. Plant entheogens with indigenous/traditional roots — ayahuasca (DMT) and San Pedro (mescaline) — are de-facto allowed under the Constitution's protection of native medicinal plants. Ketamine functions as a registered medicine. Ibogaine has no specific recognition and is conservatively treated as prohibited.", can:"Illegal under Law 1008; possession of small amounts (~50g) may divert to mandatory treatment, but cultivation/recreational use is a criminal offence.", cbd:"No hemp/CBD distinction in law; falls under cannabis prohibition. No medical-cannabis program enacted as of 2026.", psi:"Schedule I under Law 1008; trafficking penalties 10-25 years.", dmt:"Ayahuasca permitted as indigenous patrimony under the 2009 Constitution; brew ingredients sold openly in markets, ceremonial use unrestricted. Pure synthetic DMT remains controlled.", mes:"San Pedro/Wachuma cactus is a native Andean traditional medicine used openly; pure mescaline controlled but the plant is not restricted in practice.", ket:"Registered anaesthetic/medicine; reportedly not explicitly scheduled, but non-medical use treated as a controlled substance.", ibo:"Not specifically scheduled or recognized; conservatively treated under the general controlled-substances prohibition. Low certainty.", coc:"Illegal under Law 1008 ('Coca yes, cocaine no'); trafficking 10-25 years (long sentences, not capital).", coca:"Legal: traditional use enshrined in 2009 Constitution; cultivation and domestic market regulated under Coca General Law 906 (2017)." } },
  BA: { n:"Bosnia and Herzegovina", def:'ill', st:{ can:'med', cbd:'tol', ket:'med' }, nt:{ _:"Bosnia and Herzegovina prohibits essentially all listed substances as Schedule I psychotropics under its 2006 narcotics law and two entity criminal codes. Production/sale carries up to 10 years; personal-use possession is a fineable minor offence in Republika Srpska and Brcko District but jailable up to 1 year in the Federation of BiH. Ketamine is the exception — a Schedule II registered medicine (medical use OK, recreational illegal). CBD sits in an unregulated gray area (hemp legal, flower processing not). The major recent reform: medical cannabis was legalized effective 1 January 2026 (reclassified 29 Dec 2025) on a strict prescription-only pharmaceutical model, but recreational cannabis remains illegal. No coca-leaf or peyote/ayahuasca religious or indigenous exemptions exist. Ibogaine and coca leaf lack BiH-specific text and are coded illegal conservatively under the blanket prohibition.", can:"Recreational illegal & enforced; production/sale up to 10 yrs. Personal possession is a minor offence (fine ~EUR 500-1,500) in Republika Srpska & Brcko, but jailable up to 1 yr in the Federation of BiH. NOTABLE: medical cannabis legalized effective 1 Jan 2026 (Council of Ministers reclassified cannabis/resins/extracts to a 'monitored' table on 29 Dec 2025) — prescription-only, dispensed as authorized pharmaceutical products.", cbd:"Legal gray area: industrial hemp is legal but processing the flower (CBD-bearing part) is not; no explicit ban on CBD and no legal processing framework. Low-THC products de-facto tolerated.", dmt:"Schedule I; DMT, ayahuasca and changa prohibited; production/sale up to 10 yrs (Art. 195). Personal possession a misdemeanour in Republika Srpska, up to 1 yr in the Federation.", ket:"Schedule II controlled substance; registered medicine, medical/prescribed use permitted, non-medical use illegal.", ibo:"No BiH-specific scheduling found and not on UN control lists; classified illegal here as a conservative default given blanket prohibition of psychoactive substances and absence of any medical/research or decrim framework.", coca:"No traditional/indigenous-use exemption; treated as a prohibited narcotic source plant. Refined cocaine likewise illegal and enforced." } },
  BW: { n:"Botswana", def:'ill', st:{ ket:'med' }, nt:{ _:"Botswana broadly prohibits and enforces drug laws. Recreational cannabis, CBD, and all classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) plus cocaine and coca leaf are illegal controlled substances with no religious/medical/research carve-outs. The notable recent change is the Cannabis Bill 2025 (gazetted Aug 2025), which creates a tightly licensed framework for MEDICINAL cannabis and industrial hemp cultivation/export only — recreational use stays illegal. Ketamine is a registered medicine (BoMRA, Medicines and Related Substances Act 2013) so 'med'. Trafficking carries long sentences (up to 25 yrs); a 2024 whitepaper recommended a death penalty for traffickers but it is NOT yet law, so 'cap' was not assigned (conservative). Confidence medium: cannabis/CBD/cocaine/ketamine well-sourced incl. primary law and the 2025 bill, but per-substance scheduling for LSD/MDMA/DMT/mescaline/ibogaine is inferred from Botswana's narcotic/psychotropic-substances regime rather than line-item confirmation.", can:"Recreational cannabis illegal & enforced (possession <60g up to 3 yrs; >60g up to 5 yrs / P100,000). BUT the Cannabis Bill 2025 (No. 25 of 2025, gazetted 8 Aug 2025, passed by Parliament 14 Aug 2025) operationalises a Policy on the Licit Use of Cannabis, legalising cultivation/export of MEDICINAL cannabis and industrial hemp under a state-controlled licensing model. General/recreational use remains prohibited.", cbd:"No consumer carve-out; CBD treated as a cannabis-derived controlled substance and illegal outside the new licensed medicinal/industrial framework.", psi:"Psilocybin/psilocin controlled as psychotropic substances; no religious, medical or research access pathway. Wild Psilocybe occur regionally but the active compounds are scheduled.", lsd:"Controlled psychotropic substance; illegal, no medical/research access.", mdma:"Controlled psychotropic substance; illegal, no medical/research access.", dmt:"DMT controlled as a psychotropic; no ayahuasca/religious exemption.", mes:"Mescaline controlled; no peyote/San Pedro religious or traditional exemption.", ket:"Registered anaesthetic medicine regulated by the Botswana Medicines Regulatory Authority (BoMRA) under the Medicines and Related Substances Act 2013; recreational use illegal.", ibo:"No approved or regulated use; treated as a controlled substance.", coc:"Refined cocaine scheduled as a narcotic; illegal and enforced. Trafficking up to 25 yrs / P500,000. NOTE: an Apr-2024 constitutional-review whitepaper RECOMMENDED adding the death penalty for drug lords/traffickers, but this was NOT enacted as of 2026.", coca:"Coca leaf listed alongside cocaine in the drug schedules; no traditional or legal use in Botswana — illegal." } },
  BR: { n:"Brazil", def:'ill', st:{ can:'decrim', cbd:'med', dmt:'decrim', ket:'med', ibo:'med' }, nt:{ _:"Brazil (2026): Cannabis possession decriminalized for personal amounts (STF, June 2024) but recreational sale criminal; medical CBD/cannabis legal and expanding under ANVISA (RDC 327/2019, 2025 overhaul). Classic psychedelics (psilocybin, LSD, MDMA, mescaline) are proscribed List F2 and enforced — though psilocybin mushrooms sit in a legal gray area. Ayahuasca is uniquely permitted for religious/ritual use (CONAD since 1987) despite DMT being banned. Ketamine and ibogaine are regulated/approved medicines. Cocaine and coca leaf are illegal and enforced. Brazil has no death penalty for drug offences.", can:"Recreational illegal, but STF (Supreme Court) ruled June 2024 that personal possession up to 40g / 6 female plants is not a criminal offence (treated as administrative infraction). Sale/trafficking remains criminal.", cbd:"Legal for medical use only, ANVISA-regulated since RDC 327/2019; framework expanded in 2025 (pharmacy compounding, broader therapeutic uses, domestic low-THC cultivation for medical/research). No recreational CBD market.", psi:"Psilocybin & psilocin proscribed under Portaria SVS/MS 344/1998 List F2 and enforced. Legal gray area: the mushrooms themselves are not explicitly listed, and a Mato Grosso do Sul court acquitted a grower in April 2025 — but the active compounds are banned, so default status is illegal.", dmt:"DMT prohibited under Law 11.343/2006, BUT ayahuasca is explicitly authorized for religious/ritual use since 1987 via CONAD (National Drug Policy Council) resolutions, grounded in religious-freedom and Indigenous/Afro-Brazilian cultural protections. ANVISA (2021/2025) bans commercial sale & advertising but exempts religious use.", ket:"ANVISA-approved registered medicine: hospital anesthetic and approved (Nov 2020) for treatment-resistant depression incl. intranasal esketamine; Class C1 controlled. Recreational use illegal.", ibo:"Controlled substance; legalized for prescription/medical use (initially São Paulo, 14 Jan 2016, extending nationally). Recreational use illegal.", coc:"Prohibited and enforced under Law 11.343/2006; trafficking carries 5–15 years. Brazil has NO death penalty for drug offences (capital punishment only for wartime crimes), so not 'cap'.", coca:"No traditional/legal coca-leaf use in Brazil (unlike Bolivia/Peru); coca leaf falls under cocaine-precursor prohibition and is illegal." } },
  BN: { n:"Brunei", def:'ill', st:{ can:'cap', mdma:'cap', ket:'med', ibo:'nodata', coc:'cap' }, nt:{ _:"Brunei runs one of the world's strictest drug-prohibition regimes under the Misuse of Drugs Act (Cap. 27), modeled on Singapore's. Cannabis is Class A (reclassified from B in 2013) and trafficking >500g carries the mandatory death penalty; CBD is illegal with no exceptions. Cocaine (>30g) and MDMA/ecstasy (>15g) also carry death-penalty trafficking thresholds, so they are coded 'cap'. Other psychedelics (psilocybin, LSD, DMT/ayahuasca, mescaline) and coca leaf are illegal and enforced with no medical/religious carve-out ('ill'). Ketamine is a registered hospital anaesthetic ('med', recreational use illegal). Ibogaine has no Brunei-specific data ('nodata'). Note: a de facto execution moratorium exists (no drug executions since 1957, sentences commuted), but criminal enforcement, caning and long custodial sentences are active, so capital/illegal codes reflect the law as applied. Confidence medium: high-level prohibition and capital thresholds are well-sourced, but exact per-substance schedule placement for some psychedelics is inferred from the Singapore-derived statute rather than read line-by-line from the official AGC PDF (which returned only binary/404).", can:"Class A under Misuse of Drugs Act (reclassified from B in 2013). Recreational & medicinal fully illegal; possession/use up to 10 yrs + caning. Trafficking >500g carries the MANDATORY DEATH PENALTY (presumption of trafficking at ~330-500g).", cbd:"No exception for CBD/hemp — cannabis derivatives are Class A regardless of THC content. Sale/possession/use illegal and enforced; no medical or wellness carve-out.", mdma:"Death penalty threshold: trafficking >15g of ecstasy/MDMA. Otherwise illegal and enforced.", dmt:"Class A controlled drug; no religious/ayahuasca exemption in this strict zero-tolerance Islamic state.", ket:"Registered medicine used as a hospital anaesthetic (licensed medical/veterinary use under the Act); recreational use illegal.", ibo:"No Brunei-specific data; not separately scheduled and no medical-access pathway in this prohibition regime.", coc:"Refined cocaine illegal; death penalty threshold for trafficking >30g.", coca:"Coca leaf illegal (Class A-type prohibition); no traditional/Andean use in SE Asia. De facto moratorium on executions exists (none for drugs since 1957) but criminal enforcement, caning and long sentences are real." } },
  BG: { n:"Bulgaria", def:'ill', st:{ cbd:'legal', ket:'med' }, nt:{ _:"Bulgaria has some of the strictest enforced drug laws in the EU. All scheduled controlled substances (cannabis, psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine, cocaine, coca leaf) are illegal and criminally enforced under the Law on Control of Narcotic Substances and Precursors (ZKNVP) and Penal Code Art. 354a, with no decriminalization and no personal-use threshold. Two exceptions: hemp-derived CBD (<0.2% THC) is legal and freely sold (treated as a traditional food since 2019), and ketamine is a registered medicine permitted for medical use (recreational use illegal). There is no medical cannabis program and no psychedelic clinical-access framework. Bulgaria (EU member) has abolished the death penalty and has no mandatory-life drug-trafficking sentence, so 'cap' does not apply.", can:"Illegal for recreational AND medical use; no decriminalization and notably no personal-use/threshold exemption — even small possession is a criminal offence (1-6 yrs, Penal Code Art. 354a). Medical cannabis not permitted as of 2025/2026.", cbd:"Legal — hemp-derived CBD (<0.2% THC) freely sold since 2019; Bulgaria classifies CBD as a 'traditional food' (not novel food), so no special license needed.", dmt:"DMT Schedule I; ayahuasca not named in law but illegal due to DMT content. No religious-use exemption.", ket:"Registered medicine with recognized medicinal value (Schedule III); legitimate medical use permitted, unauthorized/recreational use illegal (up to ~5 yrs).", coca:"No traditional/legal use; coca leaf falls under narcotic controls and is treated as illegal." } },
  BF: { n:"Burkina Faso", def:'ill', st:{ ket:'med' }, nt:{ _:"Burkina Faso maintains strict prohibition of narcotics and psychotropics under Law No. 017/99/AN (1999) / the Code des drogues, implementing the 1961 & 1971 UN conventions. Cannabis (incl. CBD) and all classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline) are illegal and enforced, with no medical, religious, or research exemptions; drug offences carry 10-20 year prison terms plus heavy fines. Refined cocaine and coca leaf are illegal; the country is a significant Sahel cocaine-transit hub. Ketamine is classed 'med' as an essential hospital anaesthetic. The death penalty was abolished in 2018; a December 2025 reinstatement bill targets only treason/terrorism/espionage, NOT drug offences, so 'cap' is not warranted. No 2024-2026 reforms toward liberalization were found.", can:"Illegal, no recreational/medical distinction; Code des drogues / Law 017/99/AN prohibits cultivation & use; penalties 10-20 yrs + fines, actively enforced.", cbd:"No legal distinction from cannabis; CBD/THC both treated as prohibited narcotic, no medical recognition.", ket:"Registered hospital medicine (essential anaesthetic in Sub-Saharan Africa, not internationally scheduled); recreational/non-medical use prohibited.", ibo:"Iboga/ibogaine non-native; no specific framework or medical access; falls under general controlled-substance prohibition.", coc:"Illegal; Burkina Faso is a major Sahel cocaine transit country (488 kg seized in 2022, largest in region).", coca:"Coca leaf non-native, no traditional use; controlled under 1961 Convention, illegal." } },
  BI: { n:"Burundi", def:'ill', st:{ ket:'med' }, nt:{ _:"Burundi maintains a prohibitionist drug regime under the UN drug-control conventions (ratified). Cannabis and CBD are fully illegal for recreational and medical use (fines + up to ~1 year prison; light but real enforcement). Psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, cocaine and coca leaf are all illegal controlled substances with no medical, religious, or decriminalization carve-outs (no Burundi entry in Psychedelic Alpha; ayahuasca/coca not traditional there). Ketamine is a registered essential medicine widely used as a hospital anaesthetic (med); recreational use illegal. Ibogaine has no approved therapeutic pathway and is treated as prohibited. The death penalty was abolished for all crimes in 2009, so no drug offence carries capital punishment ('cap' ruled out); maximum is imprisonment. Confidence is medium: cannabis/CBD and death-penalty abolition are well-sourced, while the harder drugs/psychedelics are inferred from convention membership and the absence of any reform or exemption rather than a directly readable Burundi scheduling list.", can:"Illegal for all uses (recreational and medical); possession penalties are fines and up to ~1 year prison, enforcement on personal use is inconsistent/light but the ban is enforced and police confiscate.", cbd:"Explicitly illegal, including hemp-derived zero-THC products; no regulated CBD market.", ket:"WHO essential medicine and the primary anaesthetic used across Sub-Saharan Africa; available for clinical/hospital use. Recreational use prohibited.", coc:"Refined cocaine is an illegal controlled substance; Burundi is a transit conduit but local use is low. No death penalty (abolished 2009).", coca:"Coca leaf is not traditional/native to Burundi and has no legal status; treated as a controlled narcotic." } },
  KH: { n:"Cambodia", def:'ill', st:{ can:'tol', psi:'tol', ket:'med' }, nt:{ _:"Cambodia prohibits all listed substances under its Law on the Control of Drugs (2012, amended 2020); cannabis, cocaine, MDMA, heroin, methamphetamine and ketamine are Group I narcotics. Crucially there is NO death penalty (abolished 1989, Constitution Art. 32) - so no 'cap' status; max penalty is life imprisonment for trafficking (>80g). Enforcement is real and intensifying (26,033 drug arrests in 2024, +30.5%; 14.7t seized incl. cocaine, ketamine, ecstasy), so most hard drugs are 'ill'. Two notable de-facto exceptions: recreational cannabis ('tol' - 'happy pizza' sold openly to tourists despite prohibition) and psilocybin mushrooms ('tol' - prohibited but unenforced in tourist zones). Ketamine is 'med' as a registered hospital anaesthetic (WHO essential medicine) while recreational use is illegal. CBD is legally unaddressed and folds into cannabis prohibition. Coca leaf, mescaline, DMT/ayahuasca and ibogaine have no Cambodia-specific exemptions and fall under the general prohibition ('ill'); ibogaine/coca/mescaline are inferred from the regime rather than named in sources (lower confidence).", can:"Group I narcotic, illegal on paper (2-5 yrs possession), but de-facto tolerated in tourist areas: 'happy pizza' parlours sell cannabis openly in Siem Reap & Phnom Penh as of 2024-25 despite a 2019-20 crackdown.", cbd:"No CBD/hemp program; legally unaddressed and falls under cannabis prohibition.", psi:"Magic mushrooms prohibited but largely unenforced/ignored in tourist areas (Wikipedia: 'Illegal (unenforced)').", lsd:"Prohibited under the controlled-substances regime; enforced.", mdma:"Illegal and enforced; 'ecstasy' among drugs actively seized in 2024 (26,033 drug arrests, +30.5%).", dmt:"Prohibited; no religious/ayahuasca exemption.", mes:"Prohibited; no peyote/San Pedro exemption.", ket:"Controlled but a registered hospital anaesthetic (WHO essential medicine) used in Cambodian surgery/emergency care; recreational use illegal and ketamine is a major illicit-trafficking target (tonnes seized 2022-24).", ibo:"No Cambodia-specific source; not separately scheduled but would fall under the general prohibitionist controlled-substances regime (low confidence).", coc:"Illegal and enforced; cocaine among 14.7 tonnes seized in 2024, foreign traffickers arrested.", coca:"No traditional use; would fall under narcotics prohibition (no exemption)." } },
  CM: { n:"Cameroon", def:'ill', st:{ ket:'med' }, nt:{ _:"Cameroon prohibits all internationally-scheduled drugs via Law No. 97/019 of 7 August 1997, which implements the three UN drug conventions. Cannabis (and CBD, not legally distinguished) is illegal for both recreational and medical use, classed as a 'high-risk drug', with penalties of 2-20 years (trafficking 10-20 yrs + fines up to 250M XAF). Psychedelics (psilocybin, LSD, MDMA, DMT, mescaline, ibogaine), cocaine and coca leaf all fall under the general narcotic/psychotropic prohibition with no documented religious, indigenous or pilot carve-outs. Ketamine is a registered, WHO-essential anaesthetic (medical use legal, recreational illegal). Cameroon has NO death penalty for drug offences — the widely-circulated 'Senate approves death penalty for drug traffickers' (May 2024) story is Nigeria's NDLEA Act amendment, not Cameroon. Enforcement of the 1997 law is real though reportedly inconsistent, so substances are 'ill' (enforced criminal offence) rather than merely tolerated.", can:"Illegal (recreational & medical) under Law No. 97/019 of 1997; classed as a 'high-risk drug', 2-20 yrs. Medical-cannabis legalization was proposed in 2001/2003 but never enacted.", cbd:"No legal distinction from cannabis; CBD is treated as illegal to use/buy/sell.", ket:"Registered anaesthetic and on WHO Essential Medicines List; critical for surgery in Sub-Saharan Africa. Medical use legal, recreational use illegal.", ibo:"No specific listing or exemption found; falls under the blanket psychotropic-substances prohibition. (Iboga/Bwiti tradition is native to neighbouring Gabon, not Cameroon.)", coc:"Refined cocaine is a controlled narcotic; trafficking 10-20 yrs + fines up to 250M XAF.", coca:"Coca leaf not native and has no traditional-use exemption; prohibited as a controlled narcotic." } },
  CA: { n:"Canada", def:'med', st:{ can:'legal', cbd:'legal', dmt:'decrim', mes:'decrim', coc:'ill', coca:'ill' }, nt:{ _:"Canada (2026): Cannabis and CBD are fully legal under the Cannabis Act. The classic psychedelics and dissociatives (psilocybin, LSD, MDMA, ketamine, ibogaine) remain scheduled but have genuine medical/clinical/research access pathways via Health Canada's Special Access Program and section 56(1) exemptions, so they are coded 'med'. DMT/ayahuasca and mescaline get 'decrim' due to religious (ayahuasca churches) and Indigenous (peyote statutory exemption) carve-outs. Cocaine and coca leaf are Schedule I and illegal/enforced — BC's drug-decriminalization pilot lapsed on Jan 31, 2026 without renewal, so there is no longer any sub-jurisdictional decrim of cocaine.", can:"Fully legal recreationally & medically since the Cannabis Act (2018); adults may possess up to 30g.", cbd:"Legal as a cannabis-derived product under the Cannabis Act; no prescription required for adults.", psi:"Schedule III, illegal for general use, but legal medical/research access via Health Canada's Special Access Program (SAP) and section 56(1) exemptions since 2022; SAP approvals declined sharply in 2025.", lsd:"Schedule III; illegal generally but accessible to authorized physicians/patients through the Special Access Program.", mdma:"Schedule I; illegal generally but available for psychedelic-assisted therapy via the Special Access Program / s.56 exemptions.", dmt:"DMT is Schedule III and illegal, but several ayahuasca churches operate legally under section 56(1) religious-freedom exemptions.", mes:"Mescaline is Schedule III, but peyote (Lophophora) is explicitly exempt from the CDSA ('but not peyote (lophophora)') for Indigenous/religious use; isolated mescaline and San Pedro extracts remain controlled.", ket:"Schedule I but a registered/approved medicine; ketamine-assisted therapy is legal when administered by licensed clinicians. Recreational use illegal.", ibo:"Schedule III; available as a regulated prescription drug via the Special Access Program (rarely approved). Iboga plant itself reportedly legal for personal possession.", coc:"Schedule I, illegal and enforced. BC's personal-possession decriminalization pilot (2.5g) expired Jan 31, 2026 and was not renewed; public-space possession had already been recriminalized in May 2024.", coca:"Coca leaf is prohibited under Schedule I; only a theoretical s.56 exemption exists and none has ever been granted." } },
  CF: { n:"Central African Republic", def:'ill', st:{ ket:'med' }, nt:{ _:"Central African Republic operates a blanket prohibitionist drug regime under its Penal Code: all narcotic and psychotropic substances are illegal, with penalties up to ~5 years imprisonment plus fines (100,000–1,000,000+ CFA francs). Cannabis and CBD are explicitly illegal for both recreational and medical use, though cannabis is the most widely cultivated/consumed illicit substance regionally with inconsistent enforcement in a fragile state. Psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine), refined cocaine, and coca leaf all fall under the blanket prohibition with no documented carve-outs (all 'ill'). Ketamine is treated as 'med' per its near-universal status as a registered anaesthetic in Sub-Saharan African hospitals. No death penalty for drug offences, so 'cap' was not assigned. Confidence is medium: cannabis/CBD are well-sourced, but other substances lack CAR-specific documentation and are inferred from the general prohibition framework and CAR's adherence to the UN drug conventions.", can:"Illegal for recreational and medical use under the Penal Code (up to ~5 yrs prison + fines). Most widely cultivated/consumed illicit drug in the region; de-facto widely used among young men despite prohibition, but remains a criminal offence with inconsistent enforcement.", cbd:"Banned; no THC/CBD distinction — CBD/hemp derivatives are forbidden alongside cannabis.", ket:"No CAR-specific source, but ketamine is a critical anaesthetic and registered hospital medicine across Sub-Saharan Africa; recreational use prohibited.", coc:"Illegal; CAR sits on regional cocaine-trafficking corridors. Penalties include long sentences and heavy fines, but no death penalty.", coca:"No traditional/indigenous use in Africa; falls under blanket narcotic prohibition." } },
  TD: { n:"Chad", def:'ill', st:{ ket:'med' }, nt:{ _:"Chad prohibits all controlled substances under a blanket narcotics framework with no medical, religious, or decriminalization carve-outs, and no reform efforts underway. Cannabis (and CBD, which is not legally distinguished) is illegal for both recreational and medical use; classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine), cocaine, and coca leaf are all illegal and enforced. Ketamine is treated as a registered medicine (recreational use illegal). Notably, Chad abolished the death penalty for ALL crimes in 2020, so no drug offence carries capital punishment — 'cap' does not apply. Confidence is medium because Chad publishes little detailed drug legislation, though the prohibitionist baseline and death-penalty abolition are well documented.", can:"Both recreational and medical cannabis fully illegal; possession of any drug taken seriously by police.", cbd:"No legal distinction between CBD/hemp and cannabis; CBD prohibited along with all cannabis products.", dmt:"No religious/indigenous exemption for ayahuasca; falls under blanket narcotic prohibition.", mes:"No peyote/San Pedro tradition (New World plants); covered by blanket prohibition.", ket:"Registered anaesthetic medicine (WHO Essential Medicines List); recreational use illegal. No evidence of special national scheduling.", coc:"Illegal and enforced; Chad is a transit corridor for cocaine moving through the Sahel toward Libya/Europe.", coca:"No traditional use; prohibited under narcotics law." } },
  CL: { n:"Chile", def:'decrim', st:{ can:'med', cbd:'med', ket:'med', coc:'ill' }, nt:{ _:"Chile schedules all listed substances under Ley 20.000 + DS 867, but Article 50 makes personal possession of ANY controlled drug for immediate use a non-criminal 'falta' (fine/education, never prison) — effectively decriminalizing personal possession across the board, while trafficking/micro-trafficking remains criminal (541 days-15 yrs). No death penalty. Cannabis is medical-legal (Rx since 2015) with decriminalized private cultivation; ketamine is a registered medicine; psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) are decrim at the personal-possession level with no formal religious/indigenous exemptions; refined cocaine is illegal/enforced; coca leaf (tea + indigenous traditional use) is tolerated/protected.", can:"Medical cannabis legal by prescription since 2015 (Ley 20.000 Decree 84); personal possession & private home cultivation (~6 plants) decriminalized via Art. 50 + consistent court precedent. Recreational sale/transport still illegal. Cannabis classed as 'hard drug' (2007 decree); a contested May 2026 reform could expose small quantities to trafficking penalties (challenged at Constitutional Court).", cbd:"Available as prescription cannabis-based medicine via authorized pharmacies; no clear OTC/low-THC carve-out, so coded med conservatively.", psi:"Scheduled in DS 867 ('grave effects' substance; mushrooms also listed as controlled plant), but personal possession for immediate use is a non-criminal 'falta' under Art. 50 of Ley 20.000 (fine/education, no prison).", lsd:"DS 867 controlled; personal possession a non-criminal falta under Art. 50. Trafficking 5-15 yrs.", mdma:"DS 867 controlled; personal possession a non-criminal falta under Art. 50.", dmt:"Ayahuasca/DMT controlled under DS 867; personal possession a falta under Art. 50. No formal Chilean religious/indigenous exemption (unlike Peru/Brazil).", mes:"Mescaline/peyote (and San Pedro) controlled under DS 867; personal possession a falta under Art. 50. No formal ceremonial exemption.", ket:"Registered/controlled medicine (Decree 416/2017); medical and veterinary use legal, recreational use illegal.", ibo:"Controlled under DS 867; personal possession a falta under Art. 50. No approved therapeutic program.", coc:"Refined cocaine illegal and enforced (use/sale/cultivation); personal possession technically a non-criminal falta under Art. 50, but trafficking 5-15 yrs. No death penalty in Chile.", coca:"Coca tea legally available; indigenous/traditional ceremonial coca-leaf use protected under indigenous-rights provisions. Distinct from refined cocaine (illegal)." } },
  CN: { n:"China", def:'ill', st:{ can:'cap', mdma:'cap', ket:'med', coc:'cap' }, nt:{ _:"China operates one of the world's strictest drug regimes (~449 controlled narcotics/psychotropics under the Ministry of Public Security/NMPA framework). Article 347 of the Criminal Law allows the death penalty for trafficking above threshold quantities, and China leads the world in drug-related executions (2024-2025). Cannabis, MDMA, cocaine and the classic narcotics are illegal, enforced, and carry genuine capital exposure for trafficking in quantity (coded 'cap'). Psilocybin, LSD, DMT/ayahuasca, mescaline, ibogaine and coca leaf are prohibited and enforced with no medical/decrim/religious pathway (coded 'ill'; capital application less documented for these low-volume substances). CBD is banned for consumer/cosmetic/food use (NMPA 2021 ban tightened by an Aug 2024 multi-department announcement), though industrial hemp fiber is permitted in Yunnan/Heilongjiang. Ketamine is the notable exception: a Category I psychotropic that is also a registered medicine (anesthetic; esketamine nasal spray approved April 2023 for depression with acute suicidality), so it is coded 'med' with recreational use illegal. Confidence medium: cap-vs-ill boundary is a judgment call, and ibogaine's exact scheduling is unconfirmed.", can:"Illegal and enforced; no medical program. Trafficking >=50g cannabis resin or >=10kg herbal cannabis can carry the death penalty under Art. 347 of the Criminal Law.", cbd:"Banned for consumer/cosmetic/food use (NMPA 2021 ban; Aug 2024 six-department announcement tightened controls). Industrial hemp fiber/seed cultivation permitted only in Yunnan/Heilongjiang; CBD products themselves illegal domestically.", mdma:"Controlled psychotropic, illegal and enforced; trafficking in quantity can reach capital thresholds under Art. 347. China leads the world in drug-related executions (2024-2025).", ket:"Category I psychotropic and a registered medicine: used as an anesthetic, and esketamine nasal spray was approved April 2023 for depression with acute suicidality (administered only in authorized institutions). Recreational ('K powder') use is illegal and enforced.", ibo:"No specific Chinese listing confirmed and no medical approval or access pathway; treated as a prohibited psychoactive. Lower confidence on exact scheduling.", coc:"Narcotic, illegal and strictly enforced; trafficking can carry the death penalty under Art. 347 (1g street value ~USD 1,000, reflecting severe penalties).", coca:"No traditional/indigenous use; coca leaf treated as a controlled narcotic. Illegal and enforced." } },
  CO: { n:"Colombia", def:'decrim', st:{ can:'med', cbd:'med', ket:'med', ibo:'ill', coc:'ill', coca:'legal' }, nt:{ _:"Colombia (2026): Medical cannabis legal & regulated since 2016 with a 2025 draft decree to allow prescription psychoactive flower; CBD regulated similarly (both 'med'). Personal possession of narcotics is decriminalized under Constitutional Court C-221/1994 ('dosis personal', e.g. 20g cannabis, 1g cocaine), so personal-use LSD, MDMA, psilocybin and mescaline are not criminally prosecuted ('decrim'); natural psilocybin mushrooms and San Pedro cacti are unscheduled. Ayahuasca/yagé is uncriminalized and constitutionally protected as Indigenous ancestral medicine. Ketamine is a registered medicine ('med'). Refined cocaine is illegal and trafficking heavily enforced ('ill', despite a <=1g personal carve-out); coca leaf enjoys protected traditional/Indigenous legal status ('legal'). Ibogaine has no recognized framework and is coded conservatively as illegal (lowest certainty).", can:"Medical cannabis fully legal & regulated since 2016 (cultivation, processing, export); recreational not legal but personal possession up to 20g decriminalized via Constitutional Court C-221/1994. A 2025 draft Justice Ministry decree would let pharmacies dispense prescription psychoactive flower.", cbd:"Regulated under the medical-cannabis / INVIMA framework; CBD wellness and cosmetic products available.", psi:"Magic mushrooms in natural/unprocessed form (incl. spores, mycelium) are not specifically scheduled; personal possession protected under the 'dosis personal' doctrine. Gray area — cultivation/processing for sale can be prosecuted.", lsd:"Controlled under Law 30/1986, but small personal-use possession is decriminalized (not criminally prosecuted) under the Constitutional Court 'free development of personality' doctrine; trafficking remains illegal.", mdma:"Controlled substance under Law 30/1986; personal-dose possession decriminalized like other narcotics, trafficking illegal. Some discussion of future medical/research framework.", dmt:"Ayahuasca/yagé never criminalized; protected as ancestral indigenous medicine under the 1991 Constitution (arts. 7 & 246). Colombia has the world's highest per-capita ayahuasca use.", mes:"San Pedro (Echinopsis) cacti grow and are sold openly and are not scheduled; isolated mescaline is controlled but personal use falls under the personal-dose protection.", ket:"Registered medicine/anaesthetic; legally available under medical supervision (INVIMA), recreational use illegal.", ibo:"Not specifically regulated and no recognized medical/therapeutic framework; treated under general narcotics control — coded conservatively as illegal (low certainty).", coc:"Refined cocaine illegal; production/trafficking heavily enforced with long sentences. Possession of <=1g for personal use is decriminalized (administrative, not criminal).", coca:"Coca leaf has a protected dual status: traditional cultivation, chewing, tea and products by/for Indigenous peoples are legal under Law 30/1986 art.7 and the 1991 Constitution; roasted leaves and coca-based wellness products sold openly." } },
  CR: { n:"Costa Rica", def:'decrim', st:{ can:'med', cbd:'legal', ket:'med', coca:'ill' }, nt:{ _:"Costa Rica's Law 8204 (2001) does not criminalize personal drug consumption for ANY substance — police may confiscate small amounts but use itself is not an offence — while production/sale/trafficking carries 8-15 years (up to 20 for organized/international crime). This makes most prohibited drugs effectively 'decrim' at the personal level. Medical cannabis is legal (Law 10113, 2022; RTCR 515:2024); hemp/CBD legal with registration; ketamine is a registered medicine. Ayahuasca/ibogaine are unscheduled and retreats operate openly, but a Jan 2025 Ministry of Health advisory warns they are not authorized for therapeutic use. Coca leaf has no traditional/legal carve-out and is treated as prohibited.", can:"Medical cannabis legal since Law 10113 (March 2022), regulated via RTCR 515:2024 (in force 2025); prescription THC products in licensed pharmacies. Recreational illegal but personal consumption is not a punishable offence under Law 8204; sale/cultivation = 8-15 yrs. 2024 bill to legalize regulated adult cannabis still pending.", cbd:"Hemp (<1% THC) and CBD products legal with sanitary registration under the medical-cannabis/hemp framework.", psi:"Controlled/scheduled; trafficking 8-15 yrs, but personal consumption not criminalized under Law 8204. De-facto tolerated gray area — psychedelic-retreat tourism boom, no known mushroom arrests.", lsd:"Scheduled controlled substance; sale/possession-for-supply 8-15 yrs, but personal consumption not punished under Law 8204.", mdma:"Scheduled controlled substance; trafficking 8-15 yrs, personal consumption not criminalized.", dmt:"Ayahuasca effectively unscheduled and retreats operate openly, but Ministry of Health advisory (28 Jan 2025) warns it lacks sanitary registration and is NOT authorized for therapeutic use. Personal use not criminalized; commercial ceremonies risk trafficking charges.", mes:"San Pedro/peyote mescaline controlled; personal consumption not punished under Law 8204, commerce criminalized. Cactus widely available; gray area.", ket:"Added to Drug Surveillance Council controlled list (2015/2017); registered anesthetic medicine available by prescription. Non-medical use illegal.", ibo:"Subject of Ministry of Health advisory (28 Jan 2025): lacks sanitary registration, not authorized for therapeutic use despite addiction-treatment clinics operating. Personal use not criminalized.", coc:"Refined cocaine is a scheduled drug; trafficking 8-15 yrs (up to 20 organized/international). Personal consumption itself not a criminal offence under Law 8204, but no legal access.", coca:"Coca leaf not indigenous to Costa Rica and treated as a prohibited cocaine-source plant under Law 8204; no traditional-use or legal-access carve-out. Trafficking penalized." } },
  HR: { n:"Croatia", def:'decrim', st:{ can:'med', cbd:'legal', ket:'med' }, nt:{ _:"Croatia operates a blanket decriminalization of personal drug possession (since 2013): possession of small amounts of ANY controlled substance — cannabis, psychedelics, cocaine, heroin alike — is an administrative misdemeanour (fine ~EUR130-2,650, possible treatment), not a criminal offence, with no soft/hard-drug distinction. Supply, cultivation, and trafficking remain serious crimes (up to 12-15 years). Hence cannabis, psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine, cocaine, and coca leaf are all coded 'decrim' (illegal on paper, personal possession decriminalized). CBD is fully 'legal' — cannabis sativa was struck from the narcotics list in 2019 and CBD <0.2% THC sells as a regulated food supplement. Ketamine is 'med' (registered medicine; non-medical use illegal). Medical cannabis has been prescription-legal since 2015 with a domestic-production pathway opening in 2025, but real patient access stayed minimal. Note: some low-authority sources claim a sweeping 2026 'Drug Reform Act' (e.g. a 5g cannabis threshold, state-regulated market); this is not corroborated by authoritative sources (EUDA, Prohibition Partners, Wikipedia) and was treated cautiously, lowering overall confidence.", can:"Personal possession decriminalized since 2013 (administrative misdemeanour, fine ~EUR130-2,650, possible mandatory treatment); recreational sale/cultivation still a serious crime. Medical cannabis legal by specialist prescription since 2015, though domestic supply remained negligible into 2025 with a domestic-production framework opening in 2025.", cbd:"Cannabis sativa L. removed from the narcotics list in a 2019 amendment; CBD <0.2% THC sold legally as food supplement/cosmetic, regulated by Ministry of Agriculture rather than treated as a drug.", psi:"Illegal substance but personal possession decriminalized under Croatia's blanket personal-use misdemeanour scheme (fine, not criminal). Sale/cultivation criminal.", lsd:"Illegal but personal possession decriminalized (administrative fine).", mdma:"Illegal but personal possession decriminalized (administrative fine).", dmt:"DMT/ayahuasca illegal with no religious exemption; personal possession decriminalized like all drugs.", mes:"Controlled; personal possession decriminalized under the substance-agnostic personal-use scheme.", ket:"Registered medicine/anaesthetic, legal for medical use; non-medical use illegal (personal possession falls under the decriminalized misdemeanour scheme).", ibo:"Controlled; no approved therapeutic use. Personal possession would fall under Croatia's blanket decriminalization of personal use (lower confidence on explicit scheduling).", coc:"Croatia makes NO legal distinction between soft and hard drugs for personal possession: since 2013 personal possession of any drug, incl. cocaine, is a decriminalized misdemeanour (fine). Trafficking remains heavily penalized (up to 12-15 yrs) and enforcement is real.", coca:"Coca leaf controlled with no traditional/legal use in Croatia; personal possession falls under the same blanket decriminalization. Effectively absent from the country." } },
  CU: { n:"Cuba", def:'ill', st:{ ket:'med' }, nt:{ _:"Cuba (Penal Code Law No. 151 of 2022) operates one of the strictest drug-control regimes in the region. All listed substances are illegal and actively enforced, with no medical-cannabis, psychedelic-therapy, or research carve-outs and no decriminalization thresholds. Possession draws ~6 months-2 years; cultivation/trafficking 4-30 years. Aggravated trafficking retains the death penalty on paper, but application is classified as 'symbolic' (commuted in practice, no recent executions), so substances are coded 'ill' rather than 'cap'. Ketamine is the lone exception as a registered hospital anesthetic ('med'); recreational use remains illegal. No indigenous/religious exemptions exist for ayahuasca, peyote, or coca leaf.", can:"Illegal for both recreational and medical use; no medical cannabis program, no decriminalization threshold. Possession typically 6 months-2 years prison.", cbd:"No legal distinction from cannabis; treated as a prohibited cannabis product. No CBD/cannabinoid medicines (Sativex/Epidyolex) available.", dmt:"No religious/indigenous ayahuasca exemption; covered by blanket narcotics/psychotropics prohibition.", mes:"No peyote/San Pedro tradition or exemption; prohibited under blanket drug law.", ket:"Registered anesthetic used in Cuban hospital/trauma/emergency care; recreational use illegal.", coc:"Illegal and actively enforced; 2025 Havana cases gave up to 20-year sentences for cocaine trafficking.", coca:"No traditional/indigenous coca use in Cuba; treated as an illegal narcotic." } },
  CY: { n:"Cyprus", def:'ill', st:{ cbd:'legal', ket:'med' }, nt:{ _:"Cyprus (EU member) regulates drugs under the Narcotic Drugs and Psychotropic Substances Law of 1977 with a three-class A/B/C system; no death penalty (max life imprisonment for trafficking). Classic psychedelics (LSD, psilocybin, MDMA, DMT, mescaline), cocaine, coca leaf and ibogaine are all controlled, illegal and enforced. CBD is legal as a low-THC hemp supplement (0.3% THC cap since 2024). Ketamine is a registered medicine ('med'). Recreational cannabis is firmly illegal (Class B); medical cannabis exists on paper since 2017 but lacks a working patient-access framework.", can:"Recreational cannabis is Class B, illegal and enforced (fines EUR400-1000 for first offence, up to 8 yrs prison; up to life for trafficking). Medical cannabis legal on paper since 2017 (expanded 2019) but no functioning patient-access framework: only via exceptional Ministry of Health approval, so de-facto access is minimal and many patients get prescriptions in Greece instead.", cbd:"Legal/regulated as a hemp-derived dietary supplement; THC limit raised from 0.2% to 0.3% (dry weight) by a 2024 amendment, aligning with EU standards. Sold in shops/pharmacies, though enforcement has been inconsistent (occasional shop raids/seizures).", dmt:"DMT/ayahuasca controlled (Class A); no religious or indigenous-use exemption in Cyprus.", ket:"Registered/used as a medical anaesthetic; ketamine-assisted protocols (incl. ketamine + rTMS) are in clinical use in Cyprus. Recreational use illegal.", coca:"Coca leaf controlled as a narcotic; no traditional/religious or legal use in Cyprus." } },
  CZ: { n:"Czechia", def:'decrim', st:{ cbd:'legal', psi:'med', ket:'med', coca:'ill' }, nt:{ _:"Czechia is one of Europe's most liberal drug-policy jurisdictions. Since 2010 (Govt Reg. 467/2009) possession of small personal amounts of ALL illicit drugs is a decriminalized administrative offense, not a crime, with set thresholds (cannabis 15g, cocaine 1g, MDMA ~4 tabs/2g, LSD ~5 tabs, mushrooms ~40 pieces). Two 2026 reforms stand out: adult-use cannabis (home-grow + personal possession, no retail) effective 1 Jan 2026, and medical psilocybin (clinical, psychiatrist-administered) also effective 1 Jan 2026. CBD/low-THC (≤1%) is legal with licensed retail since mid-2025. Ketamine is a registered medicine (pioneering ketamine-assisted therapy). Refined cocaine and most psychedelics are illegal-on-paper but personal possession is decriminalized; coca leaf has no exemption and is illegal.", can:"Adult-use legalization effective 1 Jan 2026: adults 21+ may home-grow up to 3 plants and possess 100g at home / 25g in public, but NO commercial sales/clubs. Personal possession decriminalized since 2010 (up to 15g = administrative offense). Borderline legal-for-personal-use; coded decrim because there is no legal retail market.", cbd:"Legal. Hemp up to 1% THC permitted since 2022 (one of EU's most liberal limits); Psychomodulatory Substances Act (eff. 1 Jul 2025) created licensed adult-use (18+) retail for CBD and low-THC products.", psi:"Medical use of (synthetic) psilocybin approved Dec 2025, effective 1 Jan 2026, for treatment-resistant depression and end-of-life/palliative care; administered only by specially certified psychiatrists in clinical sessions. Recreational use and home cultivation remain prohibited (personal possession up to ~40 mushrooms is a decriminalized administrative offense).", lsd:"Illegal but personal possession (up to ~5 tabs) is a decriminalized administrative offense since 2010. Research/clinical use permitted under protocol (e.g. Psyon clinic).", mdma:"Illegal but personal possession (<2g / up to ~4 tablets) is a decriminalized administrative offense. Phase 2 MDMA-assisted therapy for PTSD trials ongoing at the Centre for Psychedelic Research.", dmt:"Illegal; small personal amounts decriminalized (administrative offense) under the general 2010 scheme. No specific religious/ayahuasca exemption.", mes:"Illegal; small personal amounts decriminalized (administrative offense) under the general 2010 scheme.", ket:"Registered prescription medicine (anaesthetic); Czechia was the first European country to offer ketamine-assisted psychotherapy (2020). Recreational use illegal, personal possession decriminalized.", ibo:"Genuinely uncertain scheduling; not specifically listed as a controlled narcotic. Personal possession of controlled substances is broadly decriminalized, but real-world access status is unclear — low confidence.", coc:"Refined cocaine illegal, but personal possession up to ~1g is a decriminalized administrative offense (not a crime) under Govt Regulation 467/2009.", coca:"Coca leaf illegal — no traditional/cultural use; falls under cocaine-related narcotics controls." } },
  CD: { n:"Democratic Republic of the Congo", def:'ill', st:{ ket:'med' }, nt:{ _:"DRC's 27 Feb 2021 narcotics law authorizes narcotics/psychotropics only for medical, educational and scientific purposes; all other use is prohibited. Cannabis is legal for medical/scientific/industrial use (first licences issued) but recreational use is illegal; CBD follows cannabis. Ketamine is an essential medicine (med). All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) and both refined cocaine and coca leaf are illegal with no decrim or traditional-use exemptions. Drug offences in military facilities during wartime can carry the death penalty, and DRC lifted its 2003-2024 execution moratorium in March 2024, but the general drug-trafficking offence is coded 'ill' (conservative) since the capital provision is narrow and no executions have occurred. Confidence medium: framework is clear for cannabis/CBD/ketamine, but DRC-specific scheduling detail for individual psychedelics is sparse and inferred from the blanket prohibition.", can:"Medical/scientific/industrial cannabis legalized by the 27 Feb 2021 narcotics law; first cultivation/export licence issued (TMIG/Instadose). Recreational use remains illegal (local name 'bangi'); widely cultivated/used in the east, enforcement not a priority but possession can carry severe penalties.", cbd:"No separate CBD regime; treated as cannabis. Permitted only under the medical/scientific framework, otherwise prohibited.", psi:"No carve-out; covered by the general narcotics/psychotropics prohibition (medical/scientific/educational use only).", ket:"Essential medicine and a critical (often the only) anaesthetic in DRC/sub-Saharan Africa; available for medical use. Non-medical use prohibited under the controlled-substances law.", coc:"Refined cocaine prohibited. Note: drug trafficking/possession in military facilities during wartime can carry the death penalty; DRC lifted its 2003-2024 death-penalty moratorium in March 2024, but no executions carried out yet.", coca:"Coca leaf has no traditional/legal exemption in DRC; prohibited like other narcotics." } },
  DK: { n:"Denmark", def:'ill', st:{ can:'med', cbd:'legal', ket:'med', ibo:'med' }, nt:{ _:"Denmark prohibits recreational cannabis and all classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) and refined cocaine/coca leaf under the Act on Euphoriant Substances, with enforcement that has tightened since 2004. List A substances (e.g. LSD, psilocybin) are deemed to have no therapeutic use and cannot be in Denmark at all. The June 2024 charge-waiver law and the Vesterbro drug consumption room are harm-reduction non-enforcement for dependent users, NOT decriminalization, so personal possession remains a criminal offence on paper and in practice. Medical exceptions: ketamine (registered medicine) and ibogaine (List B, prescription + special Ministry of Health permission) qualify as 'med'. CBD is legal under THC thresholds. Medical cannabis became permanent (April 2025, pharmacy/GP access from Jan 2026) but the recreational/general cannabis item stays illegal. No death-penalty or long mandatory-minimum regime applies.", can:"Recreational cannabis illegal and enforced; possession fined under Act on Euphoriant Substances. Medical cannabis programme made permanent (law April 2025); from Jan 2026 accessible via GPs/pharmacies for conditions like MS, chronic pain, chemo side-effects — but the general/recreational item remains illegal.", cbd:"CBD/industrial hemp products legal if THC stays under threshold (~0.2%) and meets safety standards.", psi:"List A (no recognized therapeutic use), illegal. Clinical trials underway at Aalborg University Hospital and Rigshospitalet, but no approved patient access.", lsd:"List A, illegal and enforced; possession up to ~2 years prison.", mdma:"Illegal and enforced (up to ~2 years prison); research interest but no approved access.", dmt:"Illegal. Danish High Court ruled ayahuasca importation illegal and religious/sacramental use NOT protected under religious-freedom law.", mes:"Mescaline, peyote and San Pedro all illegal.", ket:"Registered medicine, available by prescription/referral; recreational use illegal.", ibo:"List B — controlled but obtainable by prescription with special permission from the Ministry of Health for medical use.", coc:"Controlled euphoriant; illegal and enforced, treated as a 'hard drug' (stricter than cannabis). June 2024 law allows charge waivers for dependent users with social conditions = selective non-enforcement, not decriminalization.", coca:"No traditional/legal use; controlled as a euphoriant substance, illegal." } },
  DJ: { n:"Djibouti", def:'ill', st:{ ket:'med', coc:'cap' }, nt:{ _:"Djibouti runs a strict zero-tolerance drug regime under Law 3/1993 (Control of Illicit Trafficking in and Abuse of Narcotics and Psychotropic Substances), which explicitly provides the death penalty for narcotics import/export/manufacture with trafficking intent (hence 'cap' for refined cocaine, the classic trafficked narcotic — though Djibouti is abolitionist in practice). Cannabis and CBD are fully illegal with no medical/CBD carve-out (possession months-to-years, trafficking up to life). Psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine and raw coca leaf have no specific carve-outs and fall under the blanket prohibition, so are classed 'ill' conservatively (no evidence of decrim, religious/indigenous exemptions, or medical programs). Ketamine is a registered anaesthetic medicine ('med'), with recreational use prohibited. Confidence medium: cannabis/CBD and the death-penalty statute are well documented, but per-substance scheduling for individual psychedelics is inferred from the general controlled-substances framework rather than substance-specific sources.", can:"Illegal for all purposes incl. medical; possession ~6 months-3 yrs, cultivation 5-10 yrs, trafficking up to life imprisonment. Local use low (khat preferred); port is a transit hub.", cbd:"No legal distinction from cannabis; CBD illegal to use/buy/sell.", psi:"No specific program; prohibited under the general controlled-substances regime.", lsd:"No specific program; prohibited under the general psychotropic-substances regime.", mdma:"No specific program; prohibited under the general psychotropic-substances regime (Law 3/1993).", ket:"Registered anaesthetic medicine; Djibouti reports controlled-medicine consumption to INCB. Recreational use prohibited.", coc:"Refined cocaine treated as a trafficked narcotic. Law 3/1993 on narcotics/psychotropics mandates the death penalty for import/export/manufacture with trafficking intent, so trafficking can carry capital punishment (though Djibouti is abolitionist in practice).", coca:"No traditional use; falls under blanket narcotic prohibition, illegal." } },
  DO: { n:"Dominican Republic", def:'ill', st:{ ket:'med' }, nt:{ _:"Dominican Republic is strictly prohibitionist under Law 50-88 (1988). All listed substances except ketamine are illegal and actively enforced as Schedule I / controlled drugs, with no medical-cannabis, CBD, ayahuasca/religious, or psychedelic-therapy exemptions and no decriminalized personal-use threshold (possession is not distinguished from trafficking). Ketamine is classed 'med' as a registered anaesthetic (recreational use illegal), inferred from the global norm absent a DR-specific source. The death penalty was abolished in 1969 (DR acceded to ICCPR-OP2), so 'cap' is not warranted despite long mandatory prison terms for trafficking.", can:"Illegal & enforced under Law 50-88; no medical cannabis, no THC/CBD distinction. Possession <20g = min 6 months prison. 2021 medical-cannabis bill never passed.", cbd:"Treated as a cannabis product under Law 50-88 with no carve-out; technically illegal regardless of THC content.", dmt:"DMT/ayahuasca is Schedule I; no religious/indigenous exemption (unlike Peru/Brazil), no ayahuasca-tourism industry.", ket:"No DR-specific statute found; inferred 'med' from global norm (registered anaesthetic, not in prohibited Schedule I tier). Recreational use illegal. Lower confidence.", ibo:"Schedule I; Ministry of Public Health doesn't recognize iboga as medicine. No 'wellness-retreat' loophole (contrast Mexico/Costa Rica) despite clinic-marketing sites.", coc:"Refined cocaine illegal and heavily enforced (tens of tons seized annually). Death penalty abolished 1969, so no 'cap'.", coca:"No traditional/indigenous coca use in the DR; falls under general Law 50-88 narcotics prohibition." } },
  TL: { n:"East Timor", def:'ill', st:{ ket:'med' }, nt:{ _:"Timor-Leste prohibits illicit drugs under a national anti-drug-trafficking law (approved Oct 2016, promulgated 2017) layered on the UN 1961/1971/1988 conventions; prohibition is enforced (3.5-yr sentence for cannabis possession, 2017). Cannabis (recreational + medical) and any CBD/medicinal-marijuana product are explicitly illegal, with no carve-out. Psychedelics (psilocybin, LSD, DMT, mescaline), MDMA, ibogaine, cocaine and coca leaf are all illegal as UN-scheduled substances; no religious/indigenous ayahuasca or peyote exemption exists. Ketamine is treated as a registered medical anaesthetic (med). The death penalty is constitutionally abolished, so drug offences cannot carry capital punishment ('cap' ruled out). Confidence is medium: the prohibition/enforcement and death-penalty facts are well-sourced, but substance-specific scheduling (psychedelics, ketamine, coca) is inferred from adopted UN conventions and the blanket ban rather than a published national drug schedule, and Timor-Leste is absent from the Psychedelic Alpha tracker.", can:"Recreational and medical cannabis both illegal and enforced; an Australian was sentenced to 3.5 years for possession (Dili District Court, 2017). Pres. Ramos-Horta called for reform in 2022 but no change.", cbd:"No CBD/medical-cannabis carve-out; production, sale and possession of any form of medicinal marijuana product is explicitly illegal.", mdma:"Listed among common illicit drugs in Timor-Leste; prohibited under the anti-drug-trafficking law / UN conventions.", dmt:"No religious/indigenous ayahuasca exemption; prohibited as a UN-scheduled substance.", ket:"Treated as a registered medical anaesthetic (WHO Essential Medicine, widely used in low-resource settings); non-medical use falls under the drugs prohibition.", coca:"No Andean tradition; would be treated as a controlled narcotic plant — inferred from blanket prohibition (not separately documented)." } },
  EC: { n:"Ecuador", def:'decrim', st:{ cbd:'med', ket:'med', coca:'ill' }, nt:{ _:"Ecuador's Constitution (Art. 364) and COIP treat personal drug consumption as a public-health matter and bar criminalization of users; the National Court (Resolution 14-2023) confirmed personal-use possession remains non-punishable even after Noboa repealed the 2013 quantity table in Nov 2023. So personal possession of essentially all controlled substances (cannabis, psilocybin, LSD, MDMA, DMT, mescaline, cocaine) is decriminalized, while sale/trafficking is firmly illegal. Medical cannabis/CBD has been legal and ARCSA-regulated since 2019 (CBD <1% THC in pharmacies). Ayahuasca and San Pedro enjoy a traditional/indigenous-ceremony carve-out. Ketamine is a registered medicine. Coca leaf has no traditional-use protection in Ecuador (unlike Bolivia/Peru) and is treated as illegal. No death penalty for drug offences. Confidence is medium because the post-2023 legal vacuum makes personal-possession enforcement case-by-case, and ibogaine's status is inferred from the general framework rather than an explicit listing.", can:"Recreational regime rolled back Nov 2023 (Noboa repealed the personal-use quantity table); no legal recreational market. But personal consumption remains non-criminalized under Constitution Art. 364 and COIP (Natl. Court Resolution 14-2023, still in force 2024) — courts decide personal-use vs. trafficking case-by-case. Hence decrim, not ill.", cbd:"Medical cannabis legalized Sept 2019; ARCSA-regulated. CBD products <1% THC sold in pharmacies by prescription for epilepsy, chronic pain, etc.", psi:"Schedule I (Law 108); personal possession decriminalized under Art. 364 framework; sale illegal. Spores/grow kits not covered by law.", lsd:"Personal possession decriminalized (Psychedelic Alpha lists a permissible personal amount); sale/trafficking illegal.", mdma:"Personal possession decriminalized (permissible personal amount historically ~0.015 g); sale/trafficking illegal.", dmt:"Ayahuasca use protected for traditional indigenous/shamanic ceremony; DMT possession for personal use decriminalized; commercial/paid retreats are legally grey. NB: no death penalty for drugs in Ecuador (abolished; trafficking max ~10-13 yrs), so 'cap' applies to no substance.", mes:"San Pedro/mescaline permitted in traditional indigenous shamanic ceremonies; personal possession decriminalized.", ket:"Registered medicine (anesthetic / analgesia); recreational use illegal.", ibo:"No specific Ecuador listing; not on INCB green list. Falls under general non-criminalization of personal possession; no enforced ban and no formal medical-approval framework found — low confidence.", coc:"Refined cocaine is a controlled narcotic and trafficking is heavily prosecuted (Ecuador is a major cocaine transit country). However, personal possession of small amounts remains non-criminalized under Art. 364/COIP (the 2013 table listed 1 g cocaine HCl); confirmed still in force 2024 — hence decrim for personal possession, not ill.", coca:"Unlike Bolivia/Peru, Ecuador has no recognized traditional coca-leaf protection; little/no cultivation and plants are eradicated on discovery. Treated as a controlled narcotic plant." } },
  EG: { n:"Egypt", def:'ill', st:{ can:'cap', ket:'med' }, nt:{ _:"Egypt has one of the world's strictest drug regimes under Anti-Narcotics Law No. 182/1960 (amended 1989; 2019 amendment added synthetic drugs to capital offences). All listed psychedelics (LSD, psilocybin, mescaline, DMT, MDMA), cannabis, CBD, cocaine and coca leaf are illegal and actively enforced, with no medical-cannabis or psychedelic-therapy access. Ketamine is the lone exception: a registered, clinically-used medicine (med). Trafficking/cultivation/import of narcotics genuinely can carry the death penalty or life with hard labor — a severe-penalty regime flagged in the notes rather than coded 'cap' per the conservative per-substance convention (personal-use/patient exposure is enforced criminal prosecution). Ibogaine and coca leaf lack explicit Egypt-specific listings but fall under the broad prohibition, hence lower confidence on those two.", can:"Illegal and actively enforced under Anti-Narcotics Law No. 182/1960 (incl. hashish, bango, resin). Personal possession: min. 1 yr prison + fine. Cultivation/import/trafficking (Art. 33) can carry the DEATH PENALTY. No medical-cannabis program.", cbd:"No hemp/THC distinction in Egyptian law; CBD treated identically to cannabis = illegal to possess, sell or import. Even low-/zero-THC products are prohibited; import can be charged as a trafficking offence.", psi:"Hallucinogen, illegal and enforced; no decriminalization or medical/research access.", lsd:"Hallucinogen, illegal and enforced; no medical/research access.", mdma:"Schedule-1 style prohibition; no medical/therapeutic pathway. 2019 amendment expressly added death penalty for import/export of harmful synthetic substances. Illegal and enforced.", dmt:"Classic hallucinogen, Schedule-1 style prohibition under Law 182/1960; no religious/ayahuasca exemption. Illegal and enforced.", mes:"Mescaline (peyote/San Pedro) treated as a prohibited hallucinogen; no traditional/indigenous exemption in Egypt.", ket:"Controlled medicine, used clinically (referenced in Egyptian psychiatric guidelines for treatment-resistant depression). Recreational use illegal; tightly restricted at borders (listed among prohibited drugs at Cairo Airport).", ibo:"No Egypt-specific listing located, but no legal medical pathway exists and it falls under broad narcotics prohibition; treated as illegal (lower confidence).", coc:"Illegal and enforced. Limited domestic market (transit from Libya). Trafficking can carry life imprisonment or the death penalty under Law 182/1960 as amended.", coca:"No traditional/indigenous use; coca leaf treated as a prohibited narcotic under Law 182/1960. Illegal (lower confidence on explicit scheduling)." } },
  SV: { n:"El Salvador", def:'ill', st:{ dmt:'tol', ket:'med' }, nt:{ _:"El Salvador maintains a blanket drug prohibition (Ley Reguladora de las Actividades Relativas a las Drogas / Decreto 728) with no decriminalization of personal possession and no medical-cannabis, CBD, or psychedelic-therapy programs. Cannabis, CBD, psilocybin, LSD, MDMA, mescaline, ibogaine, cocaine, and coca leaf are all illegal and enforced as criminal offences. Ketamine is available as a registered clinical anesthetic (med). DMT/ayahuasca is illegal on paper but ayahuasca retreats reportedly operate in a de-facto-tolerated grey area with no formal religious exemption (coded tol). The death penalty was abolished for ordinary crimes in 1983, so drug trafficking is not capital despite long mandatory-style sentences — hence no 'cap' code, though penalties are severe.", can:"Illegal and enforced under the Ley Reguladora de las Actividades Relativas a las Drogas (Decreto 728); no medical or recreational program. Possession <2g = 1-3 yrs prison; >=2g = 3-6 yrs; intent to distribute 6-10 yrs. Among the strictest cannabis regimes in Central America.", cbd:"No CBD/hemp carve-out; law makes no distinction between cannabis and CBD, so CBD is treated as illegal cannabis. No legal pharmacy sale.", dmt:"DMT/pure forms illegal under the blanket drug law, but ayahuasca ceremony/retreats reportedly operate in an unregulated de-facto-tolerated grey area; no formal religious/indigenous exemption exists (El Salvador is not listed among ayahuasca-exemption countries).", ket:"Registered anesthetic medicine (WHO Essential Medicines list), used clinically; recreational/non-medical use prohibited.", coc:"Illegal and enforced; long prison sentences for possession/trafficking. Note: death penalty abolished for ordinary crimes (1983 Constitution), so trafficking is NOT capital despite harsh sentencing.", coca:"No Andean traditional-use exemption; coca leaf falls under the general prohibition like other controlled substances." } },
  GQ: { n:"Equatorial Guinea", def:'ill', st:{ can:'tol', ket:'med', ibo:'decrim' }, nt:{ _:"Equatorial Guinea has a blanket Drug Control Law criminalizing manufacture, trafficking, distribution and possession of controlled substances with severe penalties (long prison terms and heavy fines). The death penalty was abolished in the September 2022 penal code, so no drug offence carries capital punishment (not 'cap'). Cannabis is illegal on paper for both medical and recreational use but is de-facto tolerated/unenforced (no arrests or convictions in living memory; culturally embedded) → 'tol'. Classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) and refined cocaine and coca leaf have no special framework and fall under general prohibition → 'ill'. EG does not appear in the Psychedelic Alpha tracker. Ketamine is treated as a registered medicine per global norm → 'med'. Iboga/ibogaine is the notable exception: native to Central Africa with documented Bwiti ceremonial use among EG's Fang and no specific scheduling, so indigenous/traditional use is effectively unregulated → 'decrim' (low confidence; not legally protected as in neighbouring Gabon). Overall confidence is low because EG-specific primary legal sources are scarce and most non-cannabis classifications are inferred from the general narcotics statute plus regional/global norms.", can:"Illegal on paper (medical and recreational both prohibited) but de-facto tolerated: reported that no one has been arrested for smoking or dealing cannabis 'in living memory'; culturally popular across society and historically the 'sacred weed of the people'. Cultivated domestically and trafficked to Gabon.", cbd:"No separate CBD carve-out; falls under blanket cannabis prohibition. No documented legal/regulated CBD market. Low confidence.", ket:"No EG-specific source found; treated as a registered anaesthetic medicine per global norm (recreational use illegal). Low-medium confidence.", ibo:"Iboga (Tabernanthe iboga) is native to Central Africa and its Bwiti ceremonial use has spread to the Fang communities of Equatorial Guinea; no national drug law specifically schedules or prohibits it (unlike refined psychedelics), so indigenous/traditional use is effectively unregulated. Note: not legally protected as in Gabon. Low confidence.", coc:"Refined cocaine illegal and trafficking criminalized with severe penalties (long jail terms + heavy fines). Note: death penalty for all crimes abolished by the Sept 2022 penal code, so no capital exposure.", coca:"No Andean tradition; falls under general narcotics prohibition. EG is not a party to the 1961 Single Convention but has a domestic Drug Control Law. Low confidence." } },
  ER: { n:"Eritrea", def:'ill', st:{ ket:'med' }, nt:{ _:"Eritrea maintains uniformly strict, enforced drug prohibition with no decriminalization, religious/indigenous, or research carve-outs. Cannabis (and CBD, undifferentiated) is fully illegal with prison + fines. All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) and cocaine/coca leaf are illegal narcotics under UN-convention-aligned law; Eritrea does not appear on the Psychedelic Alpha tracker, indicating no reform. Ketamine is the lone exception, registered as a general anaesthetic on the National List of Medicines (med). Drug trafficking carries long prison terms (5-10+ years) but is NOT a capital offence — Eritrea's death-eligible crimes are genocide, war crimes, treason and aggravated murder, and it is absent from Harm Reduction International's list of death-penalty-for-drugs states — so 'cap' is not warranted.", can:"Fully illegal, medical and recreational. Possession up to 12 months + fine (up to 50,000 nakfa); trafficking 5-10 yrs, up to 18 yrs for commercial sale to minors. No medical program. Among the strictest regimes globally.", cbd:"Illegal. Eritrean law makes no distinction between CBD and other cannabis products.", dmt:"No religious/ayahuasca exemption; prohibited under UN-convention-aligned narcotics law.", ket:"Listed as a general anaesthetic in Eritrea's National List of Medicines (ketamine HCl 50mg/ml injection, all hospitals). Registered medicine; recreational use prohibited.", coca:"No traditional/Andean use; raw coca leaf falls under general narcotics prohibition, illegal." } },
  EE: { n:"Estonia", def:'decrim', st:{ cbd:'legal', ket:'med', ibo:'ill', coca:'ill' }, nt:{ _:"Estonia decriminalized personal-use possession of ALL illicit drugs (misdemeanour, not crime) since ~2002-2005 — threshold is below the amount needed to intoxicate ~10 people. So cannabis, psilocybin, LSD, MDMA, DMT, mescaline and cocaine are all 'decrim' for personal possession, while supply/trafficking stays criminal and enforced. CBD (hemp-derived, <0.2% THC) is legal. Ketamine is a registered medicine (med). Medical cannabis exists only via a restrictive special-permit route. EU member, no death penalty. A 2026 reform proposes raising the 'large quantity' threshold from 10 to 30 doses. Ibogaine and raw coca leaf marked illegal conservatively (obscure, no special carve-out). Confidence medium: the blanket personal-possession decrim is well-documented, but exact per-substance dose thresholds and the ibogaine/coca-leaf edge cases are less certain.", can:"Recreational illegal but personal-use possession (under ~10 doses / <7.5g) is a misdemeanour, not a crime — part of Estonia's blanket decriminalization of personal possession of all drugs (since ~2002-2005). Medical cannabis accessible only as an unlicensed medicine via special permit from the State Agency of Medicines (very restrictive, near-zero patients). A 2026 Justice Ministry draft would raise the 'large quantity' threshold from 10 to 30 doses.", cbd:"Legal when hemp-derived with THC below 0.2%, per EU rules.", psi:"Schedule I, illegal; personal-use possession decriminalized (misdemeanour) under the blanket scheme. Scientific research with psychedelics is legal per the Estonian Medicines Agency; psychiatrists have pushed to update therapeutic use.", lsd:"Illegal; personal-use possession decriminalized (administrative offence) under the blanket all-drugs scheme.", mdma:"Illegal; personal-use possession decriminalized (administrative offence) under the blanket all-drugs scheme.", dmt:"Illegal; personal-use possession decriminalized (administrative offence) under the blanket all-drugs scheme.", mes:"Illegal; personal-use possession decriminalized (administrative offence) under the blanket all-drugs scheme.", ket:"Registered/available medicine in Estonia; non-medical use illegal.", ibo:"Controlled substance, no registered medical use; supply criminal. (Personal-use possession would technically fall under the blanket decrim, but treated conservatively as illegal/enforced.)", coc:"Illegal; personal-use possession decriminalized (administrative offence) under the blanket all-drugs scheme. Supply/trafficking criminal.", coca:"Raw coca leaf controlled; no traditional/medical use in Estonia." } },
  ET: { n:"Ethiopia", def:'ill', st:{ ket:'med' }, nt:{ _:"Ethiopia broadly prohibits controlled drugs under the 1996 Narcotic Drugs & Psychotropic Substances Control Proclamation and Proclamation 176/1999, with trafficking penalties of 5-15 years (Criminal Code Art. 525) but no death penalty. Cannabis is illegal/enforced despite some informal tolerance; CBD is ambiguous and treated conservatively as illegal. All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) are prohibited with no medical/research or religious exemptions. Ketamine is available as a registered anaesthetic on the WHO-aligned Essential Medicines List (med). Refined cocaine and raw coca leaf are both prohibited narcotics (no Andean traditional-use context).", can:"Illegal for recreational and medical use under the 1996 Narcotic Drugs & Psychotropic Substances Control Proclamation; possession ~up to 6 months, sale 5-10 yrs + fine. Some de-facto police tolerance around Rastafarian/Shashamane community, but arrests do occur, so classed as enforced.", cbd:"No legal carve-out; treated as associated with cannabis, status ambiguous, so classed conservatively as illegal.", dmt:"No religious/ayahuasca exemption; prohibited as a psychotropic substance.", mes:"No peyote/San Pedro exemption; prohibited.", ket:"Registered anaesthetic on Ethiopia's WHO-aligned Essential Medicines List (7th ed., 2024); medical use only, recreational use prohibited.", coca:"No traditional/indigenous use in Ethiopia (Andean plant); falls under general narcotic prohibition." } },
  FK: { n:"Falkland Islands", def:'ill', st:{ cbd:'legal', ket:'med', ibo:'nodata' }, nt:{ _:"Falkland Islands (UK Overseas Territory) controls drugs via the Misuse of Drugs Ordinance 1987, closely modeled on the UK Misuse of Drugs Act 1971 with the same Class A/B/C structure and criminal enforcement. Cannabis is Class B (illegal, enforced; up to 5 yrs possession / 7 yrs cultivation). All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) and refined cocaine plus raw coca leaf are Class A — illegal and enforced, with no decriminalization or therapeutic-access pathway in this small territory. Ketamine is a prescribable anaesthetic medicine (recreational use illegal). The one notable liberalization is CBD: since 2022 the Executive Council has made import, possession, use and retail sale of low-THC (<=1 mg per component) 'excepted' CBD products lawful. Ibogaine has no clear scheduling or access program and is marked nodata. A Governor/Chief Medical Officer licensing clause exists for medical/research use of controlled drugs but there is no evidence of any operational program for the psychedelics.", can:"Class B under the Misuse of Drugs Ordinance 1987 (mirrors UK Misuse of Drugs Act 1971); possession up to 5 yrs, cultivation/supply up to 7 yrs. No operational medical-cannabis program despite a theoretical Governor/CMO licensing clause.", cbd:"Specifically legalized by Executive Council in 2022: import, possession, use and retail sale of 'excepted products' lawful if no more than 1 mg THC per component part and THC not readily extractable.", ket:"Controlled drug but available as a registered/prescribable anaesthetic medicine within the UK-territory medical system; recreational use illegal.", ibo:"Not specifically scheduled and no approved medical use or known access program in this micro-jurisdiction; genuinely unclear status.", coca:"Coca leaf falls under Class A cocaine/ecgonine controls; no traditional-use exemption in this South Atlantic territory." } },
  FJ: { n:"Fiji", def:'ill', st:{ ket:'med' }, nt:{ _:"Fiji prohibits all listed recreational/psychedelic substances under the Illicit Drugs Control Act 2004 (Schedule 1 / Part 8), with up to F$1,000,000 fines and life imprisonment for trafficking and a mandatory minimum sentence for small cannabis possession. No death penalty (abolished; constitutionally barred; 2024 reintroduction calls rejected) so 'cap' is not warranted despite life-imprisonment maxima. Only ketamine has real medical access (WHO essential anaesthetic, lawful professional/Poisons-Board channel) = 'med'. A 2024-25 medicinal-cannabis program is export-only and does not create domestic patient access, so cannabis/CBD remain 'ill'. Coca leaf is explicitly scheduled (ill). Ibogaine is unscheduled with no access provision (ill, lower confidence).", can:"Schedule 1 illicit drug under Illicit Drugs Control Act 2004; possession up to 100g carries a mandatory ~3-month prison term, cultivation/supply up to life imprisonment. A medicinal-cannabis industry approved in 2024-25 is EXPORT-ONLY and explicitly does NOT change domestic prohibition; no domestic patient/medical access.", cbd:"No domestic medical/OTC CBD access; remains in a legal grey zone. Only industrial hemp <1% THC was de-listed (2022) for cultivation/import; CBD products are not separately legalized, so conservatively illegal.", dmt:"DMT listed in Schedule 1; no religious/indigenous ayahuasca exemption.", ket:"Listed as an 'illicit drug' (Part 8 of the Act) but functions as a registered medicine: WHO essential anaesthetic used in Fiji hospitals; Act s.11(b) exempts lawful professional possession/administration and the Pharmacy & Poisons Board licenses import. Recreational/non-medical use illegal.", ibo:"Not individually scheduled and no medical/research access provision; defaults to prohibition. Lower confidence (inferred from absence of any permissive carve-out).", coc:"Schedule 1; importation/supply/trafficking can carry up to life imprisonment.", coca:"Coca leaf is explicitly listed in Schedule 1 ('Coca (leaf)'); no traditional-use exemption." } },
  FI: { n:"Finland", def:'ill', st:{ can:'med', cbd:'legal', ket:'med' }, nt:{ _:"Finland operates a prohibitionist framework under the Narcotics Act (373/2008): a general ban on classified narcotics (production, import, possession, use), enforced as criminal offences under Penal Code Chapter 50, with statutory exceptions for medical, scientific and research use authorized by the Finnish Medicines Agency (Fimea). Personal-use possession is typically a fine or short imprisonment; there is no death penalty or long mandatory minimum, so 'cap' is not applicable. Recreational cannabis, psilocybin, LSD, MDMA, DMT, mescaline, ibogaine, refined cocaine and coca leaf are all illegal and enforced. CBD is legal but tightly regulated (EU rules, ≤0.2% THC; Novel Food authorization needed for ingestible products). Medical cannabis is available but only via individual Fimea special permits (unlicensed medicine). Ketamine is a controlled registered medicine (esketamine/Spravato is an approved EU medicine), with recreational use illegal.", can:"Recreational illegal/enforced (fine to ~6 months for personal use). Medical cannabis (flower/oil) available only as an unlicensed medicine via individual Fimea special permit (MS, chronic pain, etc.).", cbd:"Legal but highly regulated: EU rules, max 0.2% THC; ingestible/food products need Novel Food authorization, otherwise external-use only.", psi:"Classified narcotic; illegal. Supreme Court has held Psilocybe mushrooms are not a 'very dangerous' narcotic, but possession/use remains a criminal offence.", dmt:"DMT illegal under Narcotics Act (NPS amendments, 2014). Minor legal ambiguity: ayahuasca plant components (B. caapi, P. viridis) appear on a 'herb list' and a 2016 case treated a DMT-containing plant as not an illegal drug, but no formal religious/ceremonial exemption exists.", mes:"Mescaline classified as a narcotic; illegal and enforced. No peyote/San Pedro exemption.", ket:"Controlled registered medicine (esketamine/Spravato approved in EU; ketamine used clinically). Recreational/non-medical use illegal.", ibo:"No medical approval; falls under general narcotics/NPS prohibition. Illegal.", coca:"Coca leaf is a classified narcotic with no traditional-use exemption in Finland; illegal." } },
  FR: { n:"France", def:'ill', st:{ can:'med', cbd:'legal', ket:'med' }, nt:{ _:"France is a high-control, evidence-first jurisdiction. All classical psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) plus ibogaine, cocaine and coca leaf are controlled stupefiants, illegal and enforced (no decriminalization for psychedelics; ayahuasca/iboga explicitly banned). Recreational cannabis remains a criminal offence handled by a fixed fine (rising to EUR500 in 2026), though a permanent pharmaceutical MEDICAL cannabis regime began ~April 2026 for last-resort conditions. CBD is legal and openly sold (<0.3% THC). Ketamine is a registered hospital medicine, with esketamine for treatment-resistant depression and IV ketamine approved March 2026 for acute suicidal crisis; recreational use illegal.", can:"Recreational illegal under 1970 Narcotics Act; possession handled via amende forfaitaire delictuelle (EUR200, set to rise to EUR500 per Macron Dec 2025), a criminal penalty entered on record, up to 1yr prison possible. Separately, a pharmaceutical-style permanent MEDICAL cannabis regime launched ~April 2026 replacing the 2021-2026 pilot (last-resort conditions only: refractory epilepsy, cancer symptoms, neuropathic pain, MS spasticity, palliative care).", cbd:"Legal and openly sold; products must contain <0.3% total THC (raised from 0.2% in 2025 to harmonize with EU). Ingestible CBD still gated by EU Novel Food rules; several neo-cannabinoids (HHC, THCP, H4CBD etc.) banned by ANSM 2024-2025.", psi:"Controlled stupefiant, enforced. Spores legal to sell but cultivation prohibited; no medical/therapeutic access outside ANSM trials.", mdma:"Controlled stupefiant; access only within ANSM-authorized clinical trials.", dmt:"Illegal; 2005 decree explicitly bans ayahuasca plants and harmala alkaloids. Earlier Santo Daime religious accommodation revoked; no religious exemption.", mes:"Mescaline classified as stupefiant since 1970s; peyote (Lophophora) prohibited. San Pedro/Trichocereus may be possessed as ornamental plants but extraction/consumption is illegal.", ket:"Registered medicine (hospital use). Esketamine (Spravato) authorized for treatment-resistant depression (EMA since 2019); ANSM approved IV racemic ketamine for acute suicidal crisis in March 2026. Recreational use illegal as a stupefiant.", ibo:"Iboga/ibogaine classified as stupefiant since 2007 decree (upheld by Conseil d'Etat 2009 on public-health grounds); no legal therapeutic use.", coca:"No legal distinction from cocaine outside South America; coca leaf treated as a controlled substance/stupefiant in France and the EU." } },
  GA: { n:"Gabon", def:'ill', st:{ ket:'med', ibo:'legal' }, nt:{ _:"Gabon prohibits and enforces against the standard controlled substances (cannabis, CBD by extension, psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, cocaine, coca leaf) under a UN-convention/French-derived narcotics regime. The death penalty was abolished for all crimes in 2010, so no capital classification applies. Ketamine is a registered medicine (med). The major exception is iboga, which holds protected National-Treasure status (since 2000) with constitutionally protected Bwiti ceremonial use and is not scheduled as a narcotic (legal), though export is banned and there is no clinical/medical framework. Confidence is medium: the iboga and death-penalty facts are well-sourced, while the precise schedule for several minor psychedelics (LSD/MDMA/DMT/mescaline) is inferred from Gabon's convention membership and enforced narcotics laws rather than a substance-by-substance Gabonese statute.", can:"Illegal and enforced; Gabon is a cannabis trafficking destination/transit point (interdiction in Oyem, Mitzic, Bitam, Libreville).", cbd:"No separate CBD framework; falls under cannabis prohibition.", dmt:"DMT/ayahuasca prohibited as a controlled substance — distinct from the separately-protected iboga (active ibogaine).", ket:"Registered medicine (anaesthesia); recreational use not permitted.", ibo:"Iboga is a national treasure (declared 2000) with constitutionally protected ceremonial use in the Bwiti tradition; not scheduled as a narcotic. Export is banned under a 1994/heritage law. No Western clinics — access is via traditional ceremony.", coc:"Prohibited narcotic; growing transit-trade concern but illegal and enforced." } },
  GM: { n:"Gambia", def:'ill', st:{ ket:'med' }, nt:{ _:"The Gambia maintains comprehensive drug prohibition under the Drug Control Act 2003 (amended 2014), enforced by the Drug Law Enforcement Agency (DLEAG). Cannabis and CBD are fully illegal with no medical/CBD carve-out; cocaine and MDMA appear by name in DLEAG arrest reports. There is no medical, research, or religious exemption framework for psychedelics (psilocybin, LSD, DMT/ayahuasca, mescaline, ibogaine) or for coca leaf — all classified 'ill'. Ketamine is treated as 'med' per the global registered-medicine norm (no Gambia-specific ban found; recreational use illegal). The death penalty for drug offences was abolished in 2011 (capital punishment fully abolished 2025), so 'cap' is not warranted despite trafficking carrying a 10-year mandatory minimum and large fines. Confidence is medium: cannabis/CBD/cocaine/MDMA statuses are well-sourced and recent (2024–2026), while the minor-psychedelic and coca classifications rest on the absence of any exemption regime rather than substance-specific Gambian sources.", can:"Fully illegal, actively enforced. Drug Control Act 2003 (amended 2014); possession >2.5g presumed intent to traffic → ~D1m fine + 10yr mandatory minimum. DLEAG raids cultivation regularly. No medical program.", cbd:"No legal distinction from cannabis — CBD treated as part of the prohibited cannabis plant; illegal, no medical exemption.", lsd:"No medical/research/religious exemption framework; comprehensive prohibition under Drug Control Act.", mdma:"Ecstasy explicitly among substances DLEAG arrests for; illegal and enforced.", ket:"Registered medical/anaesthetic use (WHO essential medicine, common hospital anaesthetic); recreational use illegal.", ibo:"Death penalty for drug offences abolished 2011 (full abolition of capital punishment 2025) — so no capital drug penalties; trafficking still carries long mandatory minimums.", coc:"Cocaine/crack explicitly named in DLEAG enforcement actions; illegal." } },
  GE: { n:"Georgia", def:'ill', st:{ can:'decrim', cbd:'legal', ket:'med' }, nt:{ _:"Georgia (country): cannabis is the headline case — 2018 Constitutional Court protected personal consumption, but a 2025 government crackdown re-criminalized possession (>5g up to 6 yrs; <=5g administrative), so coded decrim/borderline-ill. CBD personal use is legal (no commercial framework). All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline), ibogaine, refined cocaine and coca leaf are controlled narcotics under Art. 260 — criminal offences, no medical/research or religious carve-outs. Ketamine is a registered medicine (med). No death penalty (abolished 2006, EU candidate), so no 'cap'. Confidence medium: cannabis well-sourced for 2024-26, but the exotic psychedelics rely on general narcotics-scheduling rather than substance-specific Georgian sources.", can:"2018 Constitutional Court protected personal cannabis CONSUMPTION (privacy/free-personality), making Georgia an outlier. But a 2025 Georgian Dream crackdown repealed Art. 273-1 and folded cannabis into Art. 260 (narcotics): possession >5g dried now up to 6 yrs; <=5g is an administrative offence (repeat = up to 1 yr). Sale/cultivation always illegal. Coded decrim (small personal amounts still non-criminal/administrative + residual constitutional consumption right) but borderline ill after the 2025 reversal.", cbd:"CBD legal for personal use as of 2026; no commercial cultivation/sale framework (Orthodox Church opposition). Use itself not prohibited.", ket:"Registered medicine (clinical/anaesthetic use); recreational use illegal.", coca:"No traditional/indigenous use; controlled as a narcotic like refined cocaine." } },
  DE: { n:"Germany", def:'ill', st:{ can:'legal', cbd:'legal', psi:'med', ket:'med', ibo:'legal' }, nt:{ _:"Germany 2026: recreational cannabis legal since April 2024 (CanG, removed from Narcotics Act); CBD legal under 0.3% THC. Classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) are Anlage I 'not marketable' BtMG substances and criminal offences, with no religious exemptions. Notable exception: psilocybin classed 'med' due to the July 2025 BfArM compassionate-use programme (EU-first) for treatment-resistant depression at two clinics plus active trials. Ketamine is a non-BtMG prescription medicine ('med'); ibogaine is unscheduled and therefore not prohibited ('legal'). Cocaine and coca leaf are illegal and enforced.", can:"Recreational cannabis legalized 1 April 2024 under the Cannabis Act (CanG/KCanG): adults 18+ may possess up to 25g in public and 50g at home, grow up to 3 plants, and join non-commercial cannabis cultivation associations (social clubs, from July 2024). Removed from the Narcotics Act. 2025 CDU/SPD coalition kept the law (policy review late 2025).", cbd:"Legal if THC <0.3% and from EU-approved hemp; can be bought, possessed and used. No medical claims; CBD as food restricted under EU Novel Food rules.", psi:"Anlage I BtMG (Schedule I, 'not marketable'), so recreational/general use is a criminal offence. However in July 2025 BfArM approved the EU's first psilocybin compassionate-use programme for treatment-resistant depression at two clinics (CIMH Mannheim, OVID Clinic Berlin); active clinical trials also run. Classified 'med' on the basis of this real expanded-access/research route, not general legality.", lsd:"Anlage I BtMG, illegal and enforced. Limited research trials only; no patient-access programme. Note: some uncontrolled LSD analogues (e.g. 1cP-LSD) remain in a legal grey area as of 2026.", mdma:"Anlage I BtMG ('not marketable'), illegal and enforced. Active clinical trials exist but, unlike psilocybin, no approved compassionate-use/patient-access programme as of 2026.", dmt:"DMT is Schedule I (Anlage I) BtMG; ayahuasca containing DMT is illegal and enforced. No religious/Santo Daime exemption (courts set 'not small amount' at 3.6g DMT in 2012).", mes:"Mescaline is controlled under Anlage I BtMG (illegal, enforced). The cacti themselves (peyote, San Pedro) may be legally grown as ornamentals, but extracting/possessing mescaline is an offence.", ket:"Prescription medicine, not scheduled under the BtMG; legal for medical/anaesthetic and off-label psychiatric use. Recreational use illegal.", ibo:"Ibogaine/iboga is not listed in the BtMG and is not a controlled narcotic in Germany, so it is not prohibited (sold legally by vendors). Unregulated rather than approved as medicine.", coc:"Refined cocaine is controlled under the BtMG; illegal and enforced as a criminal offence.", coca:"Coca leaf is controlled under the BtMG; illegal and enforced. No traditional/indigenous-use exemption in Germany." } },
  GH: { n:"Ghana", def:'ill', st:{ cbd:'med', ket:'med' }, nt:{ _:"Ghana enforces prohibition on recreational drugs under the Narcotics Control Commission Act 2020 (Act 1019), which took a more public-health-oriented approach: personal-use possession is now a fine rather than the old 10-year mandatory minimum, while trafficking still carries 10-year-to-life sentences. A regulated medicinal/industrial cannabis (<=0.3% THC) and CBD licensing regime launched in February 2026. Ketamine is a registered essential medicine. Classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline, ibogaine) and cocaine/coca leaf have no exemptions and remain illegal controlled substances. The death penalty for ordinary crimes was abolished in 2023, so 'cap' is not warranted.", can:"Recreational cannabis illegal & enforced, but Narcotics Control Commission Act 2020 (Act 1019) cut personal-use possession from a 10-yr mandatory minimum to a fine of 200-500 penalty units (~GHS 2,400-6,000). High-THC plant remains prohibited; not formally decriminalized.", cbd:"Low-THC cannabis (<=0.3% THC) and CBD extraction for medicinal/industrial use permitted under a licensed regime; national licensing regime launched 26 Feb 2026 by NACOC. Unlicensed sale/import still criminal (up to 10 yrs).", psi:"No carve-out; controlled narcotic under Act 1019. Personal-use possession -> fine, trafficking -> 10 yrs+.", ket:"On Ghana's Essential Medicines List as an anaesthetic (injection formulations); registered medicine, recreational use illegal.", ibo:"No specific exemption or clinic regime; falls under general controlled-substance prohibition.", coc:"Refined cocaine illegal & enforced; trafficking carries 10-yr minimum, life imprisonment for repeat offenders. Note: Ghana abolished the death penalty for ordinary crimes in 2023, so no capital punishment for drug offences.", coca:"No traditional/indigenous use; treated as a prohibited controlled narcotic, no exemption." } },
  GR: { n:"Greece", def:'ill', st:{ can:'med', cbd:'legal', ket:'med' }, nt:{ _:"Greece (EU member, no death penalty) operates a standard UN-convention prohibition framework. Recreational cannabis and all classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) plus cocaine and coca leaf are Schedule-controlled, illegal and enforced. Personal-use possession is a criminal offence under Law 4139/2013 but carries reduced penalties with treatment diversion (not formal decriminalization). CBD (<0.2% THC) is legal and widely sold. Medical cannabis has been legal since 2017 with e-prescriptions operational since Feb 2024 (recreational still illegal). Ketamine/esketamine is a registered medicine (Spravato EMA-approved, used clinically in Greece). A claimed 2024 Greek psilocybin therapy program could not be verified in any authoritative source and is treated as unsubstantiated.", can:"Recreational cannabis illegal and a criminal offence under Law 4139/2013, though penalties for personal use are reduced and first-time/occasional users can be diverted to treatment or acquitted (not formally decriminalized or legalized). Separately, MEDICAL cannabis legal since 2017 with e-prescriptions live since Feb 2024 via licensed pharmacies for qualifying conditions.", cbd:"Legal; CBD products with <0.2% THC sold widely in pharmacies and health stores.", psi:"Illegal/enforced narcotic. Claims of a 2024 Greek psilocybin medical/prescription program for depression/PTSD appear only on low-quality SEO/AI-content sites and could not be verified in any authoritative or government source; treated as unsubstantiated.", dmt:"DMT/ayahuasca illegal and enforced; no religious/traditional-use exemption in Greece.", ket:"Registered medicine; esketamine (Spravato) is EMA-approved and clinically used in Greece (documented Greek case series). Recreational use illegal.", coca:"Coca leaf controlled/illegal; no traditional or legal use in Greece." } },
  GL: { n:"Greenland", def:'ill', st:{ cbd:'legal', ket:'med' }, nt:{ _:"Greenland is an autonomous territory of the Kingdom of Denmark and applies Danish drug law (the Euphoriants Substances Act / Executive Order on Euphoriant Substances, latest No. 405 of 23 March 2026). Recreational cannabis and all classic illicit drugs (psilocybin, LSD, MDMA, DMT, mescaline, ibogaine, cocaine, coca leaf) are illegal and enforced as criminal offences; there is no decriminalization or psychedelic-therapy framework. CBD is legal if THC <=0.2%. Ketamine is a registered medicine (med); medical cannabis is permitted by prescription as in Denmark but with limited real-world access and no Greenland-specific program. The classic psychedelics can in principle be dispensed for medical/scientific use under Denmark's B-list mechanism, but there is no practical patient/researcher access in Greenland, so they are marked 'ill' conservatively. No death penalty (capital punishment abolished). Confidence medium: Greenland-specific primary sources are sparse and most detail is inferred from Danish law, which governs Greenland.", can:"Recreational cannabis illegal and enforced; Greenland applies Danish law (Euphoriants Substances Act). Medical cannabis is technically permitted by prescription as in Denmark, but access is limited and there is no Greenland-specific program. Use is widespread (~21% of adults monthly per 2019 health survey) despite prohibition.", cbd:"CBD legal as in Denmark provided THC content does not exceed 0.2%; higher-THC products fall under euphoriant-substance rules.", psi:"Illegal euphoriant. Danish scheduling allows pharmacy dispensing for medical/scientific use in principle, but no real-world patient access in Greenland (no approved therapy, free public system, no private pharmacies).", lsd:"Illegal; classified A-list in Denmark (deemed to have no therapeutic value).", mdma:"Illegal euphoriant; possession can carry up to 2 years. No medical/decrim access in practice.", ket:"Registered medicine (anaesthetic) available through the public health system; recreational/non-medical use illegal.", coca:"Coca leaf illegal; no traditional/indigenous-use exemption under Danish/Greenlandic law." } },
  GT: { n:"Guatemala", def:'ill', st:{ dmt:'tol', ket:'med' }, nt:{ _:"Guatemala's Ley Contra la Narcoactividad (Decree 48-92, 1992) is a broad catch-all banning all consciousness-altering substances except tobacco and alcohol, so cannabis, CBD, and all classic psychedelics (psilocybin, LSD, MDMA, mescaline) are illegal and enforced. Possession is poorly distinguished from trafficking (personal use ~4mo-5yr; trafficking up to 20-25yr). The frequently-repeated 2019 medical-cannabis law appears unverified/unimplemented, so cannabis and CBD are coded illegal. DMT/ayahuasca is illegal on paper but de-facto tolerated, with retreats operating openly and possession recorded as 'unenforced'. Ketamine is a registered medicine (med). Ibogaine, refined cocaine, and coca leaf are all illegal with no exemptions. The death penalty for civilian offences was abolished in 2017, so 'cap' does not apply to any substance.", can:"Fully illegal (recreational & medical). The often-cited 2019 'medical cannabis <1% THC' law traces to a single secondary source disputed in its own comments; no implemented regulatory framework and no real patient access. Personal-use possession ~4mo-5yr; trafficking charges up to 20-25yr.", cbd:"No legal distinction from cannabis; no implemented medical/CBD framework. Illegal in practice, gray-market at best.", dmt:"Technically illegal under the Ley Contra la Narcoactividad (1992) catch-all on consciousness-altering substances, but ayahuasca possession is listed as 'unenforced' and retreats operate openly -> de-facto tolerated.", mes:"No specific exemption for peyote/San Pedro; caught by the broad consciousness-altering-substance prohibition. Conservatively illegal.", ket:"Registered medicine (standard); recreational use illegal.", ibo:"No specific regulation or medical approval; falls under the broad drug-activity prohibition. Limited direct data.", coc:"Illegal and enforced; Guatemala is a major cocaine transit country. Note: death penalty for civilian crimes (incl. drug offences) was abolished in 2017, so no capital punishment applies.", coca:"No traditional/indigenous coca use in Guatemala; prohibited like other controlled substances." } },
  GN: { n:"Guinea", def:'ill', st:{ ket:'med' }, nt:{ _:"Guinea (Republic of Guinea, Conakry) maintains blanket prohibition on controlled substances as a UN drug-convention party. Cannabis and CBD are fully illegal with no medical/recreational exception and no CBD/THC distinction; penalties include lengthy prison terms and fines (Leafwell, Cannigma). No country-specific legalization, decriminalization, or traditional-use carve-out exists for psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine), cocaine, or coca leaf — all default to enforced illegal status. Ketamine follows the near-universal pattern of a registered clinical/veterinary anaesthetic (coded 'med'), with recreational use illegal. Guinea abolished the death penalty entirely via its 2016 Criminal Code (finalized in the 2017 Military Justice Code), so drug offences carry enforced custodial sentences rather than capital punishment — hence 'ill' rather than 'cap'. Note: distinct from Equatorial Guinea (GQ), where ibogaine has indigenous ceremonial use — that does NOT apply to Guinea/GN. Confidence medium: cannabis/CBD and death-penalty abolition are well-sourced, but no Guinea-specific scheduling document for psychedelics/cocaine was located, so those statuses rest on the general prohibition framework rather than a primary statute.", can:"Cannabis fully prohibited (cultivation, possession, use, sale); no medical program. Death penalty for drug/other offences abolished by 2016 Criminal Code (finalized 2017), so trafficking is enforced prison time, not capital — hence 'ill' not 'cap'.", cbd:"Guinean law makes no distinction between CBD and other cannabis products; CBD is treated as illegal.", ket:"Ketamine available as a registered hospital/veterinary anaesthetic (clinical access); recreational use illegal." } },
  GW: { n:"Guinea-Bissau", def:'ill', st:{ ket:'med' }, nt:{ _:"Guinea-Bissau is a prohibitionist state with no medical, decriminalization, or psychedelic-reform carve-outs. Cannabis (incl. medical) and CBD are illegal (up to 18 years, personal use loosely enforced); cocaine is illegal and actively prosecuted despite the country's role as a major cocaine transit 'narco-state' (14-17 year sentences in 2024-2025). The death penalty was abolished in 1993, so no drug offence carries capital punishment (no 'cap'). All psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) and raw coca leaf fall under blanket narcotics prohibition with no traditional/religious or research exemptions identified. Ketamine is coded 'med' as a WHO essential-medicine anaesthetic widely used in regional hospitals (no GW-specific statute located). Confidence is medium: cannabis/CBD/cocaine/death-penalty facts are well-sourced; the psychedelics and ketamine codings are inferred from the absence of any reform and standard global classification rather than Guinea-Bissau-specific substance laws, which are not published online.", can:"Blanket prohibition - recreational and medical cannabis both illegal; convictions carry up to 18 years plus fines, though small personal-use possession is loosely/inconsistently enforced.", cbd:"No legal distinction between cannabinoids; CBD products fall under the same cannabis prohibition as THC.", ket:"No Guinea-Bissau-specific source found, but ketamine is a WHO essential medicine and a primary anaesthetic across West African hospitals; available for clinical use, recreational use prohibited.", coc:"Illegal and actively prosecuted; Guinea-Bissau is a major Latin America-to-Europe cocaine transit hub ('narco-state'). 2024-2025 trafficking convictions carried 14-17 year sentences. Death penalty abolished 1993, so no capital punishment.", coca:"No Andean traditional-use exemption; raw coca leaf falls under general narcotics prohibition." } },
  GY: { n:"Guyana", def:'ill', st:{ can:'decrim', cbd:'legal', ket:'med', coc:'cap' }, nt:{ _:"Guyana controls all classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) and coca leaf as narcotics/psychotropics with no medical, research, or religious/indigenous exemptions -> all 'ill'. Cannabis is illegal but possession <=30g no longer carries jail (2021 amendment: counselling/community service) -> 'decrim'; no recreational legalization. CBD/hemp legalized and regulated under the Industrial Hemp Act 2022 (<=0.3% THC, removed from narcotics) -> 'legal'. Ketamine is a registered medicine -> 'med'. Refined cocaine: trafficking carries MANDATORY life imprisonment on indictment (Act s.5 + s.73, 1989) with no judicial discretion -> 'cap' (on the mandatory-life basis; the Act's only death provision is narrow - supplying a narcotic to a minor causing death - and HRI 2022 does not list Guyana as a death-penalty-for-trafficking state). Confidence medium: cannabis/CBD/cocaine well-sourced from primary law; psychedelics rest on general statutory control rather than substance-specific Guyana entries (none in Psychedelic Alpha tracker), and ketamine/ibogaine scheduling not individually confirmed in Guyanese text.", can:"Illegal on paper, but 2021 amendment (Narcotic Drugs & Psychotropic Substances Control Act) removed custodial sentences for possession of <=30g: counselling for 1-15g, community service for 15-30g. AG reaffirmed no-jail directive in 2024. No recreational legalization.", cbd:"Industrial Hemp Act 2022 legalized hemp (<=0.3% THC) and hemp-derived products (foods, medicines, cosmetics) and removed hemp from narcotic-drug control; Guyana Industrial Hemp Regulatory Authority issues cultivation/manufacturing/research licences. Hemp-derived CBD is legal/regulated.", dmt:"Controlled psychotropic under the Narcotic Drugs & Psychotropic Substances (Control) Act; NO religious/indigenous ayahuasca exemption (unlike Brazil/Peru/Colombia). Illegal and enforced.", ket:"Registered anaesthetic medicine; no national carve-out removing medical use. Recreational use illegal.", ibo:"No dedicated ibogaine framework; falls under broad psychotropic control of the Narcotic Act. Treated as illegal.", coc:"Refined cocaine illegal; trafficking on indictment carries MANDATORY life imprisonment plus heavy fines (Act s.5 + s.73, [10 of 1989]), with judicial discretion to impose a lesser sentence removed. The Act's only capital provision is narrow (supplying a narcotic to a minor causing death, s.6); Harm Reduction International (2022) does NOT list Guyana among death-penalty-for-drug-trafficking states. 'cap' assigned on the basis of long mandatory (life) sentencing, not active executions.", coca:"No traditional/indigenous coca use in Guyana; controlled as a narcotic. Illegal." } },
  HT: { n:"Haiti", def:'ill', st:{ ket:'med' }, nt:{ _:"Haiti prohibits cannabis, cocaine, and other narcotics under Decretal Law No.4 of 1973 (amended by Law No.10 of 1984); no medical-cannabis/CBD program and no decriminalization. Although the 1984 law nominally permitted the death penalty for drug offences, Haiti's 1987 Constitution (Art.20) abolished capital punishment entirely (last execution 1972), so 'cap' is not warranted today — cocaine/cannabis are classed 'ill'. Coca leaf has no traditional-use exemption ('ill'). Ketamine classed 'med' by the registered-medicine default. Classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) have NO Haiti-specific sources — Haiti is absent from the Psychedelic Alpha tracker — so they are conservatively inferred 'ill' under the prohibitionist, UN-convention-aligned framework, with low confidence. Overall confidence LOW because the psychedelic and ketamine classifications rest on inference rather than Haiti-specific statutes.", can:"Illegal for all uses under Decretal Law No.4 of 1973 (narcotics), amended by Law No.10 of 1984; no medical program, no decrim. Penalties up to ~5-10 yrs.", cbd:"No CBD carve-out; treated under the same cannabis prohibition. Illegal on paper.", psi:"No Haiti-specific data; inferred illegal under general narcotics/psychotropics prohibition. Low confidence.", lsd:"No Haiti-specific data; not listed in Psychedelic Alpha tracker. Inferred illegal under prohibitionist UN-aligned drug law. Low confidence.", mdma:"No Haiti-specific data; inferred illegal. Low confidence.", dmt:"No Haiti-specific data; no religious/ayahuasca exemption known. Inferred illegal. Low confidence.", mes:"No Haiti-specific data; no peyote/San Pedro exemption known. Inferred illegal. Low confidence.", ket:"No Haiti-specific source found; classified 'med' by general rule (ketamine is a registered anaesthetic / WHO Essential Medicine almost everywhere); recreational use illegal. Low confidence.", ibo:"No Haiti-specific data at all; ibogaine is unscheduled in many countries. Classed 'ill' conservatively under the broad narcotic prohibition, but genuinely uncertain. Low confidence.", coc:"Cocaine is a scheduled narcotic under the 1973/1984 laws. NOTE: the 1984 law nominally allowed the death penalty for narcotics offences, but Art.20 of the 1987 Constitution abolished capital punishment entirely (last execution 1972), so 'cap' does not apply today; classed 'ill'.", coca:"Coca leaf not native and has no traditional-use exemption; falls under the cocaine/narcotic prohibition." } },
  HN: { n:"Honduras", def:'ill', st:{ ket:'med', ibo:'nodata' }, nt:{ _:"Honduras criminalizes essentially all controlled drugs under Decree 126-89 (1989). Cannabis (incl. CBD), psilocybin, LSD, MDMA, DMT, mescaline, cocaine and coca leaf are all illegal and enforced — no medical-cannabis or clinical-psychedelic framework exists, and foreign medical cannabis prescriptions are not recognized. Personal-use possession triggers mandatory rehab internment (up to 30 days first offense) plus fines; trafficking carries 3-20 years. There is NO death penalty (constitutionally abolished) and no extreme mandatory minimums, so 'cap' applies to nothing. Ketamine is a registered medical anesthetic (med; recreational illegal). Ibogaine has no Honduras-specific data — not on UN schedules and no known domestic program (nodata). Indigenous-run ayahuasca tourism is informally tolerated, but DMT itself remains criminalized.", can:"Fully illegal (recreational & medical) under Decree 126-89/1989; no medical-cannabis program, foreign prescriptions not honored. VP Nasralla has floated legalizing cultivation for export, but no law as of 2026.", cbd:"No legal distinction from cannabis; CBD products sit in a gray zone and are treated as illegal cannabis. Not regulated/approved.", dmt:"DMT/ayahuasca illegal and enforced, but indigenous-run 'ayahuasca tourism' is informally de-facto tolerated; the substance itself remains criminalized.", ket:"Registered anesthetic/medicine — legal for medical use; recreational use illegal.", ibo:"No Honduras-specific data; not on UN schedules and no known domestic regulation or program — genuinely unknown (would fall under the broad 'dangerous substances' clause if encountered).", coc:"Refined cocaine illegal and enforced; trafficking 3-20 yrs. No death penalty (constitutionally abolished).", coca:"No Andean/indigenous coca tradition or exemption in Honduras; raw coca leaf treated as an illicit narcotic." } },
  HK: { n:"Hong Kong", def:'ill', st:{ ket:'med' }, nt:{ _:"Hong Kong runs a strict prohibitionist regime under the Dangerous Drugs Ordinance (Cap. 134), with a single First Schedule covering all classic controlled drugs. Trafficking/manufacture carries a maximum of life imprisonment + HK$5M fine; possession/use up to 7 years + HK$1M. There is NO death penalty (abolished 1993), so no substance is coded 'cap'. Cannabis, LSD, psilocybin, MDMA, DMT, mescaline, cocaine and coca leaf are all illegal and enforced ('ill'). CBD is notable: reclassified as a dangerous drug on 1 Feb 2023 with no medical/hemp exemption (also 'ill'). Ketamine is the one exception — a First Schedule dangerous drug since 2000 but a registered medicine usable by licensed doctors/dentists, so coded 'med' (recreational use illegal). Ibogaine has no legal access pathway and is treated as illegal (lower confidence as not individually confirmed). DMT/ayahuasca and ibogaine carry slightly lower individual certainty but no exemption exists; overall confidence high.", can:"Dangerous drug under Dangerous Drugs Ordinance (Cap. 134); illegal and enforced. Trafficking max = life imprisonment + HK$5M fine; possession/use max = 7 years + HK$1M.", cbd:"Reclassified as a dangerous drug from 1 Feb 2023 (no THC threshold, no hemp/medical exemption, no approved consumer pathway); enforcement active through 2024-2026 incl. airport seizures. Same penalty tier as heroin.", psi:"Magic mushrooms: cultivation, sale and possession illegal (hallucinogen controlled under Cap. 134).", lsd:"Lysergide and N-alkyl lysergamide derivatives explicitly listed in the First Schedule, Cap. 134.", mdma:"Listed dangerous drug; historically a heavily abused 'party drug' and actively enforced.", dmt:"DMT is a UN 1971 Schedule I substance; controlled under Cap. 134 with no ayahuasca/religious exemption in Hong Kong. Conservatively illegal.", mes:"Mescaline named among controlled hallucinogens under Cap. 134; no peyote/San Pedro exemption.", ket:"First Schedule dangerous drug since 15 Dec 2000; usable by licensed doctors/dentists as a registered anaesthetic (medical use permitted), but recreational use is illegal and it is the most-abused drug in HK.", ibo:"No therapeutic, research or decriminalized pathway; falls under the prohibitionist Cap. 134 framework. No legal access for patients/researchers. Lower confidence (not individually confirmed in sources).", coc:"Refined cocaine is a Schedule 1 dangerous drug; illegal and strictly enforced.", coca:"Coca leaf explicitly listed in the First Schedule, Cap. 134; illegal (no traditional-use exemption)." } },
  HU: { n:"Hungary", def:'ill', st:{ cbd:'legal', ket:'med' }, nt:{ _:"Hungary has one of Europe's strictest, prohibitionist drug regimes, tightened dramatically in June 2025 (zero-tolerance package) with an anti-drug clause added to the Constitution in April 2025. Cannabis and all classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline), ibogaine, cocaine and coca leaf are illegal and actively enforced as criminal offences, with no decriminalisation and no religious/indigenous exemptions. Effectively no medical-cannabis access exists. CBD (<0.2% THC hemp) is legal subject to novel-food rules. Ketamine is a registered medicine (esketamine/Spravato EMA-authorised), so 'med', with recreational use illegal. No death penalty (EU member), so no 'cap'.", can:"Strictly illegal for recreational and medical use; criminal offence with multi-year prison terms. Sativex is nominally approved but virtually never prescribed and there is effectively zero medical-cannabis access; importing cannabis medicine even with a foreign prescription is illegal. Hungary tightened drug laws dramatically in June 2025 (zero-tolerance package) and added an anti-drug clause to its Constitution in April 2025 — among the strictest prohibitionist regimes in Europe, with no decriminalisation and no death penalty (EU member).", cbd:"Hemp-derived CBD with <0.2% THC is permitted (industrial/cosmetic); sale as a food supplement requires EU novel-food authorisation and domestic CBD-oil production is restricted. Medicinal CBD needs OGYEI authorisation.", psi:"Schedule I; possession can draw up to ~5 years imprisonment.", dmt:"DMT/ayahuasca illegal and enforced; no religious (Santo Daime/UDV) exemption in Hungary.", ket:"Registered medicine (anaesthetic); esketamine/Spravato is EMA/EC-authorised and thus available for treatment-resistant depression. Recreational use illegal." } },
  IS: { n:"Iceland", def:'ill', st:{ can:'med', cbd:'med', ket:'med' }, nt:{ _:"Iceland maintains a prohibitionist drug regime under the Narcotics Act (Law 65/1974); proposed decriminalization has not become law as of 2026 (minor possession is no longer recorded on criminal records since 2019, but remains a criminal offence). All classic psychedelics (psilocybin/dried mushrooms, LSD, MDMA, DMT/ayahuasca, mescaline), ibogaine, cocaine and coca leaf are illegal and enforced; trafficking carries up to 12 years. Two medical exceptions: ketamine/esketamine is a registered medicine (med), and CBD is regulated as a medicinal product requiring prescription because Sativex holds marketing authorization (med). Cannabis remains illegal with only Sativex available medically. Notable nuance: fresh (undried) native magic mushrooms occupy a legal gray area and may be picked.", can:"Illegal & enforced under Narcotics Act (Law 65/1974). No recreational/decrim law passed (2021 bill failed; later bill cleared first reading only). Small possession usually a fine, not recorded on criminal record since 2019, but still a criminal offence. Only medical cannabis product is Sativex (neurologist prescription, e.g. MS).", cbd:"Classified as a medicinal product because Sativex holds marketing authorization; ingestible CBD oil sold only via pharmacy/prescription, CBD flower banned. Hemp-derived CBD <0.2% THC technically permitted but access is medical-gated.", psi:"Psilocybin, psilocin and dried mushrooms prohibited (Art. 6 Narcotics Act). Notable loophole: no law specifically bans fresh native mushrooms, which may be picked in natural state; drying them is illegal.", ket:"S-ketamine/esketamine is a registered medicine in Iceland (anaesthesia/analgesia, EU-approved); recreational use illegal.", coca:"No traditional/indigenous use; controlled the same as cocaine under the Narcotics Act." } },
  IN: { n:"India", def:'ill', st:{ cbd:'med', ket:'med' }, nt:{ _:"India's NDPS Act 1985 broadly prohibits narcotics and psychotropics, with no recreational or general decriminalization. Cannabis flower/resin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine, cocaine and coca leaf are all illegal and enforced. Two real access routes exist: ketamine (registered medicine, NDPS Schedule X) and hemp-derived CBD <0.3% THC (legalized/regulated under AYUSH licensing since ~2024, prescription for oral forms). Bhang (cannabis leaf) is a long-standing state-licensed traditional carve-out, though the recreational THC product (ganja) is illegal. Psilocybin is a genuine grey area: the pure compound is scheduled and prosecuted, but the Kerala High Court ruled in Jan 2025 that magic mushrooms in natural state are not a scheduled substance. Severe-penalty dimension: commercial-quantity trafficking carries long mandatory minimum sentences (10-20 years), and repeat large-scale trafficking can attract a discretionary death penalty under Section 31A (the mandatory version was struck down in 2011 and made optional in 2014) — but ordinary possession of these substances is prosecuted as 'illegal/enforced', not capital, so per-substance codes are 'ill'.", can:"Recreational ganja (flowering tops) and charas (resin) are prohibited and enforced under the NDPS Act 1985. Bhang (cannabis leaves/seeds) is excluded from the NDPS definition of 'cannabis' and is sold via state-licensed shops in many states (e.g. UP, Rajasthan) as a traditional/personal-use carve-out — but flower and resin remain illegal.", cbd:"Hemp-derived CBD (<0.3% THC) is permitted; the government opened up industrial-hemp CBD around 2024 and products are sold under Ministry of AYUSH licensing. Oral CBD tinctures require a prescription; topicals generally do not. THC-rich products without a license remain NDPS offences.", psi:"Psilocin/psilocybin (the pure compounds) are scheduled psychotropics and prosecutions occur, but psilocybin-containing mushrooms in natural state are not explicitly listed. Kerala High Court (Jan 2025, Rahul Rai v. State) held magic mushrooms are not a scheduled narcotic/psychotropic substance under the NDPS Act — a contested grey area; the substance is still treated as illegal in practice.", dmt:"DMT/ayahuasca prohibited and enforced under the NDPS Act; no religious or research exemption in India.", ket:"Registered medicine used clinically (anaesthesia; treatment-resistant depression). Scheduled X drug under NDPS since 2013 (GSR 724(E)) and Schedule H of the Drugs & Cosmetics Act; recreational use is illegal.", coc:"Refined cocaine is a manufactured drug under the NDPS Act; illegal and enforced. Note: commercial-quantity trafficking carries long mandatory minimums (10-20 yrs) and, for repeat offenders, a discretionary death penalty under Section 31A (mandatory death struck down by Bombay HC in 2011; made optional in 2014).", coca:"Coca leaf is a controlled narcotic plant under the NDPS Act with no traditional-use exemption in India; illegal and enforced." } },
  ID: { n:"Indonesia", def:'ill', st:{ can:'cap', mdma:'cap', ket:'med', coc:'cap' }, nt:{ _:"Indonesia operates one of the world's strictest drug regimes under Narcotics Law No. 35/2009. Cannabis, CBD, psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, cocaine, and coca leaf are all Category/Group I narcotics with no medical or research access for patients (Constitutional Court rejected medical cannabis in 2022 and 2024). Trafficking of Category I substances in quantity genuinely carries the death penalty — 64 of 85 death sentences in 2024 were drug-related — so cannabis, MDMA, and cocaine are coded 'cap'; the lower-volume psychedelics are 'ill'. Ketamine is the sole exception, available as a prescription-only registered medicine (recreational use illegal), though BPOM and police are pushing to reschedule it (2024-2025). Ibogaine is not explicitly scheduled but is conservatively coded illegal, as courts read the law to cover naturally occurring psychoactives and no legal pathway exists.", can:"Category I narcotic (Law No. 35/2009), alongside heroin. No medical exception; Constitutional Court rejected medical-cannabis challenges in 2022 and again March 2024. CBD/hemp also banned. Large-scale cultivation/trafficking can carry the death penalty; 2023 Criminal Code expanded capital eligibility.", cbd:"No legal distinction from cannabis; all cannabis derivatives (CBD, hash, edibles) are Category I narcotics. No medical exemption.", psi:"Group I narcotic. Police ran undercover stings against 'shroom shake' venues in Canggu/Uluwatu/Gili in 2025-2026.", mdma:"Group I narcotic ('ecstasy'), explicitly named. Trafficking large quantities can carry life or the death penalty.", dmt:"Group I; ayahuasca/DMT treated as Category I narcotic, foreigners prosecuted for possession.", mes:"Mescaline is Group I; peyote/San Pedro classified Category I narcotic.", ket:"Registered medicine, prescription-only, administered by medical staff (anaesthesia, treatment-resistant depression). Recreational use illegal. BPOM (Dec 2024) and National Police pushing to reschedule as psychotropic/narcotic amid surge in illicit injectable sales.", ibo:"Not explicitly scheduled and absent from major trackers (Wikipedia, Psychedelic Alpha), but Indonesian courts read the Narcotics Law to cover naturally occurring psychoactives; no real legal access. Conservatively coded illegal.", coc:"Category I narcotic; importing/trafficking can carry 20 years, life, or the death penalty.", coca:"Erythroxylum genus (leaves, seeds, all preparations) explicitly defined as Category I narcotic. No traditional-use exemption." } },
  IR: { n:"Iran", def:'ill', st:{ can:'cap', ket:'med', coc:'cap' }, nt:{ _:"Iran prohibits and actively enforces against all listed substances; it is one of the world's leading executioners for drug offences (485+ drug executions in 2024). The 2017 reform raised capital-punishment thresholds but kept the death penalty for trafficking large quantities — 2kg for synthetics like cocaine and 50kg for natural substances like cannabis — so cannabis and refined cocaine sit in the 'cap' tier. CBD, LSD, MDMA, psilocybin, DMT, mescaline and (by catch-all) ibogaine are illegal and enforced. A 2014 fatwa declaring entheogens halal under supervision is religious only and gives no legal access. Ketamine is the lone exception: a registered medicine used in anaesthesia and psychiatric care, with recreational use illegal.", can:"Illegal for recreational and medical use; no medical-cannabis program. 2017/18 reform removed the death penalty for cannabis possession, but trafficking of 50kg+ can still carry capital punishment, and Iran actively executes for drug offences.", cbd:"No separate legal framework; treated as a cannabis derivative and prohibited.", psi:"Prohibited as an unapproved psychotropic. A 2014 fatwa by Grand Ayatollah Rohani declared entheogens halal under supervision, but this is a religious opinion only and does NOT change Iranian law — no legal therapeutic or research access.", lsd:"Explicitly scheduled under the Anti-Narcotics Law; illegal and enforced.", mdma:"Explicitly scheduled (Ecstasy) under the Anti-Narcotics Law; illegal and enforced. As a synthetic it could in principle fall under the 2kg capital-punishment threshold, but documented executions are overwhelmingly for opioids/meth/cocaine, so classed as enforced-illegal.", dmt:"No legal religious/ayahuasca exemption; covered under the blanket prohibition on psychotropics. The 2014 entheogen fatwa did not change the law.", mes:"No peyote/San Pedro exemption; prohibited under the general ban on psychotropics.", ket:"Registered medicine widely used for anaesthesia and increasingly for psychiatric (treatment-resistant depression) care in Iranian hospitals; recreational use illegal.", ibo:"No specific legal or medical-access data; falls under the catch-all prohibition on non-pharmacological psychotropics — treated as illegal.", coc:"Explicitly scheduled; trafficking of 2kg+ can carry the death penalty (threshold raised from 30g in 2017). Actively enforced.", coca:"Not cultivated or traditionally used; a coca/cocaine product prohibited under the Anti-Narcotics Law." } },
  IQ: { n:"Iraq", def:'cap', st:{ ket:'med' }, nt:{ _:"Iraq applies blanket prohibition on controlled drugs under Federal Law No. 50 of 2017 (Narcotics & Psychotropic Substances Act), implementing the UN 1961/1971 conventions with no medical-cannabis, hemp/CBD, research, or religious/indigenous exemptions. Trafficking (production, import, export, cultivation) is capital-eligible under Article 28 — Iraq issued ~144 drug-related death sentences and 454 life sentences in 2024 — so cannabis, CBD, the classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine), refined cocaine and raw coca leaf are all coded 'cap'. Ketamine is the sole exception: a registered hospital anaesthetic on the national essential-medicines list imported via KIMADIA, so it is coded 'med' (non-medical use remains illegal). Confidence is medium: cannabis/CBD and the death-penalty trafficking regime are well-documented for 2024–2026, but substance-specific scheduling for individual psychedelics is inferred from Iraq's adoption of the 1971 Convention schedules rather than a per-substance Iraqi source.", can:"Fully illegal (recreational/medical/industrial) under Federal Law No. 50 of 2017; trafficking/production/import can carry the death penalty (144 drug death sentences in 2024). No medical cannabis program.", cbd:"No hemp/CBD exemption — law treats all cannabis derivatives identically to cannabis. Customs at Baghdad/Erbil seize CBD oils/gummies even with foreign prescriptions; no import permits issued.", psi:"Controlled under the 1971 Convention framework adopted in Law No. 50/2017; no medical/research/decrim pathway. Trafficking capital-eligible.", lsd:"Schedule-I-type psychotropic under Law No. 50/2017; no clinical or research access. Trafficking capital-eligible.", mdma:"Prohibited psychotropic under Law No. 50/2017; no MDMA-therapy or research access. Trafficking capital-eligible.", dmt:"DMT/ayahuasca prohibited under the psychotropics law; no religious/indigenous exemption exists in Iraq.", mes:"Mescaline (peyote/San Pedro) prohibited under the 1971-Convention schedule adopted in Law No. 50/2017; no traditional/religious use.", ket:"Registered medicine: ketamine is a WHO Essential Medicines List anaesthetic imported/distributed via KIMADIA (Ministry of Health) for hospital use. Recreational/non-medical use illegal.", ibo:"No recognised legal or therapeutic status; captured by the blanket narcotics/psychotropics prohibition under Law No. 50/2017.", coc:"Refined cocaine illegal; trafficking (import/export/production) can carry the death penalty or life imprisonment under Article 28 of Law No. 50/2017.", coca:"No traditional coca use in Iraq; raw coca leaf treated as a prohibited narcotic plant. Trafficking capital-eligible." } },
  IE: { n:"Ireland", def:'ill', st:{ can:'med', cbd:'legal', ket:'med' }, nt:{ _:"Ireland prohibits and enforces against all classic controlled substances under the Misuse of Drugs Act 1977/Regulations 2017: cannabis, psilocybin, LSD, MDMA, DMT, mescaline, cocaine and coca leaf are illegal (ill). Ketamine is a registered prescription medicine (med); recreational use illegal. CBD is legal to sell below 0.2% THC. Cannabis has real medical access via MCAP (since 2019) plus Sativex/Epidyolex, and benefits from the Adult Caution Scheme for simple possession, but recreational cannabis remains a criminal offence. Ibogaine is the main outlier: not scheduled by name (personal possession effectively unregulated), though sale/import is criminalised under the 2010 Psychoactive Substances Act, so coded decrim with lower confidence. A nationwide 'health diversion'/decriminalisation reform (Citizens' Assembly 2024, Oireachtas committee, National Drugs Strategy 2026-2029) is under active consultation but is NOT yet law as of mid-2026, so possession remains criminal on paper.", can:"Recreational cannabis illegal under Misuse of Drugs Act 1977. Adult Caution Scheme since Dec 2020 allows Garda discretion to caution (not prosecute) first-offence simple possession of cannabis/resin, but it remains a criminal offence. Medical access exists separately: Medical Cannabis Access Programme (MCAP) since 2019 for 3 indications (MS spasticity, chemo nausea, intractable neuropathic pain), plus authorised meds Sativex and Epidyolex. A 'health diversion'/decriminalisation reform is under consultation (Citizens' Assembly 2024; National Drugs Strategy 2026-2029) but not yet enacted.", cbd:"CBD products legal to sell provided THC content is below 0.2%.", psi:"Schedule 1 (no recognised medical use). Sale of fresh/whole magic mushrooms was banned in 2006, closing an earlier loophole.", mdma:"Schedule 1; no therapeutic-use programme in Ireland unlike some other jurisdictions.", ket:"Controlled drug; registered/prescription medicine (medical use legal), recreational use illegal.", ibo:"Not named in the Misuse of Drugs Act 1977 schedules, so personal possession sits in a legal gray zone (effectively not prohibited by name); however sale/import/export is criminalised under the Criminal Justice (Psychoactive Substances) Act 2010 and HPRA grants no medical authorisation. Low confidence.", coca:"Treated as a cocaine-related controlled substance; no traditional/indigenous-use exemption in Ireland." } },
  IL: { n:"Israel", def:'ill', st:{ can:'med', cbd:'legal', mdma:'med', ket:'med' }, nt:{ _:"Israel: cannabis decriminalized for personal use (since 2019) with a large medical program; CBD removed from the Dangerous Drugs Ordinance (2022) and sold OTC. Classic psychedelics (psilocybin, LSD, DMT/ayahuasca, mescaline) and refined cocaine + coca leaf are illegal and enforced. MDMA is illegal but accessible via pioneering compassionate-use/PTSD research (investigational only); ketamine is a registered medicine used off-label for TRD with per-patient MoH approval. Ibogaine has no medical carve-out. No death penalty for drugs (trafficking max 20 yrs; possession max 3 yrs as a misdemeanour).", can:"Recreational illegal under the Dangerous Drugs Ordinance, but personal use in private decriminalized since 1 Apr 2019 (first offences -> ~NIS 1,000 fine, not criminal charge). Large, long-running medical cannabis program (since 1992; ~130k active licenses in 2025).", cbd:"Removed from the Dangerous Drugs Ordinance in March 2022; pure/low-THC CBD (THC limit raised 0.2%->0.3%) sold legally as a regulated supplement/cosmetic without prescription. THC-containing CBD medicines still under IMCA prescription oversight.", psi:"Illegal under the Dangerous Drugs Ordinance; only investigational use via approved clinical trials (e.g. a Phase I safety study). No general patient access.", mdma:"Illegal/controlled, but Israel was the first country to allow MDMA 'compassionate use' for PTSD (2019) and hosts MAPS Phase III + post-Oct-7 veteran PTSD trials. Access is investigational/exceptional only, not a routine prescription medicine.", dmt:"DMT (and thus ayahuasca) fully illegal and enforced; customs intercepts shipments and ceremony participants have been prosecuted (25+ arrested in a 2016-17 case). No religious exemption.", ket:"Registered medicine (anesthesia); psychiatric/off-label use for treatment-resistant depression requires per-patient Ministry of Health authorization, and supervised esketamine is available for TRD. Recreational use illegal.", ibo:"No specific medical/legal carve-out; treated as a controlled dangerous drug. No approved therapeutic access.", coca:"No traditional/indigenous coca use in Israel; coca leaf falls under the general prohibition on controlled drugs." } },
  IT: { n:"Italy", def:'decrim', st:{ can:'med', cbd:'ill', ket:'med', ibo:'ill', coca:'ill' }, nt:{ _:"Italy decriminalizes personal possession of all drugs (administrative sanctions only, per DPR 309/1990) while supply/trafficking/cultivation stay criminal — confirmed still in force 2025-2026 and not reversed by the 2025 security decree. Hence most prohibited recreational substances (cannabis, psilocybin, LSD, MDMA, DMT, mescaline, cocaine) are coded 'decrim' for possession. Ketamine is a registered medicine ('med'). Ayahuasca was banned in 2022; ibogaine was Schedule-1 listed in 2016 with specific prison penalties ('ill'). The notable 2026 change is Decree-Law 48/2025, which reclassified hemp-flower CBD products as narcotics ('ill'), leaving only seed/stalk-derived and prescription cannabinoids legal. Coca leaf has no carve-out ('ill').", can:"Recreational illegal but personal possession decriminalized (administrative sanctions only) under DPR 309/1990. Medical cannabis legal by prescription via AIFA, produced at the military pharma plant (SCFM) in Florence.", cbd:"Decree-Law 48/2025 (Apr 2025) reclassified hemp-flower-derived CBD (flowers, oils, edibles, vapes) as narcotics regardless of THC, dismantling the 'cannabis light' sector; aggressive seizures/closures. Only CBD from seeds/stalks, EU-compliant cosmetics, and prescription medical products remain legal. Industry court challenges ongoing; conflicts with EU Kanavape ruling.", psi:"Table 1 narcotic; trafficking/cultivation criminal, but personal possession is administrative-only (decriminalized).", lsd:"Table 1 narcotic; personal possession administrative-only (~0.15mg threshold). Supply remains criminal.", mdma:"Table 1 narcotic; personal possession administrative-only. Supply remains criminal.", dmt:"Ayahuasca declared illegal in 2022; DMT in Table 1. Personal possession administrative-only; no religious exemption.", mes:"Mescaline is Table 1 (illegal to buy/sell/transport), but personal possession is administrative-only. Non-peyote psychoactive cacti (e.g. San Pedro) are freely sold at garden centers; peyote prohibited.", ket:"Registered medicine; esketamine (Spravato) approved for treatment-resistant depression. Recreational use illegal.", ibo:"Ibogaine and Tabernanthe iboga added to Schedule 1 of DPR 309/1990 in 2016; possession/distribution can carry 2-12 months imprisonment.", coc:"Refined cocaine ('heavy' drug) illegal; trafficking from 6 years. Personal possession decriminalized to administrative sanctions only.", coca:"Coca leaf prohibited under narcotics law; no traditional-use carve-out and not a freely sold commodity in Italy." } },
  CI: { n:"Ivory Coast", def:'ill', st:{ ket:'med' }, nt:{ _:"Côte d'Ivoire prohibits cannabis and all listed psychoactives under Law No. 88-686 (1988), with no CBD carve-out and no medical/research access program for psychedelics — all coded 'ill'. Ketamine is a registered medicine ('med'). Refined cocaine and coca leaf are illegal and actively enforced (CI is a major cocaine transit hub). The death penalty is abolished (Constitution 2000/2016; life imprisonment since 2015), so no 'cap'. Notable reform: Law No. 2022-407 reframed personal drug USE as a public-health issue, permitting therapeutic injunctions instead of incarceration for simple use, though substances remain prohibited and implementation guidance is still incomplete. Confidence medium: cannabis/CBD and the death-penalty status are well-sourced; the niche psychedelics (psilocybin/LSD/MDMA/DMT/mescaline/ibogaine) and coca are inferred from the blanket narcotics/psychotropics framework rather than substance-specific Ivorian sources.", can:"Illegal & enforced under Law No. 88-686 (1988); CBD not distinguished from THC. Note: Law No. 2022-407 reframed personal drug USE as a public-health matter, allowing therapeutic injunctions instead of jail for simple use — but the substance remains prohibited and trafficking carries up to 20 yrs.", cbd:"No legal distinction from THC cannabis under the 1988 narcotics law; treated as illegal absent special Ministry of Health authorization.", dmt:"No religious/indigenous ayahuasca exemption; falls under general narcotics/psychotropics prohibition.", ket:"Registered anaesthetic/medicine available for medical use (WHO/INCB framework); recreational use illegal.", coc:"Refined cocaine illegal and actively enforced; CI is a major transit hub (2+ tonnes seized at San Pedro, 2024).", coca:"Coca leaf has no traditional/legal use; treated as an illegal narcotic." } },
  JM: { n:"Jamaica", def:'ill', st:{ can:'med', cbd:'med', psi:'legal', ket:'med' }, nt:{ _:"Jamaica is a global outlier on psilocybin: magic mushrooms were never scheduled under the 1948 Dangerous Drugs Act and are fully legal (legal retreat/research industry encouraged by the government). Cannabis is decriminalized (≤2 oz ticketable, 5 plants, Rastafarian sacramental use) with a CLA-licensed medical/CBD sector — not full recreational legalization. Ketamine is a registered medicine. Cocaine and coca leaf are controlled (trafficking up to 35 years), but no drug offence is capital in Jamaica (death penalty reserved for aggravated murder; de facto moratorium since 1988). LSD, MDMA, DMT and mescaline sit in a genuine regulatory gap — Psychedelic Alpha calls LSD/MDMA status 'undefined' — so they are marked illegal conservatively with low confidence rather than claimed legal from the statutory gap. Confidence overall medium (high on psilocybin/cannabis/cocaine/no-death-penalty; low on the synthetic/other psychedelics and ibogaine).", can:"Decriminalized by the Dangerous Drugs (Amendment) Act 2015: possession of up to 2 oz is a non-arrestable ticketable petty offence (no criminal record), up to 5 plants per household allowed, and Rastafarian sacramental use accommodated. Not fully legal recreationally (no open recreational retail). Medical cannabis is licensed/regulated via the Cannabis Licensing Authority (CLA).", cbd:"Available through the CLA-regulated medical/licensed cannabis framework established under the 2015 amendments; not separately prohibited.", psi:"Psilocybin mushrooms were NEVER scheduled under Jamaica's 1948 Dangerous Drugs Act and remain fully legal for possession, use, sale and cultivation. Government encourages a legal psilocybin retreat/research industry; Jamaica is a leading psychedelic-tourism destination.", lsd:"Legal status 'undefined' per Psychedelic Alpha (not clearly enumerated in the 1948 Act, but not an affirmatively sanctioned/legal market). Marked illegal conservatively; genuine ambiguity.", mdma:"Legal status 'undefined' per Psychedelic Alpha. Marked illegal conservatively; genuine ambiguity.", dmt:"Not specifically addressed in available sources; not affirmatively permitted. No notable religious/ayahuasca exemption documented. Conservative classification.", mes:"Not specifically addressed; no peyote/San Pedro exemption documented. Conservative classification.", ket:"Registered medicine (hospital anaesthetic); recreational use not permitted.", ibo:"No specific legal/medical framework documented; not a registered medicine in Jamaica. Conservative classification (status effectively unclear).", coc:"Controlled under the Dangerous Drugs Act (cocaine/ecgonine esters); trafficking carries up to 35 years and unlimited fine. NOT a capital offence — Jamaica reserves the death penalty for aggravated murder only and has a de facto moratorium (last execution 1988).", coca:"Coca leaf is not traditional/legal in Jamaica and falls under the same cocaine/ecgonine controls of the Dangerous Drugs Act." } },
  JP: { n:"Japan", def:'ill', st:{ cbd:'legal', ket:'med', ibo:'nodata' }, nt:{ _:"Japan maintains a zero-tolerance, strictly enforced drug regime with NO death penalty (max life imprisonment). Classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline) and cocaine are 'Tier 2' narcotics under the Narcotics & Psychotropics Control Act (up to 7 yrs for possession/use). The Dec 2024 Cannabis Control Act reform newly criminalized cannabis USE and reclassified THC as a narcotic, while opening only a narrow approved-medicine pathway. THC-free CBD is legal under some of the world's strictest residue limits (Stage 2 effective Mar 2025). Ketamine is a narcotic since 2007, medical-use only. Ibogaine has no confirmed scheduling and no access pathway (nodata). Coca leaf is illegal.", can:"Illegal and strictly enforced. Dec 2024 amendment to the Cannabis Control Act explicitly criminalized USE for the first time (up to 7 yrs) and reclassified cannabis/THC as a narcotic under the Narcotics & Psychotropics Control Law. A narrow medical-cannabinoid pathway (e.g. Epidiolex-type epilepsy drugs) was opened via approved pharmaceuticals/clinical trials, but recreational/general cannabis remains fully prohibited.", cbd:"Legal as a consumer product only if THC-free and derived from permitted hemp parts. Stage 2 of the 2024-25 reform (effective 1 Mar 2025) imposed ingredient-based residue limits among the world's strictest (~10 ppm oils, 1 ppm edibles/cosmetics, 0.1 ppm beverages); any detectable THC above limits is banned.", psi:"Banned since 2002 under the Narcotics & Psychotropics Control Act ('Tier 2' common narcotic); possession/use up to 7 yrs, enforced.", lsd:"Controlled narcotic under the Narcotics & Psychotropics Control Act; possession/use up to 7 yrs, enforced.", mdma:"Controlled narcotic; possession/use up to 7 yrs, enforced.", dmt:"Controlled as a narcotic/tryptamine; ayahuasca prosecuted. No religious-use exemption.", mes:"Mescaline is a controlled narcotic (scheduled phenethylamine). Peyote/San Pedro cacti themselves sit in a grayer 'Designated Substance' zone, but possession of the active compound is illegal.", ket:"Designated a narcotic in 2007 under the Narcotics & Psychotropics Control Act. Legal for medical use only (anesthesia; off-label infusion clinics exist); recreational possession/use is a criminal offence.", ibo:"No confirmed scheduling: ibogaine does not appear on Japan's narcotics schedule and is not clearly listed as a Designated Substance (Shitei-Yakubutsu). No legal medical/research access pathway either. Status genuinely unclear.", coc:"Refined cocaine is a 'Tier 2' narcotic under the Narcotics & Psychotropics Control Act; possession/use up to 7 yrs, enforced. No death penalty in Japan (max life imprisonment for large-scale trafficking).", coca:"No traditional or legal use; coca leaf treated as prohibited narcotic source material, illegal and enforced." } },
  JO: { n:"Jordan", def:'ill', st:{ ket:'med' }, nt:{ _:"Jordan prohibits and enforces against all listed psychoactive substances under the 1988 Drugs & Psychotropic Substances Law (amended 2015) and the 2016 Act; it is party to all three UN drug conventions. Cannabis and CBD are illegal for every purpose with no medical program, though first-time users are diverted to rehabilitation rather than prison. Classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline), refined cocaine, coca leaf, and ibogaine are all controlled and illegal (no religious/traditional exemptions). Ketamine is the sole exception: a registered prescription medicine for anaesthesia regulated by the JFDA (med), with recreational use illegal. Death penalty was abolished for ordinary drug offences in 2006 and now applies only to a narrow transnational-trafficking-gang offence, so substances are classified 'ill' rather than 'cap'.", can:"Illegal for all purposes; no medical-cannabis program. 1988 law amended 2015 to divert first-time users to rehab. Possession ~3mo-2yr + fine.", cbd:"No legal distinction from cannabis; CBD fully prohibited.", psi:"Schedule I under UN 1971 Convention; illegal.", lsd:"Controlled, illegal.", mdma:"Controlled psychotropic, illegal; ATS/Captagon enforcement is heavy in Jordan.", dmt:"Controlled (UN 1971); illegal, no ayahuasca/religious exemption.", mes:"Controlled, illegal; no peyote/San Pedro exemption.", ket:"Registered prescription medicine for anaesthesia, regulated by JFDA; recreational use illegal.", ibo:"Not an approved/registered medicine; controlled and illegal in practice.", coc:"Refined cocaine illegal and enforced. Death penalty abolished for ordinary drug offences (2006); 2016 Act reinstates it only for collaborating with transnational trafficking gangs, so classified 'ill' not 'cap'.", coca:"No traditional use; coca leaf treated as a prohibited narcotic." } },
  KZ: { n:"Kazakhstan", def:'ill', st:{ ket:'med' }, nt:{ _:"Kazakhstan prohibits all the listed substances except ketamine (registered medicine). Cannabis, CBD, classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline, ibogaine), refined cocaine and coca leaf are all Table I-type controlled substances with no medical, decriminalized, or religious-use access — possession is an enforced criminal offence. Ketamine is med (clinical anaesthetic; recreational use illegal). The death penalty was fully abolished in June 2022, so 'cap' does not apply; however a 2024-2025 reform raised production/trafficking penalties to 15-20 years up to life imprisonment. Statuses are access-focused (possession by patients/researchers), hence 'ill' rather than 'cap' across the board.", can:"Recreational and medical both illegal; possession is a criminal offence (cannabis offences cited at 7-14 yrs). Abundant wild cannabis exists but prohibition is enforced.", cbd:"No legal distinction from cannabis; CBD treated as a prohibited cannabis derivative. Occasional low-THC pharmacy availability is anecdotal/unclear, so classed illegal conservatively.", psi:"Table I controlled substance, prohibited; no medical or decriminalized access.", mdma:"Table I controlled substance, prohibited; no therapeutic exemption.", dmt:"DMT/ayahuasca controlled (psychotropic Table), prohibited; no religious exemption.", mes:"Mescaline controlled/prohibited; no peyote or San Pedro exemption.", ket:"Registered medicine/anaesthetic, controlled psychotropic; legal for medical use, recreational use illegal.", ibo:"No legal/medical access; controlled as a prohibited substance.", coc:"Refined cocaine in Table I (prohibited from medical use); criminal offence.", coca:"Coca leaf explicitly in Table I (prohibited); no traditional/indigenous use. NOTE: capital punishment fully abolished June 2022, but a 2024-2025 law raised drug production/trafficking penalties to 15-20 yrs up to life imprisonment — severe but not capital." } },
  KE: { n:"Kenya", def:'ill', st:{ ket:'med' }, nt:{ _:"Kenya prohibits essentially all listed substances under the Narcotic Drugs & Psychotropic Substances (Control) Act (Cap.245, amended 2022), one of Africa's strictest regimes. Cannabis, CBD (no THC carve-out for consumer products), and all classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) are illegal and enforced, with no functional religious/indigenous or therapy exemptions. Ketamine is the lone exception: an approved hospital anaesthetic (med), recreational use illegal. Cocaine and coca leaf are illegal narcotics. A narrow medical/scientific prescription clause exists on paper but does not provide real patient/researcher access for cannabis or psychedelics. Death penalty for drug trafficking was PROPOSED by President Ruto (2025-26) but is not yet law as of mid-2026; current maximum is life imprisonment, so no 'cap' coding applied.", can:"Fully illegal under Narcotic Drugs & Psychotropic Substances (Control) Act (Cap.245, amended 2022). Personal possession up to ~10 yrs; trafficking up to life + heavy fines. A narrow medical/scientific prescription exception exists on paper but is largely non-functional; no real medical cannabis program.", cbd:"No legal distinction from cannabis - CBD falls under the same controlled-substance classification regardless of THC. Industrial hemp (<0.2% THC) is licensable under the Industrial Hemp Act 2021, but consumer CBD products are not carved out as legal.", psi:"Pharmacy & Poisons Board states magic mushrooms/psilocybin are illegal; growing youth use but no legal/medical route.", lsd:"Illegal psychotropic per Pharmacy & Poisons Board; no medical/research access route.", mdma:"Illegal psychotropic per Pharmacy & Poisons Board; no MDMA-therapy access.", dmt:"DMT/ayahuasca controlled as psychotropic substance; illegal, no religious/indigenous exemption.", mes:"Mescaline/peyote/San Pedro controlled; illegal, no indigenous exemption.", ket:"Registered/approved medicine; Pharmacy & Poisons Board approves protocols and it is widely used as a hospital anaesthetic. Recreational use illegal.", ibo:"Ibogaine not approved; falls under psychotropic/narcotic prohibition; illegal.", coc:"Hard narcotic; illegal and enforced (life imprisonment for trafficking). NOTE: in 2025-26 President Ruto PROPOSED the death penalty for major drug traffickers (heroin/cocaine kingpins), but as of mid-2026 this is still draft legislation, not enacted - current max is life, so not coded 'cap'.", coca:"No traditional/indigenous use; treated as a narcotic-related plant under Cap.245. Illegal." } },
  XK: { n:"Kosovo", def:'ill', st:{ cbd:'tol', ket:'med' }, nt:{ _:"Kosovo (XK) maintains a unified prohibition framework under its Law on Narcotic Drugs and Psychotropic Substances and Criminal Code (Art. 269+), treating all controlled substances the same. Possession for personal use is a criminal offence (fine EUR250-300 or 1-3 yrs; up to 1 yr for <3g first offence); supply/trafficking/production 3-15 yrs. No medical cannabis program, no psychedelic/religious exceptions, and the death penalty is abolished (so no 'cap'). Cannabis, psilocybin, LSD, MDMA, DMT, mescaline, ibogaine, cocaine and coca leaf are all illegal and enforced (ill). Ketamine is a registered medicine (med). CBD/industrial hemp sits in a legal gray area — hemp is legal for registered cultivators and CBD products are sold openly without being treated as narcotics, so de-facto tolerated (tol). Cannabis, CBD, and cocaine statuses are high-confidence; the specific psychedelics, ketamine and ibogaine are inferred from the blanket controlled-substances framework rather than substance-named Kosovo statutes, hence medium overall confidence.", can:"Fully illegal, no medical program; possession is a criminal offence (fine EUR250-300 or 1-3 yrs). No reform movement as of 2026.", cbd:"Legal gray area: industrial hemp legal for registered entities; CBD sold in hemp shops/online and not treated as a narcotic in practice. Kosovo not bound by EU CBD rulings.", ket:"Registered medicine / controlled psychotropic available for clinical use; recreational use illegal.", coc:"Illegal and enforced; trafficking up to 12-15 yrs but no death penalty (abolished in Kosovo).", coca:"No traditional use; treated identically to cocaine under the narcotics law." } },
  KW: { n:"Kuwait", def:'ill', st:{ can:'cap', ket:'med', coc:'cap' }, nt:{ _:"Kuwait is a strict-prohibition Gulf state. The controlling instrument is Amiri Decree-Law No. 159 of 2025 (84 articles, effective ~mid-Dec 2025), which unified all drug control and reinstated the death penalty for trafficking (Art. 44) plus fines up to KD 2m. Drug use, incl. trace amounts in the body, can mean ~5 yrs prison + fine; simple possession is a criminal offence. There is NO recreational, medical-cannabis, or psychedelic-therapy access, and no religious/indigenous exemptions. The law DOES provide a Ministry of Health licensing framework for import, prescription, dispensing and hospital/research-lab handling of scheduled narcotics and psychotropics, under which ketamine functions as a registered medicine (med). Cannabis, CBD, and all classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine), plus cocaine and coca leaf, are illegal and enforced; cannabis and refined cocaine are marked 'cap' because trafficking is genuinely death-eligible. CBD is treated identically to cannabis (no hemp carve-out). One narrow leniency: Article 65 lets a first-time traveler caught at an official port with a personal-use quantity sign a pledge and avoid prosecution (confiscation only) - but a second offence or any commercial quantity triggers full prosecution, so the underlying status remains illegal.", can:"Fully illegal incl. medical; no CBD carve-out. Trafficking can carry death penalty under new Decree-Law 159/2025; even bodily trace/use up to 5 yrs prison.", cbd:"No hemp/CBD distinction; treated as cannabis. Travelers prosecuted, though Art. 65 lets first-time port arrivals with personal-use amounts sign a pledge instead of facing charges.", mdma:"No medical/research exemption; 'psychotropic pills' actively seized and enforced; trafficking eligible for capital punishment.", dmt:"Ayahuasca/DMT illegal; no religious or indigenous exemption exists in Kuwait.", ket:"Registered medical anaesthetic; import/prescription/hospital & research use permitted under Ministry of Health licence. Non-medical use illegal.", coc:"Refined cocaine illegal and actively seized; trafficking can carry the death penalty under Decree-Law 159/2025.", coca:"No traditional use; raw coca leaf prohibited as a narcotic, enforced." } },
  KG: { n:"Kyrgyzstan", def:'ill', st:{ ket:'med' }, nt:{ _:"Kyrgyzstan maintains a strict post-Soviet narcotics-control regime (Decree No 543/2007, aligned with the three UN drug conventions; list of new psychoactive substances expanded by Decree No 831 in 2015). Cannabis, CBD, and all classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline) plus cocaine and coca leaf are illegal and enforced, with no medical-cannabis or religious/indigenous exemptions. Cannabis possession carries 3-7 years. Ketamine is a registered WHO essential-medicine anesthetic (medical use legal, recreational illegal). Ibogaine is not separately scheduled but has no access pathway, so it falls under general prohibition. The death penalty was abolished in 2007 and is constitutionally barred (2nd Optional Protocol to ICCPR ratified 2010); maximum penalty is life imprisonment, so 'cap' does not apply. A December 2024 MP proposal to legalize 'light natural substances' has no legislative traction.", can:"Fully illegal and enforced; possession 3-7 years + confiscation, cultivation fined/imprisoned. Cannabis grows wild abundantly. Dec 2024 MP (Bekeshev) proposed legalizing 'light natural substances' but no legislative action.", cbd:"No legal distinction between CBD and cannabis, so consumer CBD products are illegal. Industrial hemp cultivation permitted only with a license.", ket:"WHO essential-medicine anesthetic, widely used in human/veterinary medicine; registered for medical use. Recreational use illegal.", ibo:"Not specifically named in the control list but no medical-approval or access pathway; falls under general prohibition.", coc:"Illegal and enforced. Death penalty abolished in 2007 (constitutionally barred); max penalty life imprisonment, so no capital punishment for drug offences.", coca:"No traditional use; controlled under UN conventions. Illegal." } },
  LA: { n:"Laos", def:'ill', st:{ cbd:'med', ket:'med' }, nt:{ _:"Laos prohibits effectively all controlled drugs under the Law on Narcotics (2007) and Penal Code (2017), with active enforcement and the death penalty retained for large-quantity trafficking (~90% of death row was drug-related per a 2023 Minister of Public Security statement; no executions since 1989, so abolitionist in practice but sentences still imposed). Cannabis, psilocybin, LSD, MDMA, DMT, mescaline, cocaine, coca leaf and (absent any specific framework) ibogaine are all illegal and enforced (ill). Two medical carve-outs: ketamine is a hospital anaesthetic / WHO essential medicine (med), and CBD/hemp gained a regulated medical & cosmetic framework via Ministry of Health Decision No. 3789/MOH (Dec 2022) limiting products to <=0.2% THC with CBD>=4x THC (med, licensed only) — general recreational CBD remains illegal. Tourist-area tolerance of cannabis/mushrooms exists informally but police run enforcement operations and foreigners face the same penalties, so the operative status is enforced prohibition rather than de-facto tolerance.", can:"Illegal and enforced under Law on Narcotics (2007) & Penal Code (2017); penalties up to life imprisonment for THC concentrates. Despite visible tourist-zone activity (e.g. Vang Vieng), police conduct enforcement ops; foreigners not exempt. Large-quantity trafficking can carry the death penalty.", cbd:"Recreational CBD/cannabis illegal, BUT Ministry of Health Decision No. 3789/MOH (Dec 2022) created a regulated medical/industrial hemp framework: medical hemp products <=0.2% THC with CBD>=4x THC; registered CBD-dominant cosmetics, drinks and aromatic oils may be sold/used generally via the Food & Drug Dept. Licensed/registered only.", psi:"Prohibited; sold de-facto to tourists in some areas but enforcement operations occur and intent-to-sell penalties are severe (life imprisonment / capital risk for large quantities).", mdma:"Prohibited; death penalty applies to trafficking >=3,000g of amphetamines or 'other psychotropic substances'.", dmt:"Prohibited as a psychotropic; no religious/ayahuasca exemption known.", ket:"WHO essential medicine used as a hospital anaesthetic; medical/clinical use accepted, recreational use illegal.", ibo:"No Laos-specific scheduling or therapeutic framework found; falls under general psychotropic prohibition by default.", coc:"Explicitly prohibited (0.2-100g = 10-15 yrs); trafficking large quantities can carry life imprisonment or the death penalty.", coca:"No traditional/indigenous use or exemption; prohibited as a narcotic." } },
  LV: { n:"Latvia", def:'decrim', st:{ cbd:'tol', ket:'med' }, nt:{ _:"Latvia (EU member) operates a personal-use decriminalization regime: first-time possession of small amounts of ANY illicit drug (cannabis, psychedelics, MDMA, cocaine, etc.) is an administrative offence (warning or fine up to EUR 280), with criminal liability for repeat offences within 12 months and for larger amounts/supply. There is no recreational legalization and no functioning medical-cannabis or psychedelic-therapy access program. CBD from hemp (<0.2% THC) is legal. Ketamine is a registered medicine and esketamine (Spravato) is EMA-approved and available EU-wide including Latvia. As of 2025-2026, reform debate is active (notably removing criminal liability for drug USE by minors), but possession/purchase liability remains. No death penalty. Confidence medium because the per-substance 'decrim' coding reflects the uniform personal-possession administrative framework rather than substance-specific carve-outs; supply of all listed substances remains criminally enforced.", can:"Illegal for recreational and medical use, but possession of small amounts for personal use (e.g. up to ~1 g) is a de-facto-decriminalized administrative offence (warning or fine up to EUR 280) on first occurrence; repeat within 12 months or larger amounts/supply = criminal. No functioning medical cannabis program.", cbd:"CBD from industrial hemp with <0.2% THC permitted in line with EU rules; no dedicated retail framework but legal in practice.", psi:"Controlled narcotic; personal-use small-amount possession is an administrative offence (EUR 280 fine), classified as decriminalized by Psychedelic Alpha; larger amounts/supply criminal (up to 3-8 yrs).", lsd:"Controlled; small-amount personal possession administrative (decriminalized), larger amounts criminal (up to ~10 yrs).", mdma:"Controlled; small-amount personal possession administrative/decriminalized, supply criminal.", dmt:"Controlled; same general personal-possession decriminalization regime; no religious/ayahuasca exemption known.", mes:"Controlled; same personal-possession administrative regime; no peyote/San Pedro religious exemption.", ket:"Registered medicine; esketamine (Spravato) is EMA-approved EU-wide for treatment-resistant depression and available in Latvia. Recreational use illegal.", ibo:"Controlled substance; no medical/therapeutic access; subject to the general personal-possession administrative regime.", coc:"Refined cocaine is a controlled drug; small-amount personal possession is an administrative offence under Latvia's general decriminalization regime, but trafficking/supply is criminal. No capital punishment.", coca:"No traditional use; coca leaf controlled. Falls under the same personal-possession administrative regime as other drugs; not legally available." } },
  LB: { n:"Lebanon", def:'ill', st:{ ket:'med' }, nt:{ _:"Lebanon's Narcotic Drugs and Psychotropic Substances Law No. 673 (1998) prohibits the production, possession, use, transport and sale of all first-category narcotics and hallucinogens except under special medical/scientific permits. Personal possession carries 3 months–3 years imprisonment; trafficking up to life. There is NO death penalty for drug trafficking in Lebanon (Lebanon is absent from capital-punishment-for-drugs lists; the only capital provision in Law 673 is for killing an enforcement official) — so no 'cap'. Cannabis is the notable exception: medical and industrial cultivation was legalized in April 2020 (the first Arab country to do so) and the government began activating the licensing regime in 2025; however recreational/personal cannabis use remains a criminal offence (→ ill), and CBD has no separate legal consumer market (→ ill). Psilocybin, LSD, MDMA, DMT/ayahuasca and mescaline are all prohibited hallucinogens with no decriminalization or therapy program (→ ill). Ketamine is a registered medicine/anesthetic (→ med). Ibogaine has no approved access (→ ill). Refined cocaine and raw coca leaf are both prohibited (→ ill); Lebanon has no traditional coca use. Confidence is high for the cannabis/CBD regime and the overall Law 673 prohibition framework, but medium overall because Lebanon does not appear in the major substance-specific psychedelic trackers (Psychedelic Alpha, Wikipedia psychedelic-by-country lists), so the classic-psychedelic and ibogaine classifications are inferred from Law 673's blanket prohibition rather than substance-specific sources.", can:"Medical/industrial cannabis cultivation legalized April 2020 (first Arab country); govt activated the licensing framework in 2025. Recreational/personal use remains illegal under Law 673 (3 mo–3 yr prison), though Bekaa Valley enforcement is patchy.", cbd:"No separate consumer CBD market; CBD falls under the same medical/industrial cannabis regime (THC <1%) and is otherwise a controlled substance — not legal for general use.", psi:"Prohibited hallucinogen under Law 673 (1998); no medical/research access pathway in practice.", dmt:"No religious/indigenous exemption; ayahuasca and DMT prohibited as first-category hallucinogens under Law 673.", ket:"Registered medicine/anesthetic; controlled under national narcotics framework. Recreational use illegal.", coc:"First-category narcotic; trafficking can carry up to life imprisonment (no death penalty for drug offences in Lebanon)." } },
  LS: { n:"Lesotho", def:'ill', st:{ ket:'med' }, nt:{ _:"Lesotho controls drugs under the Drugs of Abuse Act 2008 (UN-convention model: substances reserved for medical/scientific use, otherwise prohibited; trafficking is a serious criminal offence). It legalized licensed MEDICINAL cannabis cultivation in 2017 (first in Africa) but has NO patient-access program and treats consumer cannabis/CBD as illegal. Classical psychedelics (psi/LSD/MDMA/DMT/mescaline), ibogaine, cocaine and coca leaf are prohibited; ketamine is a registered medicine (med). Lesotho is de-facto abolitionist, so no capital punishment for drug offences (not 'cap'). Confidence medium: cannabis/CBD/death-penalty facts well-sourced; psychedelic scheduling inferred from the Act's general structure since Psychedelic Alpha does not list Lesotho.", can:"Recreational illegal. Licensed medicinal/scientific cannabis CULTIVATION legal since 2017 (first African country; Drug of Abuse (Cannabis) Regulations 2018) but it is an export/pharma cultivation regime with NO domestic medical-marijuana/patient-access program.", cbd:"No separate CBD/hemp consumer carve-out; CBD products treated as cannabis and effectively illegal for the public (travellers advised to leave even CBD at home). Only handled within the licensed medical-cultivation framework.", psi:"Controlled under the Drugs of Abuse Act 2008 (UN-convention-based schedules; medical/scientific only, recreational prohibited and trafficking a serious offence). Not individually documented for Lesotho.", lsd:"Prohibited controlled substance under the Drugs of Abuse Act 2008 (UN-convention schedules).", ket:"Registered medicine under the Drugs of Abuse Act 2008 medical/scientific framework; recreational use illegal (default classification, no Lesotho-specific source).", coca:"No traditional/indigenous use; not exempted. Prohibited under the Drugs of Abuse Act 2008." } },
  LR: { n:"Liberia", def:'ill', st:{ ket:'med' }, nt:{ _:"Liberia prohibits all the listed substances under the Controlled Drugs and Substances Act 2014, amended and re-signed into law by President Weah in July 2023. Cannabis (and CBD, which gets no separate treatment) is a Schedule 1 drug; there is no medical cannabis program and no religious/indigenous carve-outs for ayahuasca, peyote, etc. The 2023 amendment made cultivation/manufacture/trafficking a non-bailable first-degree felony punishable by life imprisonment, while personal use/consumption is a bailable second-degree felony — so substances are 'ill' (enforced), not 'cap' (no death penalty for drug offences). Ketamine is the exception: it is on Liberia's WHO Essential Medicines List (2023) and widely stocked for anaesthesia, so it is classified 'med'. No evidence of any decriminalization, medical-psychedelic, or coca-leaf provisions. Confidence is high for cannabis/CBD/ketamine and medium for the remaining substances, which fall under the general prohibition with little substance-specific sourcing.", can:"Schedule 1 under the Controlled Drugs and Substances Act 2014 (amended 2023). Personal use/consumption is a bailable second-degree felony; cultivation/manufacture/trafficking is a non-bailable first-degree felony carrying life imprisonment. Widely grown in practice but enforced.", cbd:"No legal distinction from cannabis; treated identically as Schedule 1. No medical cannabis or CBD program.", dmt:"No religious/indigenous ayahuasca exemption; covered by general controlled-substances prohibition.", ket:"On Liberia's WHO Essential Medicines List (2023); reported available in ~88% of health facilities for anaesthesia. Medical/hospital use legal; non-medical use illegal.", coc:"Refined cocaine illegal; trafficking is a non-bailable first-degree felony (life imprisonment) under the 2023 amended Act.", coca:"No traditional/indigenous use; covered by general controlled-substances prohibition." } },
  LY: { n:"Libya", def:'ill', st:{ ket:'med', coc:'cap' }, nt:{ _:"Libya prohibits all recreational and medical drug use with no reform underway as of 2026. Cannabis (and CBD by extension) is fully illegal — no medical program, ~2-year sentences for possession/use. All psychedelics (psilocybin, LSD, MDMA, DMT, mescaline, ibogaine) are prohibited with no medical/research carve-outs; major trackers (Psychedelic Alpha) do not even list Libya. Ketamine is rated 'med' as a registered anaesthetic (recreational use illegal), though Libya-specific scheduling was not confirmed. Refined cocaine is rated 'cap' because Libya retains the death penalty for drug trafficking under its Penal Code (Harm Reduction International lists it as retentionist with 'insufficient data' on application). Coca leaf is illegal. Confidence is medium: cannabis prohibition and the capital-trafficking framework are well-sourced, but psychedelic/ketamine statuses are inferred from blanket prohibition plus 1971 Convention obligations rather than Libya-specific published schedules.", can:"Fully illegal; no medical or recreational program. Possession/use punishable by ~2-year prison sentence.", cbd:"Not established as a distinct legal consumer category; treated under cannabis prohibition, not assumed lawful.", psi:"No medical/research pathway; prohibited as a psychotropic under 1971 Convention obligations.", ket:"Inferred 'med': ketamine is a registered anaesthetic essential to surgical care regionally; recreational use illegal. No Libya-specific scheduling confirmed.", coc:"Refined cocaine illegal; trafficking/large-scale possession can carry the death penalty under Libya's Penal Code (retentionist, though application data is limited).", coca:"No traditional/legal use; illegal." } },
  LI: { n:"Liechtenstein", def:'ill', st:{ cbd:'tol', ket:'med' }, nt:{ _:"Liechtenstein criminalizes drugs under its 1983 Law on Narcotics and Psychotropic Substances (Betäubungsmittelgesetz), aligned with the UN drug conventions. Cannabis (recreational) and all classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline, ibogaine), cocaine and coca leaf are illegal and enforced — no Swiss-style limited-medical psychedelic program exists. Ketamine is a registered medicine (med). Low-THC CBD sits in a tolerated gray area (the country's threshold is 1% THC), with industrial hemp banned since 2005. Penalties are real (up to 1 yr for possession, up to 3 yrs for supply of cannabis) but not capital and without long mandatory minimums. Cannabis/CBD are well-sourced for Liechtenstein specifically; psychedelic/cocaine classifications are inferred from the BMG's UN-convention adherence rather than a directly-read national substance schedule, hence medium confidence.", can:"Illegal under the 1983 Law on Narcotics and Psychotropic Substances (Betäubungsmittelgesetz). Possession of small amounts: fine up to ~1 yr prison; sale/cultivation up to 3 yrs. No recreational reform as of 2026; 2018 Free List reform proposal stalled.", cbd:"No specific ban. Liechtenstein defines cannabis as >1% THC, so low-THC CBD products fall outside prohibition (de-facto tolerated gray area). Industrial hemp itself banned since 2005. Not affirmatively regulated/legalized.", psi:"Controlled narcotic/psychotropic under the BMG (UN-convention aligned). No medical or religious access pathway; illegal and enforced. Unlike neighboring Switzerland, Liechtenstein has no limited-medical-use psychedelic program.", mdma:"Controlled psychotropic under the BMG; illegal and enforced, no medical/research carve-out identified.", ket:"Registered anesthetic medicine in the European/Liechtenstein market (medical use legal); recreational use illegal.", ibo:"No legal access pathway and not a registered medicine in Liechtenstein; treated as a controlled substance — conservative 'ill'.", coc:"Refined cocaine illegal and enforced under the BMG; reportedly growing demand among youth/foreign students.", coca:"Raw coca leaf controlled under the UN Single Convention framework; no traditional-use exemption — illegal." } },
  LT: { n:"Lithuania", def:'ill', st:{ cbd:'tol', ket:'med' }, nt:{ _:"Lithuania is a strict-enforcement EU member state. All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline), ibogaine, cocaine and coca leaf are Schedule I/controlled and illegal & enforced (possession up to 2 yrs, trafficking 2-15 yrs). Recreational cannabis is criminal, though small possession draws administrative fines and a nominal but non-functional medical-cannabis framework exists. CBD (THC <=0.2%) is legal. Ketamine is a registered medical anaesthetic (med). No death penalty (EU member). Repeated decriminalization bills have failed, so 'decrim' was not assigned despite lighter administrative handling of small amounts since 2017.", can:"Recreational cannabis is a criminal offence (Penal Code Art. 259); possession <5g is handled as an administrative violation (fine) but not formally decriminalized. Medical cannabis nominally legal since 2019 law (for cancer, MS, epilepsy, AIDS) but program effectively non-functional with no domestic cultivation and essentially no patients receiving it — so coded 'ill' for the recreational/general line.", cbd:"CBD legal when THC <=0.2%; production of industrial-hemp products permitted since 2021.", psi:"Schedule I narcotic; possession up to 2 yrs imprisonment, trafficking 2-15 yrs. No therapy/research access. Small-amount possession since 2017 may draw lighter (administrative/community-service) penalties but decriminalization bills repeatedly failed.", lsd:"Schedule I; illegal and enforced.", mdma:"Schedule I; illegal and enforced.", dmt:"DMT/ayahuasca controlled; no religious/indigenous exemption; illegal.", mes:"Mescaline controlled; illegal.", ket:"Registered anaesthetic medicine (medical/clinical use legal); recreational use illegal.", ibo:"Ibogaine has no medical approval; controlled/illegal.", coca:"Coca leaf appears on Lithuania's controlled-substances schedule (per UN conventions); illegal, no traditional-use exemption." } },
  LU: { n:"Luxembourg", def:'ill', st:{ can:'legal', cbd:'legal', ket:'med' }, nt:{ _:"Luxembourg legalized adult-use cannabis home cultivation (up to 4 plants/household) and private consumption on 21 July 2023, with public possession up to 3g decriminalized to a fine; no commercial retail exists, so coded decrim. CBD is freely legal (<1% THC). All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) and ibogaine, plus refined cocaine and raw coca leaf, are Schedule I narcotics under the Law of 19 Feb 1973 and enforced (ill); personal use carries 8 days-6 months. Ketamine is a prescribable controlled medicine (med). Luxembourg has abolished the death penalty, so no capital-punishment classification applies.", can:"Adult-use reform in force since 21 Jul 2023: home cultivation of up to 4 plants per household and private consumption legal for 18+; public possession up to 3g reduced to a small fine (decriminalized). No legal commercial/retail market; public consumption still penalized.", cbd:"CBD legal and sold without prescription; non-medical products permitted below 1% THC (plant classified as narcotic above 0.3% THC).", psi:"Magic mushrooms/psilocybin prohibited under the 1973 Narcotics Law; personal use punishable by 8 days-6 months imprisonment.", mdma:"Schedule I under the 1973 Narcotics Law; simple use punishable by 8 days-6 months imprisonment and/or fine.", ket:"Registered medicine/anesthetic, available on prescription as a controlled medicinal product; recreational use illegal.", coca:"No traditional/indigenous-use exemption; coca leaf controlled as a narcotic and illegal." } },
  MK: { n:"Macedonia", def:'ill', st:{ can:'med', cbd:'legal', ket:'med' }, nt:{ _:"North Macedonia follows the UN 1961/1971 conventions via its Law on Control of Narcotic Drugs and Psychotropic Substances. Medical cannabis is legal and a significant export industry (since 2016; recreational never legalized despite a 2020 proposal). CBD/low-THC (<0.2%) products are sold OTC. All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) plus cocaine and coca leaf are Schedule I and illegal; ketamine is a registered medical/veterinary anaesthetic only. Personal-use possession of small quantities is on paper a fine-only misdemeanour, but is frequently prosecuted under the Criminal Code, so substances are coded 'ill' rather than 'decrim'. No death penalty for drug offences. Ibogaine has no special status (low confidence).", can:"Medical cannabis legal since 2016 (>0.2% THC by prescription; ~100 licensed processors by 2025, major exporter to Germany). Recreational illegal; 2020 PM proposal to legalize never enacted. Personal possession of small amounts (~5g) is nominally a fine-only misdemeanour but often charged under the Criminal Code in practice.", cbd:"CBD/low-THC products (<0.2% THC) available over-the-counter in pharmacies and shops nationwide; non-psychotropic cannabinoid (CBD) content not legally restricted.", psi:"Schedule I psychotropic under Law on Control of Narcotic Drugs and Psychotropic Substances (per 1961/1971 UN conventions). No therapeutic exemption.", mdma:"Schedule I; illegal. Personal-use possession nominally a fine-only misdemeanour, larger amounts criminal (3-10 yrs for production/supply).", ket:"Registered anaesthetic (brand 'Ketax') for medical/veterinary use only; not approved for psychiatric (e.g. TRD/PTSD) or recreational use; unauthorized possession punishable.", ibo:"No approval or special pathway found; treated as prohibited/controlled. Low confidence.", coc:"Schedule I narcotic, illegal and enforced (~2g personal-use misdemeanour threshold; supply 3-10 yrs).", coca:"No traditional/indigenous use; falls under controlled narcotics with no legal market." } },
  MG: { n:"Madagascar", def:'ill', st:{ ket:'med' }, nt:{ _:"Madagascar prohibits cannabis (and CBD, treated identically) for all uses with no medical programme; possession draws 2 months-5 years and trafficking up to 20 years, and the law is enforced despite very high domestic cannabis consumption. All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) and cocaine/coca fall under blanket narcotics prohibition with no religious, indigenous, or research carve-outs found. Ketamine is the lone exception as a registered anaesthetic medicine. Madagascar abolished the death penalty in 2015, so no drug offence is capital. Confidence is medium: cannabis/CBD/cocaine/ketamine are well sourced, but Madagascar-specific scheduling detail for the individual psychedelics is thin and inferred from the general prohibition.", can:"Illegal for all uses incl. medical; possession 2 months-5 yrs + fines, trafficking up to 20 yrs. Widely cultivated/consumed (one of Africa's highest rates) but law is enforced.", cbd:"No legal distinction from cannabis; CBD/hemp products not permitted for sale, possession or use. No medical cannabis programme.", mdma:"No carve-out; covered by general narcotics prohibition. Note: Madagascar abolished the death penalty entirely in 2015, so no capital drug offences.", ket:"Registered medicine; critical for anaesthesia in Sub-Saharan Africa per WHO essential medicines. Recreational use illegal.", coc:"Illegal and enforced; Madagascar is a known maritime trafficking/trans-shipment hub for cocaine and heroin.", coca:"No traditional/indigenous use; illegal." } },
  MW: { n:"Malawi", def:'ill', st:{ ket:'med' }, nt:{ _:"Malawi (MW): Cannabis is illegal for recreational use (possession can carry harsh sentences on paper but is widely used and lightly enforced for personal use); medical cannabis and industrial hemp — including CBD extraction — are legal under license via the Cannabis Regulation Act 2020 and Cannabis Regulatory Authority, with a March 2024 amendment allowing licensed cultivation of the potent local 'chamba' variety. CBD = med (licensed medical/hemp framework). Ketamine = med (essential hospital anaesthetic; recreational use illegal). Classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline, ibogaine) have no special medical/decrim status — Malawi is absent from psychedelic-law trackers and these fall under the general Dangerous Drugs Act prohibition = ill. Coca leaf and refined cocaine are both explicitly scheduled = ill. Death penalty applies only to murder/treason (moratorium since 1992), NOT drug offences, so 'cap' is not warranted for any substance. Confidence medium: cannabis/CBD/ketamine well-sourced; psychedelic classifications rest on absence of any country-specific permissive regime.", can:"Recreational cannabis illegal; possession of 'Indian hemp' carries severe penalties on paper (up to life imprisonment under Dangerous Drugs Act Ch. 35:02), but use of local 'chamba' is widespread and personal-use enforcement is relatively uncommon. Medical/industrial cannabis legalized under the Cannabis Regulation Act 2020 (Cannabis Regulatory Authority); March 2024 amendment authorized licensed cultivation of the potent local chamba variety for industrial/medicinal use.", cbd:"Legal under the licensed medical-cannabis/industrial-hemp framework (Cannabis Regulation Act 2020); cannabinoids incl. CBD are extracted for medicinal/nutraceutical use under Cannabis Regulatory Authority licences. No separate consumer free-sale regime confirmed, so treated as medical/regulated.", ket:"Widely used as an essential anaesthetic in Malawi's district hospitals (follows WHO Essential Medicines List); recreational use prohibited.", coc:"Cocaine explicitly scheduled as a dangerous drug under the Dangerous Drugs Act; illegal and enforced. Note: Malawi's death penalty applies to murder/treason only, not drug offences (execution moratorium since 1992), so capital punishment does not apply.", coca:"Coca leaf explicitly scheduled as a dangerous drug under the Dangerous Drugs Act; no traditional/indigenous use (non-Andean country)." } },
  MY: { n:"Malaysia", def:'ill', st:{ can:'cap', ket:'med', coc:'cap' }, nt:{ _:"Malaysia maintains one of the world's strictest drug regimes under the Dangerous Drugs Act 1952. Cannabis, all classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline), ibogaine, cocaine and coca leaf are illegal and actively enforced. Trafficking above statutory thresholds (e.g. cannabis >=200g, cocaine >=40g, heroin >=15g, meth >=10g) can carry the death penalty; since the July 2023 Abolition of Mandatory Death Penalty Act this is now at judicial discretion (death OR life imprisonment + caning) rather than mandatory, and the death-row drug population has fallen sharply. Ketamine is a controlled medicine (Poisons Act) available via licensed practitioners (recreational use illegal). CBD has no independent legal status and is treated as cannabis; the Health Ministry opened a registration pathway for cannabis-based medical products in March 2025, but none are yet approved, so there is no real-world medical access. No decriminalization, religious/indigenous, or recreational exemptions exist. can and coc marked 'cap' due to documented capital trafficking thresholds; other prohibited substances marked 'ill' conservatively, though large-quantity trafficking of any First Schedule drug can in principle also attract capital punishment.", can:"Illegal; trafficking >=200g cannabis (or 50g resin) can carry the death penalty under the Dangerous Drugs Act 1952 (now discretionary since the 2023 abolition of the MANDATORY death penalty). Possession <20g up to 5 yrs + fine.", cbd:"No separate legal carve-out; regulated as a cannabis/dangerous drug. Health Ministry opened registration for cannabis-based medical products (incl. CBD) in March 2025, but none are currently approved/registered, so de facto illegal.", lsd:"Controlled dangerous drug, illegal and enforced.", mdma:"Ecstasy/MDMA explicitly illegal and enforced under the Dangerous Drugs Act; trafficking carries severe penalties incl. possible capital punishment for large quantities.", ket:"Controlled medicine under the Poisons Act 1952; available via licensed pharmacists/practitioners. Recreational possession/sale illegal.", coc:"Refined cocaine illegal; trafficking >=40g can carry the death penalty (discretionary since 2023).", coca:"No traditional/indigenous use; treated as a controlled dangerous drug, illegal." } },
  MV: { n:"Maldives", def:'cap', st:{ cbd:'ill', ket:'med', ibo:'ill', coca:'ill' }, nt:{ _:"Maldives operates one of the world's strictest drug regimes. The Drug Act (Law 17/2011, amended) controls substances per the UN 1961 and 1971 Conventions, so cannabis and all classic psychedelics, cocaine and coca leaf are illegal and enforced. Amendments ratified 6 Dec 2025 and in force March 2026 introduced the death penalty for trafficking, with thresholds of >350g cannabis, >250g heroin, and >100g of any other illicit substance (Supreme Court must rule unanimously; otherwise life imprisonment + heavy fines). Cannabis, psilocybin, LSD, MDMA, DMT, mescaline and refined cocaine all fall within these capital thresholds (=cap). Possession of even <1g carries 5-12 years. There is no medical cannabis program and no CBD/THC distinction (CBD=ill). Ketamine is the lone exception, available as a regulated medical anaesthetic (=med). CBD, coca leaf and ibogaine are classified ill conservatively (no confirmed capital-threshold treatment / no access pathway). No religious or indigenous exemptions exist.", can:"Illegal, no medical/CBD distinction. Trafficking >350g cannabis is a capital offence under amended Drugs Act (ratified Dec 2025, in force Mar 2026); possession can carry up to 15 yrs.", cbd:"No legal distinction from cannabis; all cannabis-derived products illegal. No medical CBD program. Capital exposure attaches to cannabis quantity thresholds.", psi:"UN-scheduled psychotropic; illegal & enforced. Falls under 'other illicit substances' (>100g) capital trafficking threshold. No research/medical access.", lsd:"UN-scheduled; illegal & enforced. Trafficking covered by >100g 'other illicit substances' death-penalty threshold.", mdma:"Ecstasy present and prosecuted; illegal & enforced. Trafficking covered by capital >100g threshold. Possession 5-12 yrs.", dmt:"DMT/ayahuasca UN-scheduled; illegal & enforced. No religious/indigenous exemption. Capital trafficking exposure.", mes:"Mescaline UN-scheduled; illegal & enforced. No peyote/San Pedro exemption.", ket:"Registered medical anaesthetic regulated by Maldives FDA Medicine & Therapeutic Goods Division; recreational use illegal.", ibo:"No Maldives-specific data; not internationally scheduled but no medical/research access pathway exists under the strict regime. Conservative classification.", coc:"Refined cocaine illegal & enforced; trafficking covered by >100g 'other illicit substances' capital threshold.", coca:"Coca leaf illegal; no traditional/indigenous use. UN-controlled narcotic." } },
  ML: { n:"Mali", def:'ill', st:{ ket:'med' }, nt:{ _:"Mali prohibits and enforces against essentially all listed substances under Law No. 01-078 of 18 July 2001 (drug and precursor control), backed by the earlier Law 83/14 (1983) and Mali's accession to the 1961/1971/1988 UN drug conventions. Cannabis, cocaine and all psychedelics (psilocybin, LSD, MDMA, DMT, mescaline) sit in the most restrictive category with no medical, research, religious or decriminalization framework; CBD is treated the same as cannabis. Typical penalties are 2-10 years imprisonment plus fines and asset confiscation. Ibogaine and coca leaf have no traditional or legal access and fall under the general prohibition. Ketamine is marked 'med' by default as a registered anaesthetic (recreational use illegal); no Mali-specific source confirmed this. Mali retains capital punishment but is abolitionist in practice (no executions since 1980), and is NOT on the recognized list of states imposing the death penalty for drug trafficking alone (recent death sentences involving 'trafic de stupefiants' were attached to murder/armed-robbery charges), so 'cap' was deliberately not assigned. Refined cocaine is distinguished from raw coca leaf, but both are illegal here.", can:"Illegal, enforced; rooted in French colonial-era law. No recreational/medical distinction. Penalties 2-10 yrs prison + fines (100k-5M CFA) and asset seizure.", cbd:"No dedicated CBD legislation; derived from cannabis and treated identically -> illegal.", dmt:"Controlled under 1971 UN Convention as implemented in Malian law; no religious/indigenous ayahuasca exemption (not a Malian tradition).", ket:"No Mali-specific data; classified 'med' per default that ketamine is a registered anaesthetic/essential medicine (recreational use illegal). Medium confidence.", coc:"Illegal and enforced; Mali is a major cocaine transit country toward Europe.", coca:"Coca leaf not traditional in Africa; controlled as a cocaine source -> illegal." } },
  MT: { n:"Malta", def:'ill', st:{ can:'legal', cbd:'legal', ket:'med' }, nt:{ _:"Malta has fully legalized personal adult-use and medical cannabis plus retail CBD, but all other listed psychedelics and stimulants remain illegal controlled substances. Personal-possession of hard drugs is diverted to fines/treatment under the Drug Dependence (Treatment not Imprisonment) Act rather than imprisonment, yet possession stays a criminal offence and trafficking/larger amounts carry prison. Ketamine is a registered medicine. Capital punishment was fully abolished in 2000, so no death penalty for drug offences.", can:"First EU country to legalize personal adult use (Dec 2021, Ch. 628). Adults 18+ may carry 7g, store 50g, grow 4 plants/household; non-profit Cannabis Harm Reduction Associations distribute (19 permitted by 2025). Public smoking banned. Medical cannabis legal since 2018 (pharmacy-dispensed, non-smoking forms).", cbd:"Hemp-derived CBD <0.2% THC treated as non-narcotic under EU rules; sold openly in retail shops. 2025 amendments explicitly recognize CBD as non-psychoactive/non-narcotic.", psi:"Illegal controlled substance. Small personal-possession cases diverted to fines (EUR 75-125) / treatment under the Drug Dependence (Treatment not Imprisonment) Act, but possession remains a criminal offence.", mdma:"Illegal; small possession diverted to fine/treatment, larger amounts (>300 tablets threshold) escalate to higher courts with prison risk.", ket:"Registered medicine/anaesthetic; recreational use illegal.", ibo:"No Malta-specific provision; falls under general controlled-substance prohibition (low confidence).", coca:"No traditional-use exemption; treated same as refined cocaine." } },
  MR: { n:"Mauritania", def:'ill', st:{ ket:'med' }, nt:{ _:"Mauritania prohibits all the listed substances under a penal code influenced by Islamic sharia; cannabis and all narcotics/psychotropics are illegal to use, possess, sell or cultivate, and enforcement is active (regular seizures, trafficking prosecutions, hundreds of arrests) though resource-limited. There is no medical cannabis program, no CBD carve-out, and no religious/indigenous exemption for ayahuasca/DMT or peyote/mescaline — so there is no real-world legal access for patients or researchers to any psychedelic. Drug trafficking is technically capital-eligible under the penal code, but a de facto execution moratorium has held since 1987 (death sentences are substituted with long imprisonment), so substances are coded 'ill' rather than 'cap' to reflect real-world practice. Ketamine is coded 'med' on the near-universal assumption it functions as a controlled clinical/anaesthetic medicine (no Mauritania-specific source found). Confidence is medium overall: cannabis prohibition is well-documented, but psychedelic-specific scheduling and ketamine's exact status are inferred from the general controlled-substances framework rather than primary Mauritanian statute text.", can:"Illegal to grow, sell, possess or use; cannabis is the most widely consumed illicit drug and Mauritania is a major Morocco-to-Europe transit corridor. No medical/CBD carve-out.", cbd:"No legal distinction from cannabis; no regulated CBD market.", dmt:"No religious/indigenous ayahuasca exemption; falls under general narcotics/psychotropics prohibition.", mes:"No peyote/San Pedro exemption; prohibited under general narcotics law.", ket:"No Mauritania-specific data; treated as a controlled medicine available for clinical/anaesthetic use (recreational use illegal) per near-universal practice — low confidence.", coc:"Refined cocaine illegal; Mauritania is a key Sahel cocaine transit zone with active navy/customs interdiction and trafficking prosecutions.", coca:"Coca leaf has no traditional or legal status; prohibited as a narcotic." } },
  MU: { n:"Mauritius", def:'ill', st:{ ket:'med' }, nt:{ _:"Mauritius prohibits essentially all listed substances under the Dangerous Drugs Act 2000, with active enforcement. Recreational cannabis and all classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline), cocaine and coca are illegal (ill). A narrow medical-cannabis scheme exists on paper (Act 17 of 2022, 4 qualifying conditions, hospital pilot) but is barely operational; CBD has no clear legal route and is treated under prohibition. Ketamine is a registered hospital anaesthetic (med); recreational use illegal. Death penalty was abolished in 1995 (last execution 1987), so drug offences are NOT capital despite very long trafficking sentences (up to 45-60 yrs penal servitude) — hence 'ill', not 'cap'. Confidence medium: strong on cannabis/death-penalty/general prohibition; substance-by-substance scheduling for some psychedelics inferred from the Act's blanket First Schedule prohibition rather than per-drug confirmation.", can:"Recreational cannabis illegal & enforced under Dangerous Drugs Act 2000 (up to 10 yrs possession; police still raid/arrest). SEPARATE narrow medical-cannabis scheme exists in law via Dangerous Drugs (Amendment) Act 2022 (Act 17 of 2022) for 4 conditions (MS spasticity, refractory epilepsy, chemo nausea, intractable pain), dispensed only in regional hospitals; Victoria Hospital pilot 2023, specialist training 2024 — but barely operational and personal-use decriminalization provisions largely unproclaimed.", cbd:"No clear legal CBD framework; treated under cannabis prohibition. 2022 amendment contemplates CBD within the medical scheme but it is not operational — effectively prohibited/ambiguous.", ket:"Registered medicine/anaesthetic used in hospitals; recreational use illegal under Dangerous Drugs Act.", coc:"Illegal & enforced; drug trafficking carries up to 45-60 yrs penal servitude. NOTE: death penalty abolished 1995 (last execution 1987), so NOT capital — but very long mandatory-style sentences for trafficking.", coca:"No traditional use; coca/cocaine prohibited under Dangerous Drugs Act 2000." } },
  MX: { n:"Mexico", def:'ill', st:{ can:'decrim', cbd:'legal', dmt:'tol', ket:'med', ibo:'legal' }, nt:{ _:"Mexico operates a broad personal-use decriminalization regime (2009 narcomenudeo thresholds + 2021 Supreme Court cannabis ruling) but has no regulated recreational market. Cannabis = decrim (permits exist, no dispensaries); CBD = legal (<=1% THC products commercial). Classic psychedelics (psilocybin, LSD, MDMA, peyote) are Schedule I yet decriminalized for small personal amounts, with indigenous/spiritual exemptions for psilocybin and peyote. Ayahuasca/DMT tolerated de-facto. Ketamine = med (registered medicine). Ibogaine is unregulated — a major legal clinic destination (decrim/gray area). Refined cocaine illegal (small amounts decriminalized); raw coca leaf illegal with no traditional exemption.", can:"Recreational possession decriminalized by Supreme Court (Declaratoria General de Inconstitucionalidad 1/2018, 2021); adults can obtain free COFEPRIS personal cultivation/consumption permits and possess up to 28g. No commercial/dispensary market — Congress never passed the regulation law. Personal possession up to 5g not prosecuted under the 2009 narcomenudeo law.", cbd:"Legal. Products with <=1% THC sold commercially as supplements, cosmetics, and food; medical cannabis legal since 2017; COFEPRIS authorizing cannabinoid imports/registration (latest authorization Dec 2025).", psi:"Schedule I (Art. 245 General Health Law) but indigenous/spiritual ceremonial use is not punishable (Art. 195 bis); many psilocybin retreats operate; small personal amounts tolerated; 2021 amparo allowed therapeutic use for a specific group. Reform/legalization bills pending.", lsd:"Illegal, but personal possession up to 0.015 mg is treated as immediate personal consumption and not subject to criminal prosecution under the narcomenudeo law.", mdma:"Illegal, but personal possession up to ~40 mg powder or a single tablet (<=200 mg) is decriminalized for personal use; above thresholds up to ~7 years prison.", dmt:"DMT is scheduled/illegal on paper; ayahuasca ceremonies are de-facto tolerated and widespread (retreats), though non-indigenous use is not clearly legally protected.", mes:"Peyote/mescaline is Schedule I, but peyote use is legally permitted for indigenous spiritual ceremonies (notably the Wixarika/Huichol); the cactus is also a protected species under NOM-059.", ket:"Registered medicine; recreational/unprescribed possession is criminal (reported ~4-7 years prison).", ibo:"Unregulated and not a scheduled controlled substance; ibogaine clinics operate legally (largest concentration worldwide — Tijuana, Cancun, Puerto Vallarta), with facilities monitored by COFEPRIS. Legal gray area / de-facto permitted under clinical conditions.", coc:"Illegal and enforced; personal possession up to 0.5g is decriminalized (referral to treatment) under the narcomenudeo law, but the substance remains prohibited.", coca:"No traditional-use exemption in Mexico; raw coca leaf falls under general controlled-substance prohibition (illegal)." } },
  MD: { n:"Moldova", def:'ill', st:{ can:'decrim', ket:'med' }, nt:{ _:"Moldova applies a uniform model: under Article 85 of the Contravention (Administrative Offences) Code of 2008, simple possession and personal use of ALL drugs in small quantities — including cannabis and all psychedelics — is decriminalized (administrative fine of ~30-60 conventional units or community service up to 72 hours), not a criminal offence. All these substances nonetheless remain on the controlled/prohibited list, and production, sale and trafficking are serious crimes (up to ~15 years). There is no medical/therapeutic access program for cannabis or any psychedelic; ketamine is the only one available as a registered prescription medicine (med). CBD sits in a restricted grey area (<0.2% THC). A 2025 legislative package tightened penalties for drug distribution and online sales but did not alter personal-use decriminalization. A new National Strategy on Drugs and Addictions 2026-2032 is in development with Council of Europe support." } },
  MC: { n:"Monaco", def:'ill', st:{ ket:'med' }, nt:{ _:"Monaco operates a comprehensive prohibition regime under Loi n° 890 (1970) on stupefiants, expanded by Loi n° 1.157 (1992) for psychotropes, with the classified-substance list set by Arrete Ministeriel 2015-386; it is party to the 1961 UN Single Convention. Broadly modeled on French law but notably STRICTER on CBD, which Monaco treats as a narcotic with no low-THC tolerance (unlike France) — confirmed by an April 2025 conviction. Cannabis is illegal and enforced, with 2024-2025 prosecutions. All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) and cocaine/coca leaf are controlled narcotics with no medical/research/decrim exceptions. Ketamine is a registered medicine in active clinical use at the Centre Hospitalier Princesse Grace (med). Capital punishment was abolished in 1962; the maximum penalty is life imprisonment and trafficking carries 5-20 years, so no 'cap' classification applies. Confidence is medium: cannabis/CBD/ketamine rest on direct 2024-2026 sources, while the other substances are inferred from Monaco's unambiguous narcotics-classification framework rather than substance-specific citations (Monaco is not separately listed in the Psychedelic Alpha tracker).", can:"Illegal and actively enforced; 2024-2025 court cases (personal-use conviction + a drug-trafficking case). Personal use up to ~1 yr jail + fine; trafficking 5-20 yrs.", cbd:"Stricter than neighbouring France: Monaco classifies CBD as a narcotic with NO low-THC exception. Confirmed by an April 2025 prosecution where CBD spray/gum were seized and the defendant convicted.", psi:"Controlled narcotic/psychotrope; no medical, research or decrim carve-out.", dmt:"No religious/indigenous exemption; controlled as a stupefiant under Loi 890/1970 & Loi 1.157/1992.", ket:"Registered medicine in clinical use at Centre Hospitalier Princesse Grace (e.g. ketamine-infusion chronic-pain study); recreational/non-medical use illegal.", coca:"No traditional use; raw coca leaf controlled under the same narcotics framework as refined cocaine." } },
  MN: { n:"Mongolia", def:'ill', st:{ ket:'med' }, nt:{ _:"Mongolia is a party to the 1961/1971/1988 UN drug conventions, and its Law on Narcotic Drugs and Psychotropic Substances (2002, amended 2017) controls all substances on the convention schedules. Cannabis (incl. CBD) is fully illegal and enforced. Classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline) are Schedule I, illegal, with no medical/religious exemptions. Ketamine is a registered medical anesthetic (med). Cocaine and coca leaf are illegal Schedule I narcotics with no traditional use. Trafficking carries harsh sentences (8-15 yrs, life for organizers) but NOT the death penalty — Mongolia abolished capital punishment (effective 2017), so 'cap' does not apply. Ibogaine has no specific scheduling found and no real-world access; conservatively marked illegal with low confidence on that single item.", can:"Fully illegal (recreational + medical, incl. THC and CBD-dominant products). Possession of small amounts = administrative fine; larger amounts/intent = 2-8 yrs; trafficking 8-15 yrs. Authorities routinely destroy illegal crops.", cbd:"Treated as a cannabis derivative and prohibited even when CBD-dominant; CBD oil illegal. Plain hemp-seed oil with no significant CBD is tolerated.", dmt:"Controlled as 1971 Convention Schedule I; no known religious/ayahuasca exemption.", ket:"Registered medical anesthetic (1971 Convention framework); recreational/non-medical use illegal.", ibo:"No specific scheduling found and no medical approval or real-world access; treated as illegal/unavailable under the general controlled-substances framework. Genuinely uncertain on exact legal classification.", coca:"Controlled narcotic plant under the 1961 Convention; no traditional use in Mongolia; illegal." } },
  ME: { n:"Montenegro", def:'ill', st:{ cbd:'tol', ket:'med' }, nt:{ _:"Montenegro (EU candidate, party to 1961/1971 UN conventions) maintains a prohibitionist, enforced regime under its Criminal Code (Art. 300) and Law on Prevention of Drug Abuse (Gazette 28/11, 35/13, 84/24, in force since Oct 2024). Cannabis and all classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline), plus cocaine and coca leaf, are Schedule I and illegal with real enforcement; personal possession is penalized (fines/short jail) and supply carries 2-15 yrs. No enacted medical-cannabis program (a 2022 draft stalled) and no psychedelic decrim/research pathway. Ketamine is a registered medical anesthetic (med). CBD/hemp <0.2% THC is legal for industrial/food use since 2014 with CBD retail tolerated in practice. Conservative 'ill' assigned to ibogaine and coca leaf absent any permissive carve-out.", can:"Illegal Schedule I; recreational prohibited, no enacted medical-cannabis program (2022 draft never passed). Personal possession penalized (fine up to ~EUR2,000 and/or up to 60 days); cultivation up to 5 yrs. Not formally decriminalized.", cbd:"No specific CBD law; industrial hemp <0.2% THC legal since 2014 for food/industrial use and CBD shops operate openly in cities -> de-facto tolerated.", mdma:"Schedule I under UN 1971 Convention; no medical/research carve-out or decriminalization.", ket:"Controlled substance but registered/used as a medical anesthetic regionally; recreational use illegal (med per convention).", ibo:"No specific listing or approved use found; treated as prohibited under the general Schedule I framework (conservative).", coca:"No traditional/indigenous coca use; prohibited the same as refined cocaine." } },
  MA: { n:"Morocco", def:'ill', st:{ cbd:'med', ket:'med' }, nt:{ _:"Morocco controls drugs under Dahir 1-73-282 (1974) using UN-convention-based tables A/B/C; drug use is a criminal offence (2mo-1yr) and trafficking carries 5-10yrs up to a 30yr max. Cannabis & CBD now have a legal medical/industrial regime (Law 13-21, 2021; ANRAC regulator; products in pharmacies since mid-2024) while recreational cannabis stays illegal. All classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline, ibogaine) plus cocaine and coca leaf are illegal and enforced; ketamine is a registered medicine. NOT 'cap': although the death penalty technically exists, Morocco has a de-facto moratorium since 1993 (last execution), drug crimes are not a primary capital category, and it voted for the UN moratorium in Dec 2024 — so drug offences are classified 'ill', not capital.", can:"Recreational illegal & enforced (use: 2mo-1yr prison). Law 13-21 (2021) legalized cultivation/processing for medical, pharmaceutical & industrial use; ANRAC regulator since 2022, ~2,700ha legally cultivated in 2024. Hashish culturally widespread but possession/use remains a criminal offence.", cbd:"Permitted under Law 13-21 for medical/industrial/cosmetic use (<1% THC); CBD food & cosmetic products on pharmacy shelves since June 2024, but only via government-approved channels (no free retail/online sale).", psi:"Controlled psychotropic; illegal & enforced, no religious/research exemption.", mdma:"Illicit; criminal penalties for possession and trafficking.", ket:"Registered medicine (medical/veterinary use); recreational use illegal under narcotics/psychotropics law.", coc:"Refined cocaine is a prohibited narcotic, enforced.", coca:"No traditional use; treated as prohibited narcotic." } },
  MZ: { n:"Mozambique", def:'ill', st:{ ket:'med', ibo:'tol' }, nt:{ _:"Mozambique prohibits cannabis (incl. medical and CBD, no THC/CBD distinction) and all UN-scheduled narcotics/psychotropics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, cocaine, coca leaf) as criminal offences under its UN-convention-based drug law (Lei 3/97 framework). Personal cannabis possession carries a fine or up to 6 months; trafficking up to ~20-30 years. The death penalty was abolished in 1990, so no drug offence is capital (cap ruled out). Ketamine is an available registered medicine (med). Ibogaine is unscheduled/unregulated and Mozambique is noted as a gray-zone treatment destination (decrim). Enforcement of cannabis is lax in rural areas, but it remains illegal on paper and prosecuted, so 'ill' rather than 'tol'. No religious/indigenous exemptions exist for ayahuasca, peyote, or other entheogens. Confidence medium: no granular Mozambique-specific national controlled-substances schedule was located, so non-cannabis substances are classified via UN-convention obligations; Psychedelic Alpha does not list Mozambique.", can:"Fully illegal (use, possession, cultivation, sale) incl. medical; no CBD/THC distinction. Personal possession: fine or up to 6 months prison; trafficking up to ~20-30 yrs. Enforcement lax in rural areas but still a criminal offence.", cbd:"No legal distinction from cannabis; CBD products illegal, no medical/wellness exemption.", dmt:"Scheduled psychotropic under UN-convention-based drug law; no ayahuasca religious/indigenous exemption.", ket:"Registered medicine/anaesthetic (WHO essential medicines list); medical use available, recreational use illegal.", ibo:"Unscheduled / not specifically regulated; cited as a gray-zone destination for ibogaine treatment (no formal ban, no formal approval).", coca:"No traditional use or exemption in Mozambique; falls under narcotics prohibition like cocaine." } },
  MM: { n:"Myanmar", def:'ill', st:{ can:'cap', mdma:'cap', ket:'med', coc:'cap' }, nt:{ _:"Myanmar (MM) operates under the 1993 Narcotic Drugs and Psychotropic Substances Law (amended Feb 2018), a UN-convention-aligned regime that prohibits all the listed psychoactives except ketamine as a medicine. Section 20 sets 15 years to death for production/distribution/sale/import/export, and Myanmar resumed executions in July 2022 after a 30+ year pause, so capital/severe sentences are not merely theoretical for serious trafficking. Cannabis and CBD are fully illegal with no medical program or hemp carve-out. Classic psychedelics (psilocybin, LSD, DMT/ayahuasca, mescaline) and ibogaine are scheduled and illegal with no patient/research access. Ketamine is a registered hospital anaesthetic (med) though also widely trafficked illicitly. Cannabis, MDMA and cocaine are marked 'cap' to reflect that their trafficking can trigger the death penalty under s.20; less-trafficked substances are marked 'ill' conservatively. Coca leaf has no traditional use and is prohibited. Note: post-2021-coup governance is fragmented and large border/ethnic-controlled regions (e.g. Shan State) are de-facto outside central enforcement, but on-paper law and patient/researcher access are as stated.", can:"Fully illegal, no medical or CBD carve-out. Possession 3-5 yrs; distribution/sale/import/export carries 15 yrs to death under s.20 of the 1993 Narcotic Drugs & Psychotropic Substances Law (amended 2018).", cbd:"No legal distinction from cannabis; treated as a prohibited cannabis product. No hemp/CBD exemption, including for travellers.", psi:"Classic psychedelic controlled under the 1971-convention-derived psychotropic schedule; illegal and enforced, no medical/research access pathway.", lsd:"Scheduled psychotropic substance; illegal and enforced.", mdma:"Scheduled psychotropic substance; trafficking falls under s.20 (15 yrs to death). Synthetic-drug trafficking is heavily targeted.", dmt:"Illegal; no religious/ayahuasca exemption.", mes:"Illegal; no peyote/San Pedro exemption (no indigenous tradition).", ket:"Controlled psychotropic substance but available as a registered hospital anaesthetic; non-medical use illegal. Myanmar is also a major illicit ketamine production/trafficking hub (Shan State).", ibo:"No legal medical or addiction-treatment pathway; treated as an unapproved controlled substance, illegal.", coc:"Refined cocaine fully illegal; trafficking subject to s.20 severe/capital penalties. No medical or traditional use.", coca:"No traditional/indigenous use; not cultivated locally. Prohibited." } },
  NA: { n:"Namibia", def:'ill', st:{ ket:'med' }, nt:{ _:"Namibia maintains strict drug prohibition under the Abuse of Dependence-Producing Substances and Rehabilitation Centres Act 41 of 1971 (supplemented by the 2006 Combating of the Abuse of Drugs Bill, penalties of 20-40 years). Cannabis, CBD, and all classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) plus cocaine and coca leaf are illegal and enforced — no decrim, medical, or religious/indigenous carve-outs exist, and Namibia appears in no psychedelic-reform tracker. The Feb 2026 High Court ruling reaffirmed cannabis prohibition. Ketamine is the sole 'med' case: a registered Schedule-3 prescription medicine used in anaesthesia. The death penalty was constitutionally abolished in 1990, so no drug offence carries capital punishment (no 'cap'). Confidence is medium: cannabis/CBD/ketamine are well-sourced; the specific psychedelics and coca rely on the inherited statutory framework and UN-convention obligations rather than a published Namibia-specific schedule, but all clearly indicate prohibition with no access pathway.", can:"Illegal & enforced under Abuse of Dependence-Producing Substances Act 41 of 1971; Windhoek High Court upheld prohibition Feb 2026 (Swartbooi case); >115g presumes dealing. No medical exception (only synthetic THC/dronabinol available on prescription).", cbd:"No legal distinction from cannabis; technically illegal though products circulate informally/online. Govt ruled out commercial medical cannabis cultivation in 2024.", psi:"Controlled under 1971 Act as prohibited dependence-producing substance; no medical/research/decrim pathway. Not listed in Psychedelic Alpha/Wikipedia trackers (no reform).", lsd:"Prohibited dependence-producing substance under 1971 Act (1971 UN Convention party); no access pathway.", ket:"Registered prescription medicine (Schedule 3) used in anaesthesia under Medicines & Related Substances Control Act 13 of 2003; recreational use illegal.", coc:"Illegal & enforced; Namibia is a cocaine transit hub (Walvis Bay) with active seizures/arrests. Note: death penalty constitutionally abolished 1990, so no capital sentences for trafficking." } },
  NP: { n:"Nepal", def:'ill', st:{ psi:'tol', ket:'med' }, nt:{ _:"Nepal bans nearly all listed substances under the Narcotic Drugs (Control) Act 2033 (1976), which explicitly lists cannabis, LSD, MDMA, cocaine and coca leaf; CBD is not distinguished from cannabis and is illegal. Enforcement is real (max penalty life imprisonment; NO death penalty, so no 'cap'). Two exceptions: ketamine is a registered hospital medicine ('med'), and psilocybin mushrooms are genuinely uncontrolled/unscheduled and openly available in an unregulated gray area ('legal', medium confidence). DMT, mescaline and ibogaine are conservatively classed illegal (DMT named; ayahuasca/cacti/iboga in untested gray zones). Cannabis remains illegal despite strong religious/cultural tolerance for sadhus and pending (not-yet-passed) reform bills as of 2026.", can:"Illegal & enforced under Narcotic Drugs (Control) Act 2033 (1976). Religious/cultural use by sadhus (esp. Shivaratri at Pashupatinath) historically tolerated but has no legal exemption; police have arrested public smokers since ~2018. Legalisation/medical-cultivation bills pending in 2024-2026 but none passed.", cbd:"Not distinguished from cannabis; the 'extract or essence' of cannabis is explicitly illegal, so CBD/hemp are treated as illegal narcotics. Reform discussions in 2026 noted the law lacks THC/CBD distinctions.", psi:"Psilocybin/magic mushrooms are NOT named in the Narcotic Drugs Act and are uncontrolled. Several Psilocybe species grow wild (the cubensis 'Kathmandu' strain is named for the capital); openly sold informally and used at retreat centres. Psychedelic Alpha: 'uncontrolled... not actively policed.' A legal gray area rather than affirmative legalisation.", lsd:"Explicitly listed as a narcotic; illegal and enforced. Possession ~2 months jail + small fine; trafficking/production up to ~10 years.", mdma:"Explicitly listed (ecstasy); illegal and enforced. Possession ~2 months + fine; trafficking up to ~10 years.", dmt:"DMT is controlled and treated like LSD (illegal/enforced). Ayahuasca as a plant brew sits in an untested gray area with no traditional use; conservatively treated as illegal.", mes:"Mescaline falls under the Act's broad psychotropic provisions; cacti (San Pedro) themselves unregulated but the alkaloid is controlled. No evidence of medical access or tolerance. Conservatively illegal.", ket:"Registered medicine — used in Nepali hospitals for anaesthesia and treatment-resistant depression under medical supervision; non-medical/recreational use illegal.", ibo:"No specific scheduling or medical/research framework found; falls under broad narcotics/psychotropic prohibition. Conservatively illegal.", coc:"Cocaine explicitly listed as a narcotic; illegal and enforced. Trafficking >100g can reach 10 years-to-life.", coca:"Coca leaf explicitly covered ('plants and leaves of coca'); illegal, with no Andean-style traditional/indigenous exemption in Nepal. Consumption up to 1 yr jail; cultivation 1-10 yrs." } },
  NL: { n:"Netherlands", def:'ill', st:{ can:'tol', cbd:'legal', psi:'tol', ket:'med', ibo:'legal' }, nt:{ _:"Netherlands: cannabis illegal-but-tolerated (coffeeshops; 2025 regulated supply experiment); CBD legal as supplement; psilocybin truffles legally sold in smartshops (mushrooms banned 2008). LSD, MDMA, DMT/ayahuasca, mescaline, cocaine and coca leaf are List I hard drugs, illegal and enforced. Ketamine is a registered medicine (Medicines Act); ibogaine sits outside the Opium Act under the Medicines Act with recreational use not criminalized and clinics operating. MDMA-assisted PTSD therapy is recommended by a state commission/parliament but not yet approved (~2027).", can:"Illegal but de-facto tolerated (gedoogbeleid): sold in ~570 coffeeshops, 5g personal possession not prosecuted. Regulated supply-chain 'weed experiment' entered experimental phase April 2025 across 10 municipalities.", cbd:"Not a controlled substance; legal as food supplement/cosmetic if THC <0.05% (one of the world's lowest thresholds). Domestic CBD extraction not permitted, so products are imported.", psi:"Fresh/dried mushrooms banned 2008, but psilocybin truffles (sclerotia) remain legal and openly sold in smartshops; NL is the only EU country with a regulated retail psilocybin market.", mdma:"List I hard drug, illegal and enforced. State Commission (2024) and a parliamentary committee (May 2025) recommend fast-tracking MDMA-assisted therapy for PTSD, but it is not yet approved; legalization not expected before ~2027.", dmt:"DMT is List I. Dutch Supreme Court (2018/2019) ruled ayahuasca illegal even for Santo Daime religious use, overriding the prior 2001-2018 exemption.", mes:"Mescaline is a List I hard drug. Live San Pedro/peyote cacti are a grey area, but the alkaloid is illegal.", ket:"Registered medicine under the Medicines Act (Geneesmiddelenwet), not the Opium Act; esketamine (Spravato) approved for treatment-resistant depression since 2019. Recreational use illegal.", ibo:"Governed by the Medicines Act, not the Opium Act; not a registered medicine but recreational use is not illegal nationally and treatment clinics operate (legal grey area).", coca:"Coca leaf is controlled alongside cocaine under List I; no traditional-use exemption exists in the Netherlands." } },
  NC: { n:"New Caledonia", def:'ill', st:{ cbd:'med', ket:'med' }, nt:{ _:"New Caledonia is a French sui generis collectivity where criminal law and narcotics scheduling remain State competences, so France's Code de la santé publique narcotics list (arrêté 22 Feb 1990) and the French Penal Code apply. Cannabis, psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine, cocaine and coca leaf are all classified stupéfiants — illegal and enforced (small-quantity possession is a fineable criminal offence since 2020, not decriminalization). CBD <0.3% THC is legal (post-Kanavape). Ketamine is a controlled medicine (recreational use illegal). No capital punishment (abolished 1981). NC-specific implementation (local enforcement nuances, any medical-cannabis access) is thinly documented, hence medium confidence.", can:"Stupéfiant under French Code de la santé publique (arrêté 22 Feb 1990), which applies in New Caledonia (criminal law & narcotics classification remain French State competences). Illegal recreational + medical; local Kanak authorities actively eradicate plantations. Small-quantity possession is a fineable criminal offence (forfait délictuel, since 2020), not decriminalized. France's permanent medical-cannabis regime (since Apr 2026) is a narrow ANSM-authorized pharmaceutical scheme with no documented patient access established in NC.", cbd:"CBD <0.3% THC legally sold in France post-EU Kanavape ruling; same framework applies in NC.", ket:"Classified as a narcotic in France but authorized as a medicine (general anaesthesia, emergency analgesia) under strict control; recreational use illegal.", ibo:"Iboga/ibogaine classified stupéfiant in France since 2007 (arrêté 12 Mar 2007); no medical authorization.", coc:"Refined cocaine is a stupéfiant, illegal and enforced. No death penalty (France abolished capital punishment 1981).", coca:"Coca leaf illegal (UN Single Convention Schedule I); no traditional/indigenous exemption in French law." } },
  NZ: { n:"New Zealand", def:'ill', st:{ can:'med', cbd:'med', ket:'med', ibo:'med' }, nt:{ _:"New Zealand operates under the Misuse of Drugs Act 1975 (three classes A/B/C). Most psychedelics (psilocybin, LSD, DMT, mescaline) and cocaine are Class A; MDMA is Class B1; ketamine and coca leaf are Class C. No death penalty (no 'cap'). Recent permissive shifts: medicinal cannabis (2018/2020), CBD pharmacist sales for low doses (Oct 2023), and a landmark June 2025 Medsafe approval allowing a psychiatrist to prescribe medicinal psilocybin for treatment-resistant depression. MDMA has clinical-trial/reg-22 clinical pathways but no approved prescriber yet. Ibogaine is uniquely uncontrolled — a non-approved prescription medicine since 2009, supporting legal clinics. Ketamine is a registered anaesthetic. The 2019 amendment created police discretion (health-based) for personal possession but did NOT decriminalise drug use, so recreational/personal use of Class A/B/C substances remains a criminal offence.", can:"Recreational illegal (2020 referendum rejected, 50.7% no). Medicinal Cannabis Scheme since 2018/2020; any doctor can prescribe. 2019 MoDA amendment directs police discretion toward a health-based approach for personal possession, but this is NOT formal decriminalisation — use/possession remains a criminal offence.", cbd:"Prescription medicine; since Oct 2023 low-dose CBD (<=150 mg/dose, <=4.5 g/pack) reclassified for sale by pharmacists without prescription. THC content must be minimal.", psi:"Class A controlled drug, but in June 2025 Medsafe granted the first approval for a psychiatrist to prescribe medicinal psilocybin for treatment-resistant depression under reg 22 of the Misuse of Drugs Regs 1977 (guidelines published 24 July 2025). Recreational use remains illegal/enforced.", lsd:"Class A controlled drug; illegal and enforced. Possession up to 6 months; supply/manufacture up to life imprisonment.", mdma:"Class B1 controlled drug. No approved prescriber yet, but clinical-trial pathway active (EMMACS trial, Auckland/Otago) and Medsafe reg-22 clinical pathway for psychedelics exists; MDMA expected to follow psilocybin. Recreational use illegal.", dmt:"Class A controlled drug; illegal and enforced. No religious/ayahuasca exemption.", mes:"Class A controlled drug. San Pedro/peyote cacti may be grown for ornamental purposes only; extraction/possession of mescaline is an enforced offence.", ket:"Class C controlled drug. Medsafe-approved anaesthetic; prescribable (incl. off-label for depression, though rare). Recreational use illegal.", ibo:"Not a controlled/scheduled substance. Gazetted as a non-approved prescription medicine since 2009; doctors may prescribe at discretion, enabling legal ibogaine-assisted therapy clinics.", coc:"Class A controlled drug; illegal and enforced. Possession up to 1 year; importing/supply up to life imprisonment.", coca:"Coca leaf (Erythroxylon coca) is a Class C controlled drug and listed prohibited plant; illegal but lower penalty tier than refined cocaine. No traditional-use exemption." } },
  NI: { n:"Nicaragua", def:'ill', st:{ ket:'med' }, nt:{ _:"Nicaragua is a strict-prohibition jurisdiction. Cannabis (incl. CBD), psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine, cocaine and coca leaf are all illegal and enforced under the Penal Code (Law 641) and organized-crime Law 735, which define psychotropics broadly as any natural/synthetic CNS-active substance. Small-quantity possession draws fines/community service; trafficking carries 15-30 years. Capital punishment is abolished (30-yr max), so no 'cap'. Ketamine is treated as a registered medicine ('med'); recreational use illegal. No medical-cannabis, decriminalization, or religious/indigenous psychedelic exemptions exist, though ayahuasca tourism is occasionally tolerated de-facto.", can:"Fully illegal - no medical or recreational program; possession <5g draws fines/community service, larger amounts prison.", dmt:"DMT illegal as a psychotropic; ayahuasca 'psychotourism' is sometimes unenforced de-facto but there is no formal religious/indigenous exemption.", ket:"Ketamine available as a registered human/veterinary anaesthetic (regional reporting notes it is easy to acquire in Nicaraguan pharmacies); non-medical use illegal.", coc:"Cocaine illegal and enforced; trafficking carries 15-30 yr sentences. Death penalty abolished (max sentence 30 yrs), so not capital.", coca:"No Andean traditional-use exemption; coca leaf treated as a prohibited narcotic." } },
  NE: { n:"Niger", def:'ill', st:{ ket:'med' }, nt:{ _:"Niger (NE) is a conservative francophone Sahel state with a blanket prohibitionist drug regime implementing the UN 1961/1971/1988 Conventions, enforced by OCRTIS with large and rising seizures. Cannabis and CBD are fully illegal (no medical program); psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine, cocaine and coca leaf are all illegal with no religious/indigenous/medical exemptions or reform activity. Ketamine is treated as a registered medicine (med), recreational use illegal. Crucially, Niger does NOT impose the death penalty for drug offences (de facto execution moratorium since 1976) — so no 'cap'; penalties are imprisonment and fines. Cannabis/CBD/cocaine statuses are well-sourced; psychedelics and ketamine rest on the UN-convention default rather than Niger-specific per-substance documentation, hence medium confidence.", can:"Fully illegal, recreational and medical; possession, use and sale are criminal offences enforced by OCRTIS (Office Central de Répression du Trafic Illicite de Stupéfiants). Large, rising seizures (6.3 t + 4.7M psychotropic tablets in 2019; multi-ton cannabis through 2022).", cbd:"No legal distinction from cannabis; no legal CBD/hemp market — treated as illegal.", mdma:"Schedule I psychotropic under UN 1971 Convention implemented by Niger; no medical/research access. NOTE: Niger does NOT have the death penalty for drug trafficking (de facto execution moratorium since 1976; not on the capital-drug-offence list) — penalties are imprisonment and fines, so 'cap' was not applied to any substance.", ket:"Not specifically documented for Niger, but ketamine is a registered medical/anaesthetic agent under standard international scheduling; recreational use illegal. Classified 'med' per global norm (lower certainty).", ibo:"Not internationally scheduled, but Niger has no medical-access pathway or exemption; falls under the general prohibitionist framework — no real-world access for patients/researchers.", coc:"Refined cocaine illegal; Niger is a transit corridor in the Sahel with sharply rising cocaine seizures (UNODC 2024).", coca:"No coca tradition in West Africa; controlled as a Schedule I narcotic under the 1961 Convention with no exemption." } },
  NG: { n:"Nigeria", def:'ill', st:{ ket:'med', coc:'cap' }, nt:{ _:"Nigeria operates a strict prohibition regime under the NDLEA Act. All listed substances except ketamine are illegal and enforced. Cannabis (and undistinguished CBD) carry 15-25 yrs for possession and up to life for cultivation/dealing, with active enforcement (220 ha of farms destroyed, 17,670 arrests in 2024). LSD, MDMA, DMT, psilocybin, mescaline and ibogaine are controlled as hard/psychotropic 'similar drugs' (possession 15-25 yrs). Cocaine is named explicitly in NDLEA Act s.11 with mandatory LIFE imprisonment for trafficking/production (marked 'cap' as a long mandatory sentence). A 2024 proposal to add the death penalty for trafficking was removed by a bicameral committee, and the NDLEA Amendment Bill 2025 was declined presidential assent in June 2025, so capital punishment is NOT current law. Ketamine is a NAFDAC Nationally Controlled Drug available for medical/scientific use under permit ('med'). Medical-cannabis and decriminalization bills are under discussion for 2026 but none have been enacted. Coca leaf has no traditional exemption and is illegal.", can:"Illegal & heavily enforced under the NDLEA Act; possession/use 15-25 yrs, cultivation/dealing up to life. NDLEA destroyed 220 hectares of cannabis farms and made 17,670 drug arrests in 2024. Medical-cannabis/decriminalization bills proposed in 2024-2026 but NOT yet enacted.", cbd:"No legal distinction from cannabis; any part of the genus Cannabis is prohibited, so CBD is illegal/highly uncertain. No therapeutic pathway.", lsd:"Named explicitly in NDLEA Act s.11 as a hard drug; trafficking/production = life imprisonment, possession/use 15-25 yrs.", mdma:"Prosecuted as a psychotropic 'similar drug' under NDLEA Act ss.11/21; possession 15-25 yrs.", ket:"Listed as a Nationally Controlled Drug by NAFDAC; available for medical/scientific use under import permit. Non-medical use illegal.", coc:"Cocaine named explicitly in NDLEA Act s.11: trafficking/importation/production carries life imprisonment (a long mandatory sentence). A 2024 Senate amendment proposed the DEATH PENALTY for trafficking but a bicameral committee removed it, retaining life; the NDLEA Amendment Bill 2025 was declined assent by President Tinubu in June 2025. Death penalty therefore not current law, but trafficking = mandatory life.", coca:"No traditional/indigenous use; coca leaf falls under prohibited narcotics, illegal." } },
  KP: { n:"North Korea", def:'cap', st:{ cbd:'ill', ket:'ill', coca:'ill' }, nt:{ _:"North Korea (DPRK) runs one of the world's strictest drug-prohibition regimes. The 2005 Narcotics Control Law classifies cannabis, THC, and psychoactive substances as narcotics, and the 2021 anti-drug law stipulates a maximum penalty of death for illegally gathering, manufacturing, or smuggling drugs — Harm Reduction International rates the DPRK a 'high application' death-penalty-for-drugs state. There are no legal medical, research, religious, or pilot pathways for any of these substances, so patient/researcher access is effectively nil. Cannabis and the classic illicit drugs (psilocybin, LSD, MDMA, DMT, mescaline, ibogaine, cocaine) are marked 'cap' because supply offences can carry capital punishment. CBD (no therapeutic carve-out beyond legal low-THC industrial hemp), ketamine (no verifiable medical-access framework), and raw coca leaf (no traditional use) are marked 'ill' conservatively. Confidence is medium: the prohibition framework and death-penalty law are well-documented, but DPRK opacity means substance-specific scheduling for the rarer psychedelics, ketamine, ibogaine, and coca is inferred from the blanket law rather than from substance-specific primary sources.", can:"Cannabis (incl. THC, hemp resin) is a listed narcotic under the 2005 Narcotics Control Law; recreational use illegal. Persistent media myth of 'legal weed' is false. Trafficking/manufacturing falls under 2021 anti-drug law death-penalty provisions. Low-THC industrial hemp is separately legal for consumer goods.", cbd:"No legal medical/therapeutic CBD framework; the cannabis plant is a controlled narcotic. Only low-THC industrial hemp is permitted, not CBD products for human therapeutic use — treated as illegal (conservative).", psi:"Prohibited narcotic; no research/medical carve-out. Supply offences fall under death-penalty provisions.", lsd:"Prohibited narcotic; no medical/research access. Supply offences fall under death-penalty provisions.", mdma:"Treated as a prohibited narcotic; manufacturing/smuggling can carry the death penalty under the 2021 anti-drug law.", dmt:"DMT/ayahuasca prohibited; no religious or research exemption.", mes:"Mescaline (peyote/San Pedro) prohibited; no indigenous/religious exemption.", ket:"No verifiable legal medical-access or scheduling framework for patients/researchers; opaque state-only pharma system. Recreational/possession prohibited. Classified illegal conservatively rather than 'med' absent any evidence of real access.", ibo:"Ibogaine prohibited; no medical/addiction-treatment access framework.", coc:"Refined cocaine is a prohibited narcotic; trafficking/manufacturing can carry capital punishment under the 2021 law.", coca:"No traditional/indigenous coca use; raw coca leaf falls under blanket narcotics prohibition — illegal." } },
  NO: { n:"Norway", def:'ill', st:{ cbd:'med', ket:'med' }, nt:{ _:"Norway remains a prohibition-with-diversion country in 2026. Cannabis, classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline), ibogaine, cocaine and coca leaf are all illegal and enforced narcotics (psychedelics listed since 1966). The June 2025 Prop. 112 L reform did NOT enact general decriminalization: small-quantity personal possession/use stays a criminal offence (fine or up to ~6 months), but drug-dependent individuals are statutorily exempt from punishment (codifying Supreme Court practice) and diverted to municipal counseling. Ketamine is a registered medicine with publicly reimbursed off-label use for treatment-resistant depression plus private clinics (med). CBD is permitted only as 0.00%-THC isolate products; any THC or cannabis-extract CBD is treated as a narcotic.", can:"Illegal recreationally and enforced; very limited medical cannabis by special exemption. June 2025 Prop. 112 L did NOT decriminalize: small-amount possession/use remains a criminal offence (fine or up to ~6 months), though drug-dependent persons are exempted from punishment and diverted to municipal counseling.", cbd:"Permitted only as CBD isolate with 0.00% THC (oils/cosmetics, some vapes); cannabis-extract or full-spectrum CBD is treated as a narcotic and any trace THC is illegal. Private import banned. Stricter than EU.", psi:"Psilocybin/psilocin on narcotics list since 1966; illegal and enforced. Research-only access.", mdma:"Illegal and enforced; prison for possession. MDMA-assisted therapy studied in clinical trials (MAPS Phase II at Sykehuset Ostfold; Univ. of Oslo) but no approved/medical access.", dmt:"DMT and ayahuasca prohibited as narcotics; no religious/indigenous exemption.", mes:"Mescaline on narcotics list since 1966; illegal and enforced.", ket:"Registered medicine; off-label IV racemic ketamine authorized in specialist services and publicly reimbursed for treatment-resistant depression (as of Aug 2025); private ketamine clinics operate. Recreational use illegal.", ibo:"Ibogaine prohibited as a narcotic; illegal.", coca:"No traditional/legal use; coca leaf treated as a narcotic (cocaine source), illegal." } },
  OM: { n:"Oman", def:'cap', st:{ cbd:'ill', ket:'med', ibo:'ill' }, nt:{ _:"Oman is one of the strictest prohibitionist jurisdictions. The Law on Combating Narcotics & Psychotropic Substances criminalises all listed substances; Article 43 provides the death penalty or life imprisonment (plus fines over RO 25,000) for producing, importing, exporting, dealing or links to international trafficking gangs — confirmed by state media (Oman Observer) and reflected in Oman's list of capital offences. There is no medical-cannabis or CBD framework, and no religious/indigenous/research exemptions for psychedelics. Ketamine is the lone exception: a registered anaesthetic medicine, so medical/research use is lawful while recreational use is not. Possession (as opposed to trafficking) generally draws long prison terms, fines and deportation for foreigners rather than execution, but the trafficking statute legitimately puts most of these substances in the 'cap' tier." } },
  PK: { n:"Pakistan", def:'ill', st:{ ket:'med', coc:'cap' }, nt:{ _:"Pakistan prohibits recreational cannabis and all classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline, ibogaine) under the Control of Narcotic Substances Act 1997, which schedules them in line with the UN conventions — illegal and enforced, though enforcement of personal use is uneven. Two notable developments: (1) the Cannabis Control and Regulatory Authority Act 2024 created a federal framework licensing cultivation/extraction/sale of cannabis derivatives (incl. CBD) for medical and industrial use only — recreational cannabis stays illegal; (2) the CNS (Amendment) Act 2023 (effective 25 Jul 2023) abolished the death penalty for all drug offences, replacing it with a maximum of life imprisonment, though severe long sentences for trafficking remain (coded 'cap' for refined cocaine). Ketamine is a registered medicine (med); coca leaf has no traditional use and is illegal.", can:"Recreational cannabis illegal and enforced under Control of Narcotic Substances Act 1997. A separate medical/industrial pathway now exists via the Cannabis Control and Regulatory Authority Act 2024 (CCRA), but recreational/general use remains prohibited.", cbd:"No free consumer CBD market; cannabis derivatives (incl. CBD) are legally provisioned only for medical/industrial use under the CCRA Act 2024 licensing framework. Coded med to reflect this regulated medical/industrial pathway.", psi:"Scheduled under the CNS Act (aligned with the UN 1971 Convention); illegal and enforced, no religious/research exemption documented.", lsd:"Scheduled psychotropic under the CNS Act; illegal and enforced.", mdma:"Scheduled psychotropic under the CNS Act; illegal and enforced.", dmt:"DMT/ayahuasca scheduled under the CNS Act; illegal and enforced, no religious-use carve-out.", mes:"Mescaline (peyote/San Pedro) scheduled under the CNS Act; illegal and enforced.", ket:"Registered medicine regulated under the DRAP Act 2012 and CNS Act 1997; medical/clinical use permitted, recreational use illegal (and reportedly rising).", coc:"Refined cocaine is a controlled narcotic; trafficking carries up to life imprisonment. Note: Pakistan abolished the death penalty for all drug offences via the CNS (Amendment) Act 2023 (in force 25 Jul 2023), replacing capital punishment with a maximum of life imprisonment — but long/severe sentences for trafficking remain, hence 'cap'.", coca:"Coca leaf has no traditional/indigenous use in Pakistan and is treated as a prohibited narcotic — illegal and enforced." } },
  PS: { n:"Palestine", def:'ill', st:{ ket:'med' }, nt:{ _:"Palestine (PS) prohibits all of these substances under the 2015 Palestinian Anti-Narcotics Act, which adopts UN-convention scheduling and applies stringent penalties (up to hard labor for life) against dealers/traffickers. No cannabis legalization (recreational or medical) and no CBD carve-out; psilocybin, LSD, MDMA, DMT/ayahuasca and mescaline are illegal with no permissive or pilot framework. Ketamine is classified 'med' because the law permits medical/scientific import under strict control (recreational use illegal). Coca leaf has no traditional use and refined cocaine is illegal. Jurisdiction is bifurcated: the West Bank (PA) has had a de facto execution moratorium since 2005, but Gaza (Hamas) actively imposes and carries out the death penalty for drug dealing/smuggling, so trafficking carries capital-punishment risk there. Confidence is medium due to sparse substance-specific data and the split legal regimes.", can:"Illegal for all uses (recreational and medical); no CBD carve-out. UNODC confirms full prohibition; strong religious/cultural opposition. In Gaza (Hamas), drug offences incl. hashish can reach capital punishment.", cbd:"No legal distinction from cannabis; prohibited along with all cannabis products.", ket:"Registered medicine; 2015 Anti-Narcotics Act permits import/export of drugs for medical/scientific use under strict restriction. Recreational use illegal.", ibo:"No specific provision; prohibited by default under general narcotics law.", coc:"Illegal and enforced; trafficking can carry hard labor for life (West Bank) and the death penalty in Gaza.", coca:"No traditional/indigenous use; falls under general narcotics prohibition." } },
  PA: { n:"Panama", def:'ill', st:{ cbd:'med', ket:'med' }, nt:{ _:"Panama: medical cannabis legal since 2021 (Law 242), recreational cannabis illegal. CBD <1% THC is unregulated/legal. All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) and cocaine are controlled, illegal and enforced; no religious/indigenous exemptions documented. Coca leaf has no traditional-use exemption → illegal. Ketamine is a controlled prescription medicine (med). Personal possession is NOT decriminalized — it remains a criminal offence, though small amounts may draw lighter penalties or therapeutic measures (sentencing mitigation, not decrim). No 'cap' anywhere: the death penalty is constitutionally prohibited (Art. 30 of the 1972 Constitution).", can:"Recreational illegal & enforced; medical cannabis legal since Law 242 (2021) — first Central American country to do so. Resolution 200 of 2025 added cannabis to the official controlled-substances list for medical/scientific use.", cbd:"CBD products with THC below 1% are not controlled substances and may be sold (incl. in food products).", dmt:"No documented religious/indigenous ayahuasca exemption in Panama; DMT is a controlled substance, illegal and enforced.", ket:"Controlled medicine available by strict prescription; recreational use illegal.", coc:"Strictly prohibited; trafficking 10-15 yrs (Art. 313). No death penalty — capital punishment is constitutionally banned (Art. 30).", coca:"No traditional coca-chewing exemption in Panama; treated as a prohibited controlled substance." } },
  PG: { n:"Papua New Guinea", def:'ill', st:{ ket:'med' }, nt:{ _:"Papua New Guinea prohibits all the listed recreational/psychedelic substances. Cannabis and CBD are illegal for both recreational and medical use (Dangerous Drugs Act), though cannabis is widely cultivated and consumed. The Controlled Substance Act 2021 modernized the framework, explicitly criminalizing cocaine, methamphetamine and 'all manner of drugs' and precursors, with penalties up to life imprisonment or a K2 million fine. Crucially, the death penalty does NOT apply to drug offences: capital punishment was abolished entirely in January 2022 and was never used for drugs, and a proposal to introduce it for drug crimes was rejected - so penalties are severe ('ill') but not 'cap'. Classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline, ibogaine) fall under the broad prohibition with no therapeutic/research access program (unlike Australia/NZ). Ketamine is marked 'med' by inference (registered anaesthetic medicine; recreational use prohibited) as no PNG-specific source was found. Coca leaf has no traditional use and is prohibited. Confidence is medium overall: cannabis/CBD/cocaine and the no-death-penalty finding are well sourced, but the rarer psychedelics (DMT, mescaline, ibogaine) and ketamine lack PNG-specific scheduling sources and are inferred from the catch-all 2021 Act and international-convention membership.", can:"Illegal for recreational and medical use under the Dangerous Drugs Act; widely grown/consumed ('spak brus') but enforced - possession up to 2 yrs, cultivation up to 15 yrs, supply up to ~20-25 yrs. No medical program; no pending reform (as of 2026).", cbd:"No separate legal status; treated as a cannabis derivative and therefore prohibited alongside cannabis.", mdma:"Prohibited as a psychotropic; PNG is a party to the 1971 Convention and the Controlled Substance Act 2021 covers 'all manner of drugs'. No therapeutic/research access (unlike Australia/NZ).", dmt:"Prohibited under the broad narcotic/psychotropic framework. Not individually scheduled by name in available sources and no enforcement record - lower confidence.", ket:"No PNG-specific source found. Inferred 'med': ketamine is a registered essential anaesthetic medicine almost everywhere and PNG has a medicinal-product registration framework; recreational use falls under controlled-substance prohibition.", ibo:"No PNG-specific data; not individually scheduled by name. Classified illegal under the catch-all controlled-substance framework rather than any permissive carve-out - low confidence.", coc:"Explicitly criminalized by the Controlled Substance Act 2021 (previously no specific cocaine law). PNG is a Pacific transit hub; police actively pursue cocaine trafficking. Trafficking/peddling can carry up to life imprisonment or a K2m fine - severe but NOT capital (death penalty abolished 2022).", coca:"No Andean/traditional coca use in PNG; not legal. Falls under general narcotic prohibition." } },
  PY: { n:"Paraguay", def:'ill', st:{ can:'decrim', cbd:'med', ket:'med' }, nt:{ _:"Paraguay: medical cannabis/CBD legal since 2017 (Law 6007) -> med. Recreational cannabis illegal but personal possession <=10g exempt from punishment (Art. 30, Law 1340/88) -> decrim. All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) and cocaine + coca leaf are illegal and enforced under blanket narcotics Law 1340/88, with no religious/indigenous/medical exemptions -> ill. Ketamine = registered medicine -> med. No death penalty for drug offences (max ~15 yrs), so 'cap' not applicable.", can:"Recreational cannabis illegal, but Law 1340/88 Art. 30 exempts possession of up to 10g for exclusive personal use from punishment (de-facto personal-use decriminalization). No legal purchase route.", cbd:"Medical cannabis/CBD legal since 2017 (Law 6007); national medical program with licensed cultivation/production and a 0.5% THC cap for medicinal products. First commercial medical cannabis licenses being rolled out.", psi:"Schedule-I-type substance under blanket narcotics Law 1340/88; illegal and enforced, heavy penalties for supply (up to ~15-20 yrs). No medical/religious exemption.", lsd:"Prohibited under Law 1340/88; illegal and enforced. No exemption framework.", mdma:"Prohibited under Law 1340/88; illegal and enforced. No approved therapeutic access.", dmt:"DMT/ayahuasca subsumed under general narcotics law (Law 1340/88); no Santo Daime/UDV or indigenous exemption recognized. Illegal and enforced.", mes:"Mescaline (peyote/San Pedro) prohibited under Law 1340/88; no traditional/indigenous carve-out. Illegal.", ket:"Ketamine treated as a registered medicine (UN Schedule III psychotropic); medical/veterinary use lawful, recreational use illegal. No Paraguay-specific source confirming details.", ibo:"Ibogaine has no specific legal framework; falls under general controlled-substance prohibition. No approved access.", coc:"Refined cocaine illegal and enforced under Law 1340/88; small personal-use amounts may escape punishment but supply/trafficking heavily penalized (up to ~15 yrs). Paraguay is a major cocaine trans-shipment route.", coca:"Coca leaf is illegal in Paraguay (unlike Bolivia/Peru) with no traditional-use exemption." } },
  PE: { n:"Peru", def:'decrim', st:{ cbd:'med', psi:'ill', lsd:'ill', dmt:'legal', mes:'legal', ket:'med', coca:'legal' }, nt:{ _:"Peru combines a hard-line trafficking regime with broad personal-use exemptions (Penal Code Art. 299) and strong protection for indigenous plant medicines. Coca leaf and San Pedro/mescaline are legal as cultural/traditional medicine; ayahuasca/DMT is protected for traditional and ritual use (National Cultural Heritage, 2008). Medical cannabis and CBD are legal since 2017 (Law 30681), and ketamine is a DIGEMID-controlled medicine. Cannabis, psilocybin, MDMA and even cocaine are illegal on paper but small single-substance personal quantities are not punished. LSD is banned with no defined personal threshold. Ibogaine is unscheduled (legal gray area). Refined cocaine remains illegal with severe penalties for supply, but no death penalty exists in Peru.", can:"Recreational illegal but personal possession up to 8g decriminalized under Penal Code Art. 299. Medical cannabis legal since Law 30681 (2017), regulated by DIGEMID; first dispensary opened 2021; framework updated by Supreme Decree 004-2023-SA. Cultivation/sale 8-15 yrs.", cbd:"Legal/available within the medical cannabis framework (Law 30681, 2017; Supreme Decree 004-2023-SA), prescribed and dispensed via DIGEMID-registered channels.", psi:"Schedule I-B controlled substance under Decree-Law 22095 (1978); illegal to cultivate/sell, but possession for immediate personal use is non-punishable under the Penal Code.", lsd:"Controlled/banned; trafficking and supply carry long prison sentences. Personal-use possession is in principle exempt but Art. 299 sets no specific LSD threshold; coded illegal conservatively.", mdma:"Illegal, but personal possession up to 250mg of ecstasy (MDMA/MDA/methamphetamine etc.) is exempt from punishment under Penal Code Art. 299 (single-substance rule).", dmt:"Ayahuasca's traditional indigenous use recognized as National Cultural Heritage (2008); Peru entered a reservation for ayahuasca under the 1971 Convention. Traditional/ritual use permitted; commercial/decontextualized use is not protected.", mes:"San Pedro (Echinopsis pachanoi) cactus containing mescaline is legal; Peru entered a treaty reservation for San Pedro and it is treated as part of traditional medicine. Purified mescaline is controlled.", ket:"Controlled medicine under Supreme Decree 023-2001-SA (narcotics/psychotropics health surveillance); requires special prescription and DIGEMID tracking (FOPE). Anesthetic/medical use legal; recreational use illegal.", ibo:"No specific national regulation; legal gray area (not scheduled). Treatment clinics operate without formal oversight; coded decrim to reflect de-facto permitted unregulated status.", coc:"Refined cocaine illegal; production/trafficking heavily penalized. However personal possession up to 2g cocaine HCl (or 5g coca paste) is non-punishable under Penal Code Art. 299 (single-substance only).", coca:"Raw coca leaf is legal: chewing and traditional use are lawful and culturally protected; cultivation/commerce run through the state monopoly ENACO. Considered part of traditional medicine." } },
  PH: { n:"Philippines", def:'ill', st:{ cbd:'med', ket:'med', coc:'cap' }, nt:{ _:"Philippines (RA 9165, Comprehensive Dangerous Drugs Act 2002) maintains strict prohibition. Cannabis, psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine, cocaine and coca leaf are all illegal Schedule I dangerous drugs with no legal access; enforcement is severe (ongoing 'drug war' killings in 2024-2025). The death penalty was abolished (RA 9346, 2006) and is NOT currently imposable, but large-scale trafficking carries mandatory life imprisonment — hence 'cap' for refined cocaine. CBD has a genuine but very narrow medical route (FDA Compassionate Special Permit / Epidiolex for severe epilepsy since ~2014) → 'med'. Ketamine is a controlled medicine → 'med'. A medical-cannabis bill is advancing but not yet law.", can:"Illegal Schedule I under RA 9165; recreational/general cannabis prohibited and enforced. A medical-cannabis bill advanced in the House (DOH set conditions Feb 2026) but is NOT yet law.", cbd:"No general legal CBD market, but a real medical access route exists: the FDA Compassionate Special Permit has allowed importation of CBD/Epidiolex since ~2014 for severe (mainly pediatric) epilepsy, by prescription. Very limited and costly.", psi:"Schedule I dangerous drug under RA 9165; no medical or research access. Enforced.", lsd:"Specifically listed as a dangerous drug under RA 9165; illegal and enforced.", mdma:"Specifically listed ('ecstasy') as a dangerous drug under RA 9165; illegal and enforced.", dmt:"No DMT/ayahuasca-specific exemption; covered by the broad RA 9165 prohibition and 1971 Convention obligations. No legal/religious access route.", mes:"Not separately named but covered by the broad prohibition framework; no access route.", ket:"Registered/controlled anaesthetic medicine, tightly supervised by the Dangerous Drugs Board; recreational use illegal.", ibo:"Not separately scheduled/named, but no legal access; covered by the general prohibition regime.", coc:"Refined cocaine is an illegal dangerous drug; large-quantity trafficking carries mandatory life imprisonment. Note: the death penalty was abolished (RA 9346, 2006) and is not currently in force, but 'drug war' enforcement remains severe with ongoing drug-related killings (2024-2025).", coca:"Coca leaf prohibited; no traditional/indigenous use exemption in the Philippines." } },
  PL: { n:"Poland", def:'ill', st:{ can:'med', cbd:'legal', ket:'med' }, nt:{ _:"Poland has one of Europe's stricter drug regimes. All classical psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) are Group I-P psychotropics: illegal and enforced, though multinational Phase III research trials are running. Cannabis is illegal for recreational use (govt reaffirmed no easing in Oct 2025) but has a sizable legal medical programme (>105k patients) since 2017; CBD <0.3% THC is legal as a novel food. Ketamine is a Group II-P registered medicine (esketamine reimbursed via NFZ programme B.147 for treatment-resistant depression); recreational use illegal. Cocaine and coca leaf are controlled narcotics, illegal. Ibogaine is not separately scheduled but has no access pathway - classified conservatively as illegal (low confidence). Article 62a allows discretionary discontinuation of low-quantity personal-use cases but this is prosecutorial discretion, not formal decriminalization. No death penalty in Poland.", can:"Recreational cannabis illegal and enforced (up to 3 yrs possession, 1-10 yrs for larger amounts); govt reaffirmed Oct 2025 it will not ease laws. NOTE: separate medical cannabis programme legal since 2017, >105,000 patients by end-2025 (in-person exam required for Rx since Nov 2024) - but recreational/general status is illegal.", cbd:"Legal for adults at THC <0.3%, sold in shops/online; regulated as 'novel food', no medicinal health claims allowed.", psi:"Psilocybin/psilocin are Group I-P controlled psychotropics; criminal offence. Phase III research trials underway.", lsd:"Group I-P, strictly prohibited and enforced; research-only under national framework.", mdma:"Group I-P, illegal; possession penalties up to ~10 yrs.", dmt:"DMT (and ayahuasca brew ingredients) treated as Group I-P illegal psychotropics.", mes:"Mescaline is a Group I-P controlled psychotropic; San Pedro/peyote use prohibited.", ket:"Group II-P: registered medical anaesthetic; esketamine reimbursed via NFZ drug programme B.147 for treatment-resistant depression. Recreational use illegal.", ibo:"Not individually named in Polish drug law and not on UN list, but no legal/medical access pathway exists; classified conservatively as illegal/de-facto unavailable (low confidence on exact control status).", coc:"Refined cocaine is a controlled narcotic, illegal and enforced (Art. 62; up to 3 yrs, 10 yrs for significant quantity).", coca:"Raw coca leaf listed among narcotic drugs under the 2005 Act; illegal." } },
  PT: { n:"Portugal", def:'decrim', st:{ can:'med', cbd:'med', ket:'med' }, nt:{ _:"Portugal decriminalized personal possession of ALL drugs in 2001 (Law 30/2000): possession up to a ~10-day supply is an administrative offence handled by Dissuasion Commissions, not a crime. Sale/trafficking of every substance remains criminal (1-5 yr prison; no death penalty — capital punishment abolished). Exceptions to the blanket 'decrim' baseline: medical cannabis legal since 2018 (prescription, pharmacy); hemp CBD <=0.2% THC sold without prescription; ketamine is a registered controlled medicine. No regulated recreational sales or licensed psychedelic 'use centres' exist despite some unreliable web claims of 2026 legalization.", can:"Personal possession decriminalized since 2001 (admin offence, ~10-day supply / 25g flower); recreational sale & cultivation remain criminal. Medical cannabis legal since 2018 (pharmacy, prescription).", cbd:"Hemp-derived CBD <=0.2% THC sold without prescription (retail/online); THC-containing CBD only via medical-cannabis prescription. Food/supplement CBD restricted under EU Novel Food rules.", psi:"Decriminalized personal possession (<=10-day supply) under Law 30/2000; sale/cultivation illegal. No regulated 'safe-use centres' despite some online claims.", lsd:"Decriminalized personal possession; trafficking criminal.", mdma:"Decriminalized personal possession; trafficking criminal.", dmt:"DMT controlled (DL 15/93); personal possession decriminalized. Ayahuasca not explicitly regulated; religious use argued under freedom-of-religion but UDV denied formal recognition.", mes:"Mescaline controlled; personal possession decriminalized, sale illegal.", ket:"Controlled medicine; legitimate medical/clinical use. Recreational possession decriminalized (admin), supply criminal.", ibo:"Not specifically scheduled or medically approved; personal possession falls under blanket decriminalization (admin offence). No clinical/legal pathway.", coc:"Refined cocaine: personal possession decriminalized (<=2g / 10-day supply); trafficking criminal (1-5 yrs).", coca:"Raw coca leaf not part of local culture; would be treated like any controlled substance under blanket decriminalization for personal possession, no specific tolerance regime." } },
  PR: { n:"Puerto Rico", def:'ill', st:{ can:'med', cbd:'legal', ket:'med' }, nt:{ _:"Puerto Rico is a US territory governed by the federal Controlled Substances Act and a mirroring territorial Controlled Substances Act. Cannabis is medical-only (Act 42-2017, since 2015) with no recreational legalization; hemp-derived CBD is legal. All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) and ibogaine are Schedule I and criminally enforced, with only narrow federal religious peyote/ayahuasca exemptions that do not provide general access in PR. Ketamine is a prescription medicine (med). Refined cocaine and raw coca leaf are both illegal. No death penalty for drug offences; standard US federal mandatory-minimum trafficking penalties apply but do not rise to 'cap' under the conservative rule.", can:"Medical cannabis legal since 2015, codified by Act 42-2017; 300+ licensed dispensaries; no recreational use (still illegal); smoking prohibited, no home cultivation.", cbd:"Hemp-derived CBD (<0.3% THC) legal under US 2018 Farm Bill; sold openly to general public and tourists.", dmt:"DMT Schedule I; ayahuasca illegal. PR follows US federal law — only narrow federal religious exemptions (UDV, certain Santo Daime churches) exist and none operate in PR.", mes:"Mescaline Schedule I; only the narrow federal Native American Church peyote religious exemption applies — no general or indigenous-tradition access in PR.", ket:"Registered medicine (anesthesia, depression treatment) by prescription; non-prescription possession is a felony.", ibo:"Schedule I under US/PR law; no approved medical use; possession is a criminal offence." } },
  QA: { n:"Qatar", def:'ill', st:{ can:'cap', lsd:'cap', mdma:'cap', ket:'med', coc:'cap' }, nt:{ _:"Qatar operates a comprehensive zero-tolerance narcotics regime under Law No. 9 of 1987 (NDDPS), amended by Law No. 16/2023 and Ministerial Decision No. 8/2026. All recreational drugs, psychedelics, cannabis (incl. CBD, no THC threshold), and cocaine are illegal and enforced; drug trafficking can legally carry the death penalty or life imprisonment (death sentences issued but not recently executed for drugs), so the most clearly trafficked/scheduled substances are marked 'cap'. Ketamine is a controlled hospital medicine available with prior MOPH authorization ('med'). No medical-cannabis, religious-ayahuasca, or psychedelic-research exemptions exist.", can:"Illegal under Law No. 9/1987 (NDDPS); no medical or recreational provision. Trafficking (explicitly including hashish) can carry the death penalty or life imprisonment; courts have handed down death sentences but no recent executions for drugs.", cbd:"No legal distinction between hemp and cannabis; MOPH recognizes no THC threshold. CBD imports prohibited and intercepted by Qatar Customs even with foreign prescriptions (Epidiolex not honored without MOPH authorization).", psi:"Falls under blanket prohibition of narcotics/psychotropics; no medical, religious, or research exemption.", lsd:"Banned psychotropic under Law No. 9/1987; trafficking falls under capital/long-mandatory-sentence provisions of Qatar's narcotics law.", mdma:"Ecstasy explicitly prohibited under NDDPS; trafficking can carry death penalty or life imprisonment.", dmt:"Prohibited under NDDPS; no religious/ayahuasca exemption.", mes:"Prohibited under NDDPS; no peyote/San Pedro exemption.", ket:"Controlled medicine available in hospitals with prior MOPH (Dept. of Pharmacology and Drugs Control) authorization, alongside morphine/fentanyl; recreational use illegal. Travelers need pre-approval to import.", coc:"Cocaine explicitly prohibited; trafficking can carry the death penalty or life imprisonment under Law No. 9/1987.", coca:"Coca leaf has no traditional/legal status; falls under blanket prohibition of Law No. 9/1987." } },
  RS: { n:"Republic of Serbia", def:'ill', st:{ cbd:'tol', ket:'med' }, nt:{ _:"Serbia maintains a uniformly prohibitionist drug regime under the Criminal Code (Art. 246/246a) and the Law on Psychoactive Controlled Substances (2010, amended 2018), which makes no distinction between substances. Possession of small quantities for personal use is punishable by up to 3 years' imprisonment (use itself is not criminalized, but possession is); larger quantities 3-10 years; production/sale 3-12 years (5-15 for organized groups). There is NO decriminalization (reaffirmed by President Vucic in 2024) and NO medical cannabis or psychedelic-therapy program. The death penalty is abolished, so 'cap' does not apply. Cannabis, psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine, cocaine, and coca leaf are all illegal and enforced (ill). Ketamine is classed 'med' as a registered medical anesthetic (recreational use illegal). CBD is the lone exception: low-THC hemp-derived CBD products are sold OTC in a tolerated/regulated gray area (legal), with industrial hemp permitted under authorization at THC <=0.3%. Confidence is high for the directly sourced substances; ketamine, mescaline, ibogaine, and coca leaf rest on the uniform controlled-substances framework rather than substance-specific citations, but the conservative calls (med/ill) are well-supported.", can:"Illegal for both recreational and medical use; no medical cannabis program. Criminal Code (Art. 246/246a) treats cannabis like any other drug. Possession of small amounts: up to 3 years; cultivation/sale up to 12 years. President Vucic (2024) explicitly ruled out decriminalization, vowing harsher penalties.", cbd:"Legal gray area but de-facto available: low-THC hemp-derived CBD products (<0.2-0.3% THC) sold OTC in shops in larger cities (oils, supplements, creams); industrial hemp permitted under authorization with THC <=0.3%. The only substance with real regulated/tolerated access.", dmt:"Illegal; prohibition explicitly extends to ayahuasca and changa. Up to 3 years for small amounts.", mes:"Illegal; no religious/traditional-use exemption under Serbian law.", ket:"No specific Serbian carve-out, but ketamine is a registered medical/anesthetic agent regionally; recreational use prohibited under the controlled-substances regime. Classed 'med' per standard practice.", ibo:"Illegal; controlled, no medical/clinical exception.", coca:"Coca leaf illegal; no traditional-use exemption (treated as a narcotic like refined cocaine)." } },
  CG: { n:"Republic of the Congo", def:'ill', st:{ ket:'med' }, nt:{ _:"Republic of the Congo (Congo-Brazzaville) prohibits cannabis (recreational and medical) and has no CBD framework. As a party to the 1961/1971/1988 UN drug conventions, it permits narcotics/psychotropics only for medical, scientific and educational use, so psilocybin, LSD, MDMA, DMT and mescaline are controlled/illegal with no decriminalization or religious exemption (no Congo entry in the Psychedelic Alpha tracker; an apparent secondary-source claim of a Central-African 'decrim foothold' conflates iboga's native range with legal status). Ketamine is a registered medical anaesthetic (med). Iboga grows natively here but the Bwiti legal/cultural protection is documented for Gabon, not Congo, so ibogaine is treated conservatively as illegal (lowest confidence). Refined cocaine is illegal/enforced and coca leaf has no traditional standing. The death penalty was abolished in 2015, so no drug offence carries capital punishment (no 'cap'). Confidence is medium: cannabis/CBD/cocaine are well-sourced, while the psychedelics and coca classifications are inferred from standard UN-convention adherence with limited Congo-specific documentation.", can:"Illegal recreational & medical; no medical-cannabis program. Cultivation banned since a 1929 colonial decree; locally called 'mbanga' and grown as a cash crop despite prohibition.", cbd:"No legal CBD/hemp framework; sources advise assuming all cannabis-derived products are prohibited.", ket:"Registered anaesthetic / WHO essential medicine used across Sub-Saharan Africa; medical use only, recreational use illegal.", ibo:"Iboga (Tabernanthe iboga) is native to Congo's forests, but the documented Bwiti sacramental/legal protection exists in neighbouring Gabon, not Congo-Brazzaville. No formal Congolese legal exemption found — treated as a controlled hallucinogen (low confidence).", coc:"Refined cocaine illegal and enforced; Congo is a known transit point for South American/Asian drugs. Note: death penalty abolished in 2015, so no capital drug offences.", coca:"Coca leaf has no traditional use here; controlled under the UN conventions like other narcotics." } },
  RO: { n:"Romania", def:'ill', st:{ cbd:'legal', ket:'med' }, nt:{ _:"Romania is a strict-prohibition EU state. All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) plus cocaine and coca leaf are illegal and enforced; personal possession of high-risk drugs carries 6mo-3yr (cannabis lower tier). Possession is NOT decriminalized (criminal offence, though an assistance programme can substitute for jail). Ketamine is a registered medicine (med). THC-free CBD is legal OTC. Medical cannabis exists only on paper (<0.2% THC, nothing marketed). No death penalty (abolished 1990, EU member) so no capital provisions for drugs.", can:"Recreational illegal under Law 143/2000; classified high-risk (Table I). A 2013 law allows only <0.2% THC derivatives but no product is on the market, so access is effectively nil. 2023 '3grame' decrim bill (3g) rejected by all committees. Possession is a criminal offence (6mo-3yr), NOT decriminalized, though jail can be avoided via an integrated assistance programme.", cbd:"THC-free CBD oils, creams and cosmetics are legal and sold over the counter; CBD flower and edibles are restricted due to THC limits.", dmt:"DMT illegal (1971 Convention Schedule I). Ayahuasca only permitted in approved scientific/medical studies in hospitals/clinics; all other use illegal.", ket:"EU-authorised anaesthetic/analgesic medicine, used clinically in Romania; recreational/non-medical use controlled.", ibo:"No specific medical or decriminalized framework; treated as a controlled/illegal unapproved psychoactive. Not listed in major trackers (lower confidence).", coca:"No traditional/indigenous exemption in Romania; coca leaf falls under prohibited controlled substances." } },
  RU: { n:"Russia", def:'ill', st:{ ket:'med' }, nt:{ _:"Russia (RU) has among the world's strictest drug regimes. Cannabis (incl. CBD), psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine, cocaine and coca leaf are all List I (Govt Decision No. 681), prohibited and actively enforced under Criminal Code Art. 228/228.1 — no medical cannabis, no decriminalization, no religious/indigenous exemptions. Ketamine is the sole 'med' case: a registered psychotropic used as a medical anesthetic (heavily restricted), with recreational use illegal. 'cap' is NOT assigned: Russia maintains a death-penalty moratorium (last execution 1996); the maximum drug penalty is life imprisonment for large-scale trafficking, not capital punishment. Confidence high; status current as of 2025-2026.", can:"Fully illegal incl. medical; List I. Possession >6g criminal under Art. 228 (up to 15 yrs); <=6g is administrative offence but still prohibited.", cbd:"No medical exception; treated as cannabis derivative and prohibited. Non-THC cannabinoids sit in a grey unenforced zone but products are not legally available.", mdma:"List I narcotic, prohibited and enforced under Art. 228/228.1.", dmt:"DMT and ayahuasca are List I Schedule I narcotics; no religious exemption.", mes:"Mescaline (and peyote/San Pedro) are List I; purchase, transport and possession prohibited.", ket:"Controlled psychotropic registered for human medical/anesthetic use (very heavily restricted; veterinary access nearly impossible). Recreational use illegal.", coc:"List I narcotic, illegal and enforced. NB: Russia has a death-penalty moratorium (last execution 1996); max drug penalty is life imprisonment under Art. 228.1, so 'cap' not assigned.", coca:"No traditional/legal use; controlled as source of cocaine, illegal." } },
  RW: { n:"Rwanda", def:'ill', st:{ ket:'med' }, nt:{ _:"Rwanda prohibits all listed recreational/psychoactive substances under Law No. 03/2012 (Narcotic Drugs, Psychotropic Substances and Precursors) and the Penal Code, which incorporate the 1961/1971/1988 UN conventions. The death penalty was abolished in 2007, so no capital ('cap') status applies; trafficking nonetheless carries long prison terms. Cannabis: recreational illegal (1-3 yrs prison); medical legalized in 2021 but strictly export-oriented with no domestic patient access, and CBD is not separately legalized — so both scored 'ill' for real-world access. Classical psychedelics (psilocybin, LSD, MDMA, DMT, mescaline) and ibogaine are controlled with no therapeutic/religious exemptions ('ill'). Cocaine and coca leaf are prohibited ('ill'); no Andean-style coca exemption exists. Ketamine is a registered anaesthetic medicine ('med'), with recreational use illegal. Cannabis and ketamine are well-sourced; the classical psychedelics rest on convention-based scheduling rather than substance-specific Rwandan citations, hence medium confidence.", can:"Recreational cannabis illegal & enforced (1-3 yrs prison + fine). Medical cannabis legalized by 2021 Ministerial Order but market is export-only; no domestic patient access yet.", cbd:"Not distinguished from other cannabis derivatives in Rwandan law; no clear legal access route, effectively prohibited.", ket:"Registered anaesthetic medicine, used in healthcare (esp. anaesthesia); recreational use prohibited.", coc:"Illegal and enforced; trafficking can carry long prison terms (death penalty abolished in Rwanda in 2007).", coca:"No traditional/indigenous use; treated as a prohibited narcotic." } },
  SM: { n:"San Marino", def:'ill', st:{ can:'med', ket:'med' }, nt:{ _:"San Marino is a small European microstate with strict, enforced drug laws (illicit possession/use/import/export/trafficking of narcotics carries 3-8 years imprisonment plus a fine). Recreational cannabis is illegal and enforced, though limited MEDICAL cannabis access exists — Sativex is provided free to MS and spinal/bone-marrow patients since ~2016, and a government-approved 2016 petition started building a medical-cannabis framework. CBD sits in an unregulated gray area (San Marino is non-EU and ignores the EU CBD ruling); treated as stricter. Classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline), ibogaine, refined cocaine and coca leaf fall under the controlled-narcotics regime as illegal/enforced — no decrim, religious, or traditional-use exemptions found, and San Marino is not separately listed in psychedelic-law trackers (statuses inferred from its general narcotics framework). Ketamine is a registered medicine (med). No capital punishment — San Marino abolished the death penalty entirely — so no 'cap'. Confidence medium: cannabis/CBD well-sourced; other substances inferred from the overarching narcotics framework rather than substance-specific San Marino sources.", can:"Recreational cannabis illegal & enforced; possession/use/trafficking penalties 3-8 years prison + fine. BUT medical access exists: Sativex (cannabis spray) provided free to MS and spinal/bone-marrow patients since ~2016, and a 2016 govt-approved petition began establishing a medical-cannabis framework.", cbd:"Legal gray area, not explicitly legalized; San Marino is non-EU and does not recognize the EU 'CBD is not a narcotic' ruling. Sources advise avoiding unless medically prescribed — treated as stricter (illegal) given ambiguity.", ket:"Registered/medical use as anesthetic; recreational use illegal under narcotics law.", coca:"No traditional/indigenous use; treated as a controlled narcotic like refined cocaine." } },
  SA: { n:"Saudi Arabia", def:'cap', st:{ cbd:'ill', mes:'ill', ket:'med', ibo:'ill', coca:'ill' }, nt:{ _:"Saudi Arabia runs a zero-tolerance drug regime under Sharia, the 2005 Law on Combatting Narcotic Drugs and Psychotropic Substances, and a 1987 fatwa mandating death for drug smuggling. Drug trafficking/smuggling and repeat dealing carry capital punishment, actively applied (356 executions in 2025, 243 drug-related; 122 drug-related in 2024). Cannabis, CBD, and all classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) are prohibited with no medical, research, or religious exemptions; cocaine and coca leaf are likewise banned. Major trafficked substances (cannabis, the main psychedelics, cocaine) are scored 'cap' given genuine death-penalty exposure; niche substances mostly hitting personal-possession penalties (CBD, mescaline, ibogaine, coca leaf) scored 'ill'. Ketamine is the sole 'med' case — a registered medicine used in Saudi hospitals and clinics, monitored via the SFDA Raqeeb platform, with recreational use illegal.", can:"Fully illegal incl. medical/CBD; no program. Trafficking/smuggling & repeat dealing are capital offences under 2005 Narcotics Law + 1987 fatwa. Hashish frequently features in drug-execution cases.", cbd:"Treated identically to cannabis (a prohibited narcotic); no hemp/medical carve-out. Active airport & mail screening. Personal possession 6mo–2yr; criminally enforced.", psi:"Prohibited psychotropic under UN-convention-based schedules; no research/religious exemption. Trafficking falls under capital framework.", lsd:"Prohibited psychotropic; no exemptions. Trafficking capital-eligible.", mdma:"Prohibited; no clinical/therapy access. Trafficking capital-eligible. Psychedelic-assisted therapy remains only a topic of discussion, not legal practice.", dmt:"Ayahuasca/DMT prohibited; no religious exemption (non-Islamic religious practice itself restricted). Trafficking capital-eligible.", mes:"Peyote/San Pedro prohibited as controlled substance; no traditional use. Personal possession 6mo–2yr; criminally enforced.", ket:"Registered medicine — used in Saudi hospitals/ICUs and a growing ketamine-clinic market; monitored via SFDA 'Raqeeb' controlled-substance platform. Recreational use illegal.", ibo:"No approval or access pathway; falls under blanket psychotropic prohibition. Criminally enforced.", coc:"Refined cocaine illegal; trafficking/smuggling is a capital offence — featured in actual drug executions of foreign nationals.", coca:"Raw coca leaf prohibited as a narcotic plant; no traditional/permitted use. Criminally enforced." } },
  SN: { n:"Senegal", def:'ill', st:{ ket:'med' }, nt:{ _:"Senegal prohibits all listed substances under the Code des Drogues (Loi 97-18, amended 2007), which classifies them as Schedule I 'high-risk drugs'. Trafficking/cultivation carries 10-20 years forced labour; personal possession/use is a criminal offence (Art. 109) and is enforced. The death penalty was abolished for ALL crimes in 2004, so no 'cap'. Cannabis (incl. medical) and CBD are explicitly illegal with no exemptions. Psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline and ibogaine have no country-specific data and no religious/indigenous carve-outs — all fall under the general Schedule I prohibition (ill). Ketamine is a registered essential medicine used as an anaesthetic (med); recreational use is prohibited. Refined cocaine is illegal and heavily enforced (major transit hub); coca leaf has no traditional use and is likewise prohibited. Higher confidence on cannabis/CBD/cocaine/ketamine (direct sourcing); psychedelics and coca leaf inferred from the framework (medium).", can:"Illegal recreational & medical, no exemptions; production in Casamance actively targeted/burned (Code des Drogues, Loi 97-18 as amended by Loi 2007-31).", cbd:"Explicitly illegal — treated as a controlled substance with no medical carve-out.", psi:"No substance-specific exemption; falls under Schedule I hallucinogen prohibition. No death penalty (abolished 2004); personal possession is a criminal offence (Art. 109).", ket:"Registered anaesthetic / WHO essential medicine, widely used in hospitals across Senegal & Sub-Saharan Africa; recreational use prohibited.", coc:"Schedule I ('drogue à haut risque'); Senegal is a major transit hub with large, enforced seizures (e.g. 643 kg, Aug 2025).", coca:"No traditional/indigenous use in West Africa; coca leaf falls under Single Convention Schedule I narcotic prohibition." } },
  SL: { n:"Sierra Leone", def:'ill', st:{ ket:'med', coc:'cap' }, nt:{ _:"Sierra Leone operates a strict, UNODC-modeled prohibition regime under the National Drugs Control Act 2008. Cannabis and CBD are illegal (life imprisonment for cultivation/sale; mandatory 5-yr minimum for possession, suspendable for first offenders entering treatment). All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) and coca leaf are prohibited with no medical, research, religious, or indigenous carve-outs. Ketamine is a registered anesthetic on the National Essential Medicines List (med). Refined cocaine is treated most severely (cap): trafficking and possession of cocaine/heroin-making materials carry mandatory life imprisonment, and a December 2025 Judiciary Practice Direction added a no-bail policy and 30-year minimum sentences under s.7. The death penalty was abolished in 2021, so severity is via long mandatory sentences rather than execution. Note: synthetic 'kush' (nitazenes/synthetic cannabinoids) triggered a national emergency in April 2024, reinforcing the punitive direction of policy.", can:"Illegal under National Drugs Control Act 2008; life imprisonment for sale/cultivation, mandatory 5-yr minimum for possession/use (sentence can be suspended for first offenders entering treatment). Widely cultivated/used in practice but enforced. No medical-cannabis program despite occasional reform talk.", cbd:"Not differentiated from cannabis under the 2008 Act; no legal/regulated CBD market.", psi:"Prohibited drug; no medical/research or religious carve-out; enforced criminal offence.", dmt:"No ayahuasca religious exemption exists; treated as a prohibited drug.", ket:"Registered anesthetic on Sierra Leone's National Essential Medicines List (injection 10/50/100 mg/ml); recreational use illegal.", ibo:"Iboga is native to Central Africa (Gabon), not Sierra Leone; no separate legal status, treated as a prohibited drug.", coc:"Cocaine is the explicit target of the 2008 Act (passed after the 2008 cocaine-plane scandal). Trafficking and possession of cocaine/heroin-making materials carry mandatory life imprisonment; a Dec 1 2025 Judiciary Practice Direction adds no-bail and 30-yr minimum sentences under s.7. Death penalty abolished 2021, but mandatory sentences are extremely severe.", coca:"No traditional/indigenous coca use in Sierra Leone; treated as a prohibited narcotic." } },
  SG: { n:"Singapore", def:'cap', st:{ cbd:'ill', ket:'med', ibo:'ill', coca:'ill' }, nt:{ _:"Singapore has one of the world's strictest drug regimes under the Misuse of Drugs Act. Cannabis, CBD/hemp, cocaine, MDMA, LSD, psilocybin, DMT, mescaline and ketamine are all Class A controlled drugs. Trafficking above thresholds (e.g. >500g cannabis, >30g cocaine, plus MDMA, heroin, meth) carries the MANDATORY DEATH PENALTY — a cannabis-trafficking execution was carried out in April 2026. Hence most substances are coded 'cap'. Exceptions: esketamine (Spravato) is HSA-approved for treatment-resistant depression since Oct 2020 → ketamine 'med' (recreational still illegal). CBD is fully prohibited as a cannabis derivative with only a vanishingly rare Epidiolex special-access exception for ~2 pediatric patients → coded 'ill'. Coca leaf and ibogaine are controlled/prohibited with no access → 'ill'.", can:"Class A controlled drug under Misuse of Drugs Act; zero-tolerance. Trafficking/importing >500g carries mandatory death penalty (man executed for cannabis in April 2026). Possession/consumption up to 10 yrs jail / S$20,000.", cbd:"Cannabis & all derivatives incl. CBD/hemp are Class A controlled (First Schedule) — banned even in trace amounts. Extremely rare special-access exception: only ~2 young patients granted Epidiolex after exhausting all other options. No real-world patient/research access.", psi:"Class A controlled drug; psilocybin/psilocin in Misuse of Drugs framework. No medical or research access. Severe mandatory penalties; trafficking subject to capital regime.", lsd:"Class A controlled drug. No medical/research carve-out; long mandatory imprisonment + caning, capital trafficking regime.", mdma:"Class A controlled drug; trafficking above threshold carries mandatory death penalty. No therapy/research access.", dmt:"DMT and ayahuasca prohibited under Misuse of Drugs Act (Class A). No religious/indigenous exemption.", mes:"Mescaline (and peyote/San Pedro derivatives) controlled under Misuse of Drugs Act. No traditional-use exemption.", ket:"Class A controlled drug; recreational use illegal (up to 10 yrs jail / S$20k). BUT esketamine (Spravato) HSA-approved Oct 2020 for treatment-resistant/major depressive disorder under stringent safeguards — genuine prescribed medical access for the pharmaceutical form.", ibo:"No specific public listing found, but prohibited as a controlled/psychoactive substance under the Misuse of Drugs Act and Singapore's psychoactive-substances framework. No medical access.", coc:"Class A controlled drug; trafficking/import/export >30g carries mandatory death penalty.", coca:"Coca leaf and derivatives controlled under Misuse of Drugs Act (Class A); no traditional/legal use. Illegal and enforced." } },
  SK: { n:"Slovakia", def:'ill', st:{ cbd:'tol', ket:'med' }, nt:{ _:"Slovakia has one of the EU's strictest drug regimes (Criminal Code s.172; Narcotics Act 139/1998), with no soft/hard distinction. Cannabis (incl. medical), psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, cocaine and coca leaf are all illegal and enforced; possession is criminal (a 2022 amendment reduced small personal-use penalties but did NOT decriminalize). CBD (<=0.3% THC, hemp-derived) is legal since May 2021, though ingestibles are restricted by EU novel-food rules. Ketamine is a registered prescription medicine (med). Ibogaine has no specific regulation but is treated conservatively as illegal. No death penalty (EU abolitionist); trafficking sentences are long (3-25 yrs) but not 'cap'.", can:"Illegal/criminal; no medical cannabis program. Possession of even one joint up to 8 yrs; 2022 amendment softened personal-use possession (up to ~1 yr for <=3 doses, ~2 yrs for <=10 doses) but NOT decriminalized. Multiple decrim bills failed; Fico govt opposed.", cbd:"Removed from controlled-substances list 1 May 2021; hemp-derived CBD with <=0.3% THC legal, no possession limits. Ingestible/food CBD restricted under EU novel-food rules, so often sold as cosmetics/topicals.", psi:"Controlled; illegal and enforced. No medical/research carve-out (contrast neighbouring Czechia, which approved medical psilocybin from 2026).", dmt:"DMT/ayahuasca/changa treated as controlled (Schedule I) narcotics; illegal and enforced.", ket:"EU-registered prescription anaesthetic (med); recreational use illegal.", ibo:"No Slovakia-specific regulation found and not listed in ibogaine/psychedelic trackers; classified conservatively as illegal given Slovakia's strict narcotics framework and absence of any legal access. Lower confidence.", coca:"Raw coca leaf controlled as a narcotic under the 1961 Single Convention framework Slovakia follows; no traditional-use exemption." } },
  SI: { n:"Slovenia", def:'decrim', st:{ can:'med', cbd:'legal', ket:'med', coca:'ill' }, nt:{ _:"Slovenia operates a substance-agnostic decriminalization model: personal-use possession of any drug in small quantities is a misdemeanor (fine ~€36-209), not a criminal offence, while manufacture/sale/trafficking remain criminal (1-10 yrs, up to 15 if minors). As an EU member there is no death penalty. Cannabis: recreational decriminalized; medical fully legalized (Medical and Scientific Cannabis Act, in force 20 Aug 2025); an adult-use legalization bill cleared EU notification (Feb 2026) but had not yet passed parliament by mid-2026. CBD <0.2% THC is legally sold (novel-food grey area). Classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca) are Schedule I but personal possession is decriminalized; mescaline and ibogaine fall under the same general decrim framework (ibogaine lower confidence). Ketamine is a registered medicine (med). Refined cocaine is illegal but personal possession is decriminalized like other drugs; raw coca leaf is illegal with no traditional-use exemption.", can:"Recreational illegal but decriminalized: personal-use possession is a misdemeanor (fine ~€36-209), not a crime. 2024 advisory referendum backed adult-use (51.6%); a legalization bill (4 plants/person, 7g public carry, up to 150g at home) cleared EU TRIS standstill (ended 2 Feb 2026) but had NOT yet passed parliament as of mid-2026 (still in 3-hearing process). Medical cannabis fully legalized via the Medical and Scientific Cannabis Act, in force 20 Aug 2025 — physicians may prescribe for any indication via a 'cannabis card'.", cbd:"CBD products with <0.2% THC sold legally, mainly as food supplements; EU novel-food rules create a grey area and limited availability, but products (oils, cosmetics, edibles) are widely sold.", psi:"Schedule I (Decree on Classification of Illicit Drugs); personal-use possession decriminalized as a misdemeanor fine.", lsd:"Schedule I; personal-use possession decriminalized (misdemeanor fine).", mdma:"Schedule I; personal-use possession decriminalized (misdemeanor fine). Manufacture/sale 1-10 yrs (Criminal Code Art. 186).", dmt:"DMT/ayahuasca Schedule I; personal-use possession decriminalized (misdemeanor fine). No religious-use exemption.", mes:"Controlled psychotropic; covered by Slovenia's substance-agnostic personal-use decriminalization (misdemeanor fine). No specific peyote/San Pedro carve-out.", ket:"Registered medicine/anesthetic (medical use legal); non-medical/recreational use prohibited, personal possession decriminalized as a misdemeanor.", ibo:"Not separately profiled; falls under general controlled-substance regime where personal-use possession is decriminalized (misdemeanor fine). No approved medical/addiction-treatment program. Lower confidence on exact scheduling.", coc:"Illegal; however personal-use possession of any drug (incl. cocaine) is decriminalized as a misdemeanor (fine ~€36-209). Manufacture/trafficking criminal (1-10 yrs, up to 15 if minors). EU state — no death penalty.", coca:"Raw coca leaf illegal; no traditional/indigenous-use exemption and no realistic personal-use carve-out distinct from cocaine." } },
  SB: { n:"Solomon Islands", def:'ill', st:{ ket:'med' }, nt:{ _:"Solomon Islands is governed by the colonial-era Dangerous Drugs Act (Cap. 49), whose 'dangerous drugs' list (s.2) covers cocaine, coca leaf, crude cocaine, heroin/diacetylmorphine, ecgonine, Indian hemp (cannabis), and opium/morphine — but NOT modern synthetics. Cannabis, cocaine, coca leaf, opiates are illegal and enforced (cannabis up to ~10 yrs/large fine; cocaine actively interdicted via Pacific narco-trafficking routes). A well-documented loophole meant methamphetamine, ketamine and ecstasy/MDMA were unclassified until the Dangerous Drugs (Amendment) Bill 2025, which (as of 2026) is under parliamentary committee and raises max penalties to large fines and life imprisonment — NO death penalty. Classic psychedelics (psilocybin, LSD, DMT, mescaline, ibogaine) are not named in the statute and absent from psychedelic-law trackers; they are technically unscheduled but have no legal/medical access, so are classed 'ill' conservatively with low confidence. Ketamine treated as a registered medicine ('med'). No medical-cannabis or CBD program exists. High confidence on cannabis/cocaine/coca; lower on the unscheduled psychedelics and the in-flux synthetics.", can:"Illegal & enforced as 'Indian hemp' under Dangerous Drugs Act (Cap. 49); up to ~10 yrs and/or large fine. No medical/recreational carve-out.", cbd:"No separate CBD provision; falls under cannabis prohibition. No medical-cannabis or CBD program exists.", psi:"Not named in the Dangerous Drugs Act schedule (a narrow colonial-era list) and absent from Psychedelic Alpha's tracker. Technically unscheduled, but no legal access/market and law is actively being tightened — classed ill conservatively (low confidence).", lsd:"Not specifically scheduled in the Dangerous Drugs Act; technically unscheduled but no legal access. Classed ill conservatively (low confidence).", mdma:"Was an unclassified loophole — Solomon Islands law did NOT classify ecstasy/MDMA as a 'dangerous drug' until the Dangerous Drugs (Amendment) Bill 2025 (under parliamentary committee as of 2026). De-facto illicit (seized/targeted).", dmt:"Ayahuasca/DMT not named in the Act and not on Psychedelic Alpha's tracker; technically unscheduled but no legal/religious-use framework. Classed ill conservatively (low confidence).", mes:"Mescaline (peyote/San Pedro) not named in the Act; technically unscheduled but no legal access framework. Classed ill conservatively (low confidence).", ket:"Historically NOT scheduled (named loophole alongside meth/ecstasy); being brought under control by the 2025 amendment. Registered medicine regionally — treated as med (clinical) with recreational use criminalized. Framework in flux; low confidence.", ibo:"Ibogaine not named in the Act and not on Psychedelic Alpha's tracker; technically unscheduled, no legal/clinical access. Classed ill conservatively (low confidence).", coc:"Refined cocaine ('cocaine'/'crude cocaine') explicitly scheduled and enforced; Solomon Islands is a Pacific trafficking transit point (narco-subs, seizures 2025).", coca:"'Coca leaf' is explicitly listed as a dangerous drug in s.2 of the Act; no traditional-use exemption (non-Andean country)." } },
  SO: { n:"Somalia", def:'ill', st:{ can:'cap', ket:'med', coc:'cap' }, nt:{ _:"Somalia prohibits all listed substances except ketamine (a registered essential medicine = 'med'). Cannabis is the main illicit drug, criminalized under the Drug & Related Substances Act 1992; no medical cannabis or CBD framework. Somalia is one of very few countries actively executing people (34+ in 2024), and drug trafficking can genuinely carry capital/severe punishment under statutory and Sharia law — so cannabis and cocaine are marked 'cap'; in Al-Shabaab-held areas drug offenders are publicly flogged. Psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) and coca leaf have no medical/decrim/traditional carve-out and are illegal and enforced. Confidence is medium: the statutory code is outdated (1964) and enforcement is fragmented between federal authorities and non-state actors, creating uncertainty about consistent application (esp. capital punishment for low-level possession vs. trafficking).", can:"Illegal under the Drug & Related Substances Act 1992 as a 'habit-forming drug'; possession up to 10 yrs (1-5 yrs if <60g), all cultivation/supply banned. No medical cannabis. In Al-Shabaab-controlled areas, offenders publicly flogged. Drug trafficking can carry capital/severe punishment under statutory + Sharia law.", cbd:"No separate legal status; treated as cannabis = illegal. No CBD market or carve-out.", dmt:"No religious/traditional ayahuasca framework; prohibited and enforced.", mes:"No peyote/San Pedro tradition; prohibited and enforced.", ket:"WHO essential medicine and appears on Somalia's Essential Medicines List (2019); the main anaesthetic in rural areas. Legal for medical use; recreational use illegal.", coc:"Refined cocaine illegal; drug trafficking can carry the death penalty in Somalia (one of the few countries with active executions, 34+ in 2024), esp. under Sharia.", coca:"No coca tradition; treated as a prohibited narcotic = illegal/enforced." } },
  ZA: { n:"South Africa", def:'ill', st:{ can:'decrim', cbd:'legal', ket:'med', ibo:'med' }, nt:{ _:"South Africa: cannabis decriminalised for private adult use (Cannabis for Private Purposes Act 2024, post-2018 ConCourt ruling) but no legal commercial sale; low-dose CBD is OTC (Schedule 0). Ibogaine (Schedule 6) and ketamine (Schedule 5/6) are legally available as prescribed/clinical medicines — South Africa is notable for formal clinical ibogaine access. Classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline), refined cocaine and raw coca leaf are all prohibited and enforced as criminal offences with no religious/therapeutic exemption. No death penalty (abolished 1995), so no 'cap' statuses.", can:"Private adult use, possession & cultivation decriminalised since 2018 Constitutional Court ruling; codified by Cannabis for Private Purposes Act (signed May 2024). Commercial sale still prohibited; draft possession/cultivation regs out for public comment early 2026.", cbd:"Low-dose CBD (max ~20mg/day, =0.001% THC) exempted to Schedule 0 and sold OTC since 2019/2020 exemption notices; higher-dose/therapeutic CBD is Schedule 4 (prescription).", psi:"Part I undesirable dependence-producing substance under Drugs & Drug Trafficking Act 140/1992 + Medicines Act 101/1965; criminal offence. Decriminalisation argued in academia/litigation but not enacted.", ket:"Registered medicine (Schedule 5/6); widely used anaesthetic/analgesic and in private ketamine-for-depression clinics. Recreational use illegal.", ibo:"Schedule 6 controlled substance, legally prescribable by a registered medical practitioner under SAHPRA oversight; South Africa is one of the few countries with formal clinical ibogaine treatment (Cape Town/Johannesburg clinics).", coca:"Coca leaf controlled under Drugs & Drug Trafficking Act (only decocainised leaf/cocaine-free extracts exempt); no traditional-use exemption." } },
  KR: { n:"South Korea", def:'ill', st:{ cbd:'med', mdma:'cap', ket:'med', coc:'cap' }, nt:{ _:"South Korea runs a strict zero-tolerance drug regime under the Narcotics Control Act (consolidating the former Cannabis Control Act), splitting controlled drugs into narcotics, psychotropics, and cannabis. All classic psychedelics (psilocybin, LSD, DMT/ayahuasca, mescaline, ibogaine) and MDMA are scheduled and criminally enforced, with no decriminalization and no religious/indigenous exemptions. Possession/use can draw multi-year prison terms; large-scale trafficking of narcotics/psychotropics (e.g., cocaine, MDMA) is theoretically capital-eligible (death penalty retained on the books, though not carried out in recent practice), hence 'cap' for refined cocaine and MDMA, conservatively. Recreational cannabis is fully illegal (up to 5 years); a narrow medical-cannabis route has existed since 2018-2019 for limited approved products, and a late-2025 MFDS pilot allows tightly controlled CBD clinical trials for epilepsy only — so CBD/medical cannabis access is best coded 'med' (research/medical-only, not consumer-legal). Ketamine is a regulated medicine used clinically. Coca leaf is named among controlled narcotics with no traditional-use allowance. Confidence high for the prohibition framework; the 'cap' codings reflect statutory maximums rather than active enforcement.", can:"Recreational cannabis fully illegal and enforced; possession up to 5 years' prison or fines up to ~50M KRW. Korea has pursued citizens for overseas use.", cbd:"Not legal for consumers. Limited medical cannabis route since 2018-2019 (narrow approved products via KODA import). Late-2025 MFDS pilot permits tightly controlled CBD clinical trials for epilepsy only.", psi:"Psilocybin controlled as a psychotropic under the Narcotics Control Act; zero-tolerance, no religious/research exemption.", mdma:"Grouped with the most severely penalised drugs; large-scale trafficking is theoretically capital-eligible under the Narcotics Control Act (death penalty on the books, not used in recent practice).", dmt:"DMT/ayahuasca controlled as psychotropics; no religious or indigenous exemption.", ket:"Ketamine is a regulated/controlled medicine used clinically in hospitals; non-medical use illegal.", coc:"Refined cocaine is a scheduled narcotic with the most severe penalties; large-scale trafficking is capital-eligible (death penalty retained on paper, no recent executions).", coca:"Coca is explicitly named among controlled narcotics in the Narcotics Control Act; no traditional-use allowance, illegal." } },
  SS: { n:"South Sudan", def:'ill', st:{ can:'cap', ket:'med', coc:'cap' }, nt:{ _:"South Sudan is a low-data, conflict-affected jurisdiction with broad drug prohibition rooted in its Penal Code Act 2008. Cannabis is explicitly illegal for all purposes including medical, with no CBD exemption. The country is repeatedly listed among the small set of states that retain the death penalty for drug trafficking on the books (with Cuba, Sudan, Mauritania, Gaza), though sources describe enforcement as symbolic with no reported executions — hence 'cap' applied conservatively to the main trafficking-targeted drugs (cannabis, cocaine). No South Sudan-specific legislation or programs were found for psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine); these are treated as illegal/enforced under the general prohibitive framework with no research, medical, or religious-use carve-outs. Ketamine is coded 'med' per the near-universal default (registered medicine), and coca leaf 'ill' (no traditional use). Confidence is low because most determinations beyond cannabis are inferred from the general legal framework rather than substance-specific primary sources.", can:"Cannabis fully illegal for recreational AND medical use; no CBD carve-out. South Sudan is listed among the few states retaining capital punishment for drug trafficking, though enforcement is described as 'symbolic' with no reported executions.", cbd:"No separate CBD legal category; falls under blanket cannabis prohibition.", mdma:"No SS-specific legislation found; treated as illegal under general prohibition (could plausibly fall under capital trafficking provisions, kept conservative).", ket:"No SS-specific data; coded 'med' per global default (ketamine a registered anaesthetic medicine almost everywhere; recreational use illegal). Low confidence for SS specifically.", coc:"Refined cocaine illegal; subject to drug-trafficking provisions which can carry the death penalty on paper (enforcement symbolic).", coca:"No traditional coca use in South Sudan; treated as a prohibited substance." } },
  ES: { n:"Spain", def:'decrim', st:{ can:'med', cbd:'legal', ket:'med', ibo:'med', coca:'ill' }, nt:{ _:"Spain decriminalizes personal use/possession of ALL drugs in private (administrative, not criminal); cultivation/sale/trafficking remain criminal offences and public use/possession draws fines (€601-30,000) under the Citizens' Security Law. No death penalty or long mandatory minimums. Cannabis: private use decrim + social-club grey area; medical cannabis (extracts) legalized Oct 2025 (RD 903/2025). CBD legal as cosmetics/hemp. Classic psychedelics (psilocybin, LSD, MDMA, mescaline) controlled but personal possession decrim. Ayahuasca not explicitly scheduled, favorable 2025 Madrid court ruling. Ketamine = registered medicine. Ibogaine tolerated medically with ongoing Phase II trials. Cocaine: trafficking illegal but personal use decrim; raw coca leaf has no legal carve-out (ill).", can:"Personal use/possession in private decriminalized (administrative, not criminal); cannabis social clubs operate in a legal grey area. Medical cannabis (extracts only) legalized via Royal Decree 903/2025, Oct 2025, hospital-prescribed. Sale/trafficking remains criminal.", cbd:"Legal as cosmetics/topicals and hemp products (<0.2% THC); ingestible CBD unauthorized as food under EU novel-food rules.", psi:"Controlled (UN Annex I); sale/trafficking criminal, but personal possession/use decriminalized (administrative offence). Spores/grow kits legal.", lsd:"Annex I controlled; personal possession decriminalized, trafficking criminal.", mdma:"Controlled substance (listed in BOE); personal possession decriminalized, trafficking criminal. Some exceptional/research access.", dmt:"DMT is controlled, but ayahuasca as a plant brew is not explicitly scheduled; numerous import cases ended in acquittal/dismissal. TSJM ruling 316/2025 (Madrid) found ayahuasca not a controlled substance. Personal possession effectively decriminalized; no one imprisoned for ayahuasca.", mes:"Mescaline expressly listed as controlled in the consolidated BOE text; personal possession decriminalized. Cacti (peyote/San Pedro) not explicitly listed.", ket:"Registered medicine for human/veterinary anesthesia; recreational use prohibited (public use = administrative fine).", ibo:"Not a standard scheduled/prescription drug; administration tolerated in supervised medical settings; Spain running Phase II clinical trials for substance-use disorders.", coc:"Sale/trafficking strictly illegal and enforced, but private personal use/possession decriminalized with administrative fine only.", coca:"No traditional/legal coca-leaf carve-out in Spain; treated under the controlled-substance regime (source of cocaine). Personal possession would be handled administratively like other drugs, but no specific authorization exists." } },
  LK: { n:"Sri Lanka", def:'ill', st:{ can:'med', ket:'med', coc:'cap' }, nt:{ _:"Sri Lanka prohibits virtually all the listed substances under the Poisons, Opium and Dangerous Drugs Ordinance. Cannabis is the notable exception: recreational use is illegal and enforced, but a genuine licensed medical/Ayurvedic supply chain exists (Ayurvedic Drugs Corporation + registered Ayurveda practitioners) and government-approved medical/scientific cultivation is expanding (2024-2025 foreign-investor licenses under a UN agreement) — hence 'med'. CBD is illegal outside that Ayurveda channel. Ketamine is a regulated NMRA medicine ('med'). Classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) and ibogaine are illegal with no medical/research or religious exemptions. Refined cocaine is 'cap': it is explicitly named in the 5-gram death-penalty/life-imprisonment threshold (Act No.41 of 2022, reaffirmed by the 2026 high-seas amendment) and cocaine manufacture carries death/life — though Sri Lanka has not executed anyone since 1976 (abolitionist de facto). Raw coca leaf has no traditional/legal status and is classified 'ill'.", can:"Recreational illegal & enforced (cultivation up to 20 yrs). Genuine medical route: cannabis legally supplied via the regulated Ayurveda system (Ayurvedic Drugs Corporation / licensed Ayurveda practitioners) under the Poisons, Opium & Dangerous Drugs Ordinance's galenical-preparations exemption; govt-approved medical/scientific cultivation expanding (UN-agreed, first foreign-investor licenses 2024-2025).", cbd:"Treated as part of the hemp plant — illegal to import, possess or sell regardless of THC content; only legal via Ayurveda prescription. No general legal CBD/hemp market.", psi:"Magic mushrooms/psilocybin prohibited as a dangerous drug; no medical or research access.", lsd:"Illegal/controlled; present in affluent nightlife but criminalized, no medical access.", mdma:"Illegal/controlled dangerous drug; no medical or research exemption.", dmt:"DMT/ayahuasca illegal; no religious or indigenous-use exemption.", mes:"Mescaline (peyote/San Pedro) illegal; no traditional/religious exemption.", ket:"Registered medicine (anaesthesia/analgesia) regulated by the National Medicines Regulatory Authority (NMRA); non-medical use illegal.", ibo:"Ibogaine has no legal or approved medical status; falls under general dangerous-drugs prohibition.", coc:"Refined cocaine named in the death-penalty/life-imprisonment threshold: trafficking/possessing 5+ g of cocaine, heroin, morphine or methamphetamine carries death or life (Act No. 41 of 2022; reaffirmed by 2026 high-seas amendment). Manufacture of cocaine also death/life. Note: de-facto execution moratorium since 1976 (abolitionist de facto), but capital statutes remain in force and new death sentences are still imposed.", coca:"Raw coca leaf has no traditional or legal status in Sri Lanka; prohibited as a dangerous drug. (No specific coca-leaf capital threshold identified, so classified ill rather than cap.)" } },
  SD: { n:"Sudan", def:'ill', st:{ ket:'med' }, nt:{ _:"Sudan is a strict prohibition jurisdiction. Its 1994 Narcotic Drugs and Psychotropic Substances Act implements the three UN drug conventions, so cannabis (banned since 1924), CBD, and all classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline) plus cocaine and coca leaf are illegal with no medical, research, or religious exceptions. Ketamine is the lone exception, available as a registered anaesthetic on the national essential medicines list. Sudan introduced the death penalty for drug offences in 1989 and statute authorizes capital punishment for trafficking (e.g. supplying drugs in/around schools or large-quantity smuggling); however, international trackers classify Sudan's drug death penalty as \"symbolic\" (on the books, not actively executed), so substances are coded as enforced-illegal (ill) rather than cap, with the capital-trafficking provision flagged in notes. Confidence is medium: the prohibitionist framework is clear, but per-substance scheduling is inferred from treaty obligations rather than a primary Sudanese schedule, and the ongoing civil war (since April 2023) has degraded enforcement and regulatory institutions, making real-world status fluid.", can:"Banned since 1924 (Anglo-Egyptian condominium); no medical or recreational allowance, enforced as criminal offence. Trafficking/large-quantity smuggling can in statute trigger the death penalty (see general note).", cbd:"No cannabis exemption; CBD prohibited even when THC-free. No medical-cannabis program.", psi:"Schedule I psychotropic under Sudan's 1994 Narcotic Drugs and Psychotropic Substances Act (implements 1971 UN Convention); no medical/research access.", lsd:"Controlled as Schedule I psychotropic under the 1994 Act / 1971 UN Convention; illegal, no therapeutic access.", mdma:"Schedule I psychotropic under the 1994 Act / 1971 UN Convention; illegal, no approved therapy.", dmt:"DMT controlled under the 1994 Act / 1971 UN Convention; no religious or ayahuasca exemption exists in Sudan.", mes:"Mescaline controlled under the 1994 Act / 1971 UN Convention; no peyote/San Pedro religious or indigenous exemption.", ket:"Registered anaesthetic on Sudan's National Essential Medicines List (2014); critical for surgery in a resource-limited setting. Medical use only; recreational use illegal.", ibo:"No registered medical use and no specific legal framework; falls under general prohibition with no real-world access. Sudan-specific data is sparse.", coc:"Refined cocaine controlled under the 1961 Single Convention via the 1994 Act; illegal and trafficking-sensitive.", coca:"No traditional/indigenous coca use in Sudan; raw coca leaf prohibited under the 1961 Single Convention via the 1994 Act." } },
  SR: { n:"Suriname", def:'ill', st:{ ket:'med' }, nt:{ _:"Suriname enforces strict, largely uniform drug prohibition. Cannabis (incl. CBD as a controlled substance) and all classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) are Schedule I / illegal with severe penalties (psilocybin up to ~13 yrs; cannabis supply 8-15 yrs); there is no medical-cannabis program and no religious/indigenous ayahuasca exemption. A 2023 Industrial Hemp Act allows licensed low-THC hemp cultivation for CBD export only. Refined cocaine is illegal/enforced (Suriname is a major transit hub) and coca leaf has no traditional-use carve-out. Ketamine is classified 'med' per the standard registered-anesthetic pattern. Ibogaine has no specific or permissive regulation and defaults to prohibition. The death penalty was fully abolished in 2015, so no 'cap' applies; max prison terms were raised to 50 years. Confidence medium: cannabis, psychedelics and death-penalty abolition are well sourced, while ketamine and ibogaine are inferred from general patterns and the absence of any permissive framework.", can:"Illegal for recreational and medical use; no medical program (stalled since 2020). Cultivation/sale punishable by 8-15 yrs. Some sources note a small personal-possession tolerance (~8g) and lax enforcement of public use, but this is weakly sourced and supply is heavily penalized.", cbd:"Treated as a controlled substance for consumer use. However, the 2023 Industrial Hemp Cultivation Act permits licensed hemp cultivation (THC <0.3%) for commercial CBD export to foreign manufacturers - an agriculture/export framework, not domestic CBD legality.", psi:"Schedule I / most restrictive controlled-substances list; possession reportedly up to ~13 years.", dmt:"Schedule I; illegal. No religious or indigenous ayahuasca exemption (Suriname absent from ICEERS and Wikipedia ayahuasca legal maps).", ket:"No Suriname-specific scheduling confirmed; classified 'med' per the near-universal pattern of ketamine as a registered anesthetic medicine, with recreational use illegal.", coc:"Illegal and enforced; Suriname is a significant cocaine transit country. Death penalty abolished entirely in 2015, so no capital punishment for drug offences (max prison terms raised to 50 yrs).", coca:"Not an Andean producer; no traditional/indigenous coca-leaf allowance. Falls under general prohibition." } },
  SZ: { n:"Swaziland", def:'ill', st:{ ket:'med' }, nt:{ _:"Eswatini (SZ) prohibits and enforces against all listed substances except ketamine (a registered medicine). The 1922 Opium & Habit-Forming Drugs Act, Pharmacy (Amendment) Act 1992 and Medicines and Related Substances Control Act 2016 govern: Schedule 1 (cannabis, MDMA, heroin) and Schedule 2 (cocaine, methamphetamine). Cannabis possession carries up to 5 years, sale/cultivation up to 15 years + fines; CBD is not distinguished from cannabis. A medical-cannabis bill has been pending since 2020 but has not passed as of 2026, so there is no real-world patient access (one cultivation licensee, Profile Solutions, exists). No carve-outs for psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) or coca leaf. Capital punishment exists but is non-mandatory, with no executions since 1983, and drug offences are not capital crimes, so 'cap' is not assigned. Confidence medium: cannabis/CBD are well-sourced; other substances rest on the general controlled-substances regime rather than substance-specific Eswatini statutes.", can:"Illegal and enforced under 1922 Opium & Habit-Forming Drugs Act + Pharmacy (Amendment) Act 1992. Schedule 1. Possession up to 5 yrs; sale/cultivation/trafficking up to 15 yrs + fines. A medical-cannabis bill has been pending since 2020 (resurfaced 2023) but has NOT passed as of 2026 (needs 3/4 vote in both houses). One firm (Profile Solutions) holds a cultivation licence, but with no enacted enabling law there is no real patient access.", cbd:"No legal distinction from cannabis; CBD treated the same and is illegal.", mdma:"Explicitly listed in Schedule 1 alongside cannabis and heroin; illegal and enforced.", ket:"Regulated medicine under the Medicines and Related Substances Control Act 2016 / Essential Medicines List framework; recreational use illegal.", coc:"Schedule 2 controlled substance; illegal and enforced. Death penalty exists in Eswatini but is non-mandatory, no executions since 1983, and drug offences are not capital crimes.", coca:"No traditional/legal coca use in Southern Africa; falls under controlled-substances prohibition." } },
  SE: { n:"Sweden", def:'ill', st:{ can:'med', cbd:'med', ket:'med' }, nt:{ _:"Sweden (SE) maintains a strict zero-tolerance prohibition regime. Personal use and possession of all controlled drugs are criminal offences and actively enforced; there are no decriminalization reforms. As an EU member Sweden has no death penalty, and maximum sentences for the most serious trafficking offences are 6-10 years, so no 'cap' applies. Cannabis (Schedule I) and all classic/novel psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline), cocaine (Schedule II), coca leaf, and ibogaine are illegal and enforced (ill), with psychedelics permitted only in approved clinical research and no religious/indigenous exemptions. Ketamine is classified med: esketamine (Spravato) has been approved and recommended for treatment-resistant depression since 2019, with racemic ketamine also used medically. CBD is classified legal but is among the EU's most restricted: a 2019 Supreme Court ruling makes any product with detectable THC a narcotic, so only zero-THC CBD products may be sold and ingestibles are effectively barred. Confidence high for the prohibition picture and ketamine; medium on the CBD classification given its borderline restrictiveness.", can:"Schedule I narcotic under the Narcotic Drugs (Punishment) Act (1968:64). Recreational use, possession, sale and cultivation are criminal offences and enforced. Medical cannabis exists only via rare individual exemptions from the Medical Products Agency (MPA); Sativex (MS) approved since 2011. No general medical program.", cbd:"Among the strictest CBD regimes in the EU. 2019 Supreme Court ruling: any CBD product containing detectable THC is a narcotic preparation and illegal. Only truly zero-THC CBD products may be sold, and virtually no ingestible/edible CBD is permitted. Pure CBD itself is not scheduled, so zero-THC products are legally available but heavily restricted.", psi:"Schedule I narcotic; magic mushrooms illegal and enforced. Possession can carry fines and up to 6 months imprisonment. No medical/religious exemption; psychedelics permitted only in approved clinical research.", lsd:"Schedule I narcotic, illegal and enforced. In Nov 2025 the Public Health Agency proposed scheduling LSD analogues (1S-LSD, 1T-LSD) as narcotics, tightening the framework further.", mdma:"Scheduled narcotic, illegal and enforced. No approved MDMA-assisted therapy; clinical research only.", dmt:"DMT and ayahuasca are controlled narcotics; illegal and enforced. No religious/indigenous exemption in Sweden.", mes:"Mescaline (peyote/San Pedro) is a controlled narcotic; illegal. No religious exemption.", ket:"Ketamine is a narcotic but available medically: esketamine (Spravato) approved in the EU/Sweden since 2019 for treatment-resistant depression and recommended by the MPA as first-line; racemic ketamine also used off-label in several regions. Recreational use illegal.", ibo:"Ibogaine is illegal in Sweden (confirmed as of January 2024); controlled narcotic, no medical/therapeutic access.", coc:"Refined cocaine is a Schedule II narcotic; illegal and enforced (use, possession, sale all criminalised).", coca:"Coca leaf is treated as a controlled narcotic; illegal in Sweden with no traditional/cultural exemption." } },
  CH: { n:"Switzerland", def:'med', st:{ can:'decrim', cbd:'legal', dmt:'decrim', mes:'ill', ibo:'ill', coc:'ill', coca:'ill' }, nt:{ _:"Switzerland combines pragmatic decriminalization with a notable regulated-medical-access regime. Cannabis is decriminalized (<10g, CHF 100 fine for use) with large state adult-use pilots and a pending national legalization bill (2026). CBD <1% THC is fully legal. Crucially, psilocybin, LSD and MDMA are prohibited but legally accessible to patients via the FOPH 'limited medical use' authorization (Art. 8(5) Narcotics Act) - ~723 patients treated in 2024. Ketamine is a registered medicine. Ayahuasca enjoys religious-use allowance (UDV in Geneva). Mescaline, ibogaine, refined cocaine and coca leaf remain illegal and enforced.", can:"Illegal recreationally but decriminalized: possession <10g for personal use not punishable; consumption = CHF 100 fine. Large state-approved adult-use pilot programs (Zurich Zuri Can, Basel, Lausanne, Bern, Geneva). National legalization bill in consultation through 2025, expected before Parliament 2026.", cbd:"Legal since 2011: cannabis products with <1% THC are not narcotics. CBD flowers/oils/cosmetics sold openly; regulated by FOPH/Swissmedic. More permissive than EU's 0.3% limit.", psi:"Schedule 'd' prohibited, but accessible via FOPH 'limited medical use' program (Art. 8(5) Narcotics Act) for treatment-resistant patients. 348 patients treated with psilocybin in 2024 under ~100 authorized physicians.", lsd:"Prohibited but available via the same Art. 8(5) limited medical use program; 130 patients treated with LSD in 2024.", mdma:"Prohibited but available via the Art. 8(5) limited medical use program; 245 patients treated with MDMA in 2024 for trauma-related disorders.", dmt:"DMT prohibited, but ayahuasca religious use is allowed: Uniao do Vegetal granted right to import/use in Geneva; Narcotics Act does not mention ayahuasca and authorities indicate no permit needed to sell it. Legal status contested among judges/police.", mes:"Mescaline and mescaline-containing cacti/derivatives prohibited and enforced; no decriminalization.", ket:"Registered medicine (anaesthetic; also used off-label/privately for treatment-resistant depression). Recreational use illegal.", ibo:"Prohibited; no decriminalization. Only narrow compassionate-use/private-clinic exceptions.", coc:"Refined cocaine prohibited; possession for personal use remains criminalized (not decriminalized like cannabis). Supervised consumption rooms exist but cocaine itself is an enforced criminal offence.", coca:"Coca derivatives prohibited under the Narcotics Act; no traditional/indigenous-use exemption in Switzerland." } },
  SY: { n:"Syria", def:'ill', st:{ can:'cap', ket:'med' }, nt:{ _:"Syria maintains blanket drug prohibition under Law No. 2 of 1993 (Narcotic Drugs & Psychotropic Substances); Art. 39 allows the death penalty for trafficking/cultivation and up to 20 years for major offences. The law remains in force under the post-Assad al-Sharaa/HTS interim government, which since Dec 2024 has intensified (not relaxed) counter-narcotics enforcement against the Captagon trade. No medical, research, religious, or decriminalization carve-outs exist for any substance. Cannabis is explicitly capital-eligible (cap). CBD shares the cannabis prohibition (ill). All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, ibogaine) and cocaine/coca leaf are scheduled and illegal/enforced (ill) with no patient or researcher access. Ketamine is a registered hospital anaesthetic (med); recreational use illegal. Confidence medium: Syrian statutes rarely name individual psychedelics, and transition-era enforcement is uneven.", can:"Illegal for all uses under Law No. 2 of 1993 (Narcotic Drugs & Psychotropic Substances), Art. 39 — trafficking/cultivation can carry the death penalty; up to 20 yrs for major offences. No medical cannabis.", cbd:"No Western-style exemption — CBD falls under the same cannabis prohibition; illegal.", psi:"Scheduled psychotropic under Law No. 2/1993; no medical, research or religious access.", mdma:"Controlled psychotropic under the 1993 narcotics law; illegal and enforced.", ket:"WHO Essential Medicine; used as a hospital anaesthetic. Recreational use illegal.", coca:"No traditional use; treated as illegal narcotic material." } },
  TW: { n:"Taiwan", def:'ill', st:{ cbd:'med', ket:'med', coc:'cap' }, nt:{ _:"Taiwan controls drugs under the Narcotics Hazard Prevention Act (mirrored by the Controlled Drugs Act), with a four-tier schedule. Cocaine sits in Category 1 with heroin/opium, where trafficking can carry the death penalty or life imprisonment ('cap'). Cannabis, coca leaf, and all classic psychedelics (LSD, psilocybin, MDMA, DMT/ayahuasca, mescaline, ibogaine) are Category 2 narcotics — illegal and enforced, with no medical, research, religious, or decriminalization carve-outs ('ill'); cannabis trafficking can reach life imprisonment. Ketamine is a Category 3 registered anaesthetic (medical use legal, recreational illegal → 'med'). CBD is not a scheduled narcotic but no products are approved domestically; access is via TFDA import permit and prescription only ('med'). Verified against the official MOHW substance-by-substance schedule plus government and Wikipedia sources; placements are unambiguous, so confidence is high.", can:"Category 2 narcotic under the Narcotics Hazard Prevention Act; illegal for both recreational and medical use (no domestic medical-cannabis program). Use up to 3 yrs, possession up to 2 yrs, trafficking 7 yrs to life. Imported THC products (Epidiolex/Sativex) only via rare special TFDA approval.", cbd:"Not scheduled as a narcotic (treated as a 'general drug'), but no CBD medicines are approved in Taiwan. Personal import requires a physician prescription plus a TFDA import permit; unauthorized import can be prosecuted under the Pharmaceutical Affairs Act (up to 10 yrs). Hence regulated medical access only, not freely legal.", psi:"Schedule/Category 2 controlled narcotic (item 147 'Psilocybine'). No medical or research carve-out; trafficking up to life imprisonment.", lsd:"Schedule/Category 2 controlled narcotic (item 81, Lysergide). No therapeutic access.", mdma:"Schedule/Category 2 controlled narcotic (item 83). Common 'club drug'; no medical/research program.", dmt:"Schedule/Category 2 controlled narcotic (item 51 'Dimethyltryptamine, DMT'); ayahuasca has no religious-use exemption in Taiwan.", mes:"Schedule/Category 2 controlled narcotic (item 85 'Mescaline'); peyote/San Pedro covered, no indigenous-use exemption.", ket:"Category 3 narcotic; registered medicine/anaesthetic since 2002. Recreational use/possession <20g treated as administrative (mandatory drug-hazard seminar); >=20g criminal. Medical use legal under control.", ibo:"Schedule/Category 2 controlled narcotic (item 74 'Ibogaine'). No medical/research access.", coc:"Category 1 narcotic alongside heroin/morphine/opium. Manufacture/transport/sale can carry the death penalty or life imprisonment; airport signage warns trafficking is punishable by death.", coca:"Coca is explicitly listed in Category 2 of Taiwan's narcotics schedule. No traditional/Andean-use exemption; illegal and enforced (distinct from refined cocaine in Category 1)." } },
  TJ: { n:"Tajikistan", def:'cap', st:{ cbd:'ill', ket:'med', ibo:'ill' }, nt:{ _:"Tajikistan operates a strict UN-Convention-aligned prohibition regime (National List of narcotics, psychotropics & precursors, last updated 27 Feb 2020). All classic controlled substances (cannabis, psilocybin, LSD, MDMA, DMT, mescaline, cocaine, coca leaf) are scheduled, illegal, and enforced, with no medical-cannabis program, no CBD/hemp carve-out, and no religious/indigenous psychedelic exemptions. Tajikistan is the only Central Asian state that retains the death penalty for ordinary crimes including large-scale drug trafficking and cultivation; a moratorium on executions has held since 2004 (no executions since) but capital punishment remains de jure on the books, is unabolished, and lifting the moratorium was again debated by officials in 2024 — hence 'cap' for the trafficking-scale narcotics. Ketamine is a registered medicine ('med'); recreational use illegal. Ibogaine is not specifically listed but has no legal access route. Coded 'cap' for substances whose large-scale trafficking realistically triggers the capital provisions; CBD/ibogaine coded 'ill' as the conservative consumer-level status. Confidence medium: the capital-punishment law is substance-agnostic (quantity/scale-based) and unenforced for 20+ years, and the full current national schedule was not read line-by-line.", can:"Fully illegal, no medical/CBD carve-out. Large-scale cultivation/trafficking of cannabis can carry the death penalty under the Criminal Code (commutable to 25 yrs); possession up to 5 yrs.", cbd:"No legal distinction from cannabis (no THC threshold recognized); illegal in practice, though realistically not a capital matter at consumer quantities.", psi:"Scheduled under UN-1971-aligned national list; no medical/religious access.", lsd:"Scheduled; trafficking falls under the general narcotics death-penalty provision.", mdma:"Scheduled and seized in quantity; large-scale trafficking falls under capital provisions.", dmt:"Controlled under national list; no ayahuasca religious/indigenous exemption.", mes:"Controlled under national list; no peyote/San Pedro traditional-use exemption (not native to region).", ket:"Registered medicine (clinical/veterinary) under UN-aligned national list; recreational use illegal.", ibo:"Not specifically scheduled but no medical/research access; treated as an unauthorized narcotic — illegal.", coc:"Refined cocaine controlled and actively interdicted; large-scale trafficking falls under capital provisions.", coca:"Coca leaf controlled; no traditional use in Central Asia; illegal." } },
  TH: { n:"Thailand", def:'ill', st:{ can:'med', cbd:'legal', ket:'med' }, nt:{ _:"Thailand 2026: Cannabis recriminalized in mid-2025 from recreational to medical-only (prescription required); CBD <0.2% THC stays legal. Ketamine is a registered Category 2 medicine. Psilocybin sits in a narrow new lane — a 23 Apr 2024 notification permits it (Category 5) for FDA-approved treatment/research while the Thai FDA still warns the public it is illegal, so I coded it 'med' at medium confidence. LSD, MDMA, DMT/ayahuasca, mescaline are Category 1 with no medical pathway (illegal/enforced; some tourist-area tolerance for ayahuasca). Cocaine is Category 2 and illegal; coca leaf has no recognized status. Ibogaine is not explicitly scheduled in available sources and not available to patients (coded ill, low confidence on mechanism). Overarching caveat: Thailand retains the death penalty for serious trafficking (de-facto moratorium, but death sentences still issued).", can:"Recreational legalization (June 2022) REVERSED June 25-26 2025. Now medical-only: cannabis flower is a 'controlled herb' requiring a Thai doctor's prescription (insomnia, chronic pain, migraine, Parkinson's, loss of appetite; max 30-day scripts). Recreational sale/possession re-criminalized.", cbd:"Legal if <0.2% THC and FDA-registered; sold without prescription for food/cosmetic/health use. Survived the June 2025 crackdown.", psi:"Category 5 narcotic. Ministerial Notification effective 23 Apr 2024 permits psilocybin (Psilocybe cubensis) for treatment of disease/research with FDA-approved formulations (no imports); Khon Kaen University trials underway. Recreational use remains a criminal offence and Thai FDA publicly warns it is illegal — real-world access is very narrow.", lsd:"Category 1 narcotic (most restrictive, with heroin); no medical/research pathway.", mdma:"Category 1 narcotic; no medical/research pathway. 2017 amendment lowered some possession penalties but it remains illegal and enforced.", dmt:"Category 1 psychotropic ('no medical use'); ayahuasca illegal. Underground ceremonies in tourist areas (Koh Phangan, Pai) are de-facto tolerated but have no legal protection.", mes:"Category 1 psychotropic ('no medical use'); peyote/San Pedro not legally available.", ket:"Schedule/Category 2 psychotropic substance — registered anaesthetic medicine; legitimate clinical use, but recreational use/unauthorized possession illegal.", ibo:"No explicit Thai scheduling found in sources; not a registered medicine and not legally available to patients — treated as a controlled narcotic/psychotropic by default. Classification uncertain (low confidence).", coc:"Category 2 narcotic. Possession/supply illegal and enforced (up to life imprisonment); large-scale trafficking can attract the death penalty under the Narcotics Code (de-facto execution moratorium, but death sentences still handed down, e.g. heroin case Mar 2025).", coca:"Raw coca leaf not separately recognized; no traditional/legal use in Thailand. Falls under narcotic controls and is illegal." } },
  BS: { n:"The Bahamas", def:'ill', st:{ psi:'legal', dmt:'decrim', ket:'med', ibo:'legal' }, nt:{ _:"The Bahamas: Cannabis Act 2024 enacted but only partially commenced — recreational cannabis remains illegal/enforced (ill) and CBD has no operational legal access; medical/religious cannabis and the <=30g $250 decrim framework are on the books but not yet in force as of mid-2026. Classic synthetics LSD, MDMA, refined cocaine and coca leaf are illegal and enforced under the Dangerous Drugs Act. Notably permissive: psilocybin mushrooms and ibogaine are NOT scheduled (legal — open mushroom retreats and licensed ibogaine clinics); DMT/ayahuasca is unlisted/de-facto tolerated (decrim). Ketamine = registered medicine (med). Death penalty applies only to murder/treason, NOT drug offences, so no 'cap'. Mescaline status undocumented — conservatively 'ill' (low confidence).", can:"Cannabis Act 2024 passed (medical + Rastafarian religious use, $250 fixed-penalty for <=30g, licensing/Cannabis Authority) but key decriminalization & licensing provisions are NOT yet in force as of mid-2026 — commencement orders pending, no dispensaries, possession arrests continued through 2025 under the Dangerous Drugs Act. Recreational still illegal/enforced; medical & religious authorized on paper but not operational.", cbd:"No separate CBD statute; falls under the Cannabis Act 2024 framework which is not yet operational. No legal retail/medical CBD access in practice — Dangerous Drugs Act still governs. Status uncertain (low confidence).", psi:"Psilocybin mushrooms are NOT listed in the Dangerous Drugs Act; possession, cultivation and transport effectively legal (sale is a gray area). Bahamas is a noted destination for legal mushroom retreats.", dmt:"DMT/ayahuasca not explicitly listed in the Dangerous Drugs Act; ayahuasca retreat centres reportedly operate — de facto unscheduled/tolerated.", ket:"Ketamine is a registered anaesthetic (medical use); recreational use illegal.", ibo:"Ibogaine is NOT classified as a dangerous/illegal drug; licensed ibogaine addiction-treatment clinics (e.g. Oceanside, Nassau, since 2014) operate openly — Bahamas is a recognised medical-ibogaine hub.", coc:"Refined cocaine illegal and enforced under the Dangerous Drugs Act; trafficking carries long sentences (up to ~40 years) but NOT the death penalty (capital punishment reserved for murder/treason).", coca:"Coca leaves are explicitly named as a controlled substance in the Dangerous Drugs Act — illegal." } },
  TG: { n:"Togo", def:'ill', st:{ ket:'med' }, nt:{ _:"Togo prohibits and enforces against all listed substances except ketamine, which is a registered medicine (recreational use illegal). Cannabis and CBD are illegal since 1955 with substantial prison terms and a reputation for strict enforcement, especially of foreigners; there is no medical/industrial cannabis program and no medical or research framework for psychedelics. Classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) and ibogaine fall under Togo's narcotic/psychotropic control (Togo acceded to the 1961 Single Convention in 1963) with no religious, indigenous, or research carve-outs. Refined cocaine and raw coca leaf are both treated as prohibited narcotics (no Andean-style traditional-use exemption in West Africa). 'cap' is ruled out: Togo abolished the death penalty for all crimes in 2009. Confidence is medium — cannabis/CBD are well documented, while the psychedelics and coca/cocaine classifications are inferred from convention adherence and the absence of any reform or carve-out rather than Togo-specific substance scheduling pages (Psychedelic Alpha does not list Togo).", can:"Illegal and enforced since 1955. Drug Control Law: up to ~10 yrs for cultivation/trafficking, up to ~5 yrs for possession/use; known for harsh enforcement, esp. against foreigners. No medical or industrial program.", cbd:"No legal distinction from cannabis; CBD and other cannabis derivatives explicitly prohibited. Possession can carry a minimum ~6 months imprisonment plus fines.", dmt:"No religious/indigenous ayahuasca exemption; controlled under 1961/1971 convention framework (Togo acceded 1963).", ket:"Registered medicine (hospital/anaesthetic use) as in most countries; recreational/non-medical use prohibited as a controlled psychotropic.", coca:"No traditional/indigenous use in West Africa; coca leaf treated as a prohibited narcotic alongside cocaine." } },
  TT: { n:"Trinidad and Tobago", def:'ill', st:{ can:'decrim', ket:'med' }, nt:{ _:"Trinidad and Tobago decriminalized small-quantity cannabis (<=30g, up to 4 plants/adult) in Dec 2019 but has NOT legalized recreational or medical cannabis; the medical Cannabis Licensing Authority framework is legislated but not yet operational as of 2026, leaving CBD without a clear legal carve-out. All classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) and cocaine/coca leaf are controlled under the Dangerous Drugs Act Chap 11:25, illegal and enforced. Ketamine is available as a registered medicine (med). Drug trafficking carries a mandatory 25-year + TT$100k penalty, but the death penalty applies only to murder, not drug offences - so no substance rated 'cap'. Ibogaine is not addressed in statute and has no legal access (conservatively 'ill', low confidence).", can:"Decriminalized since 23 Dec 2019 (Dangerous Drugs Amendment): possession up to 30g cannabis / 5g resin and cultivation of up to 4 plants per adult are non-criminal; 30-60g carries a fixed fine. Recreational sale and use still prohibited; no commercial market.", cbd:"No statutory distinction between CBD and other cannabis products; the medical-cannabis/Cannabis Control framework (Cannabis Licensing Authority) is legislated but not yet proclaimed/operational as of 2026, so CBD has no clear legal carve-out. Status ambiguous - treated conservatively as prohibited.", psi:"Psilocybin explicitly listed as a controlled substance under the Dangerous Drugs Act Chap 11:25; no decrim or therapeutic access (unlike neighbouring Jamaica/Bahamas).", lsd:"Controlled under the Dangerous Drugs Act; the 2019 amendment specifically set possession/trafficking penalties for LSD.", mdma:"Controlled under the Dangerous Drugs Act; 2019 amendment added MDMA and new psychoactive substances with possession/trafficking penalties.", dmt:"DMT/ayahuasca controlled under the Dangerous Drugs Act; no religious or indigenous exemption identified.", mes:"Mescaline controlled under the Dangerous Drugs Act; no peyote/San Pedro carve-out.", ket:"Scheduled in the Dangerous Drugs Act with a possession threshold deeming larger amounts as trafficking; available as a registered/clinical anaesthetic medicine, recreational use illegal.", ibo:"No explicit listing or legal access framework identified in T&T law; not a registered medicine and no therapy clinics - treated conservatively as not legally available (low confidence).", coc:"Illegal and enforced; possession-for-trafficking carries a mandatory minimum fine of TT$100,000 and 25 years imprisonment. Death penalty is retained only for murder, not drug offences (last execution 1999).", coca:"No Andean traditional-use exemption; raw coca leaf falls under the cocaine/Dangerous Drugs prohibition and is illegal." } },
  TN: { n:"Tunisia", def:'ill', st:{ ket:'med' }, nt:{ _:"Tunisia operates a strict blanket drug-prohibition regime under Law 92-52 (1992, 'Law 52'). All recreational and psychedelic substances (cannabis, CBD, psilocybin, LSD, MDMA, DMT, mescaline, ibogaine, cocaine, coca leaf) are illegal and enforced as criminal offences, with mandatory prison terms (1-5 yrs for personal use, up to life for trafficking). A 2017 reform added limited judicial discretion but did not decriminalize; drug arrests still fill prisons (10,000+ inmates, ~70% cannabis). No medical/research/religious carve-outs exist for psychedelics; CBD is not distinguished from cannabis. Ketamine is available as a registered hospital anaesthetic (med), with non-medical use prohibited. Maximum penalty is life imprisonment, not death, so 'cap' is not assigned. Substance-specific Tunisian sources exist for cannabis/CBD; psychedelics and ketamine status is inferred from the blanket law plus Tunisia's adherence to the UN 1961/1971 conventions.", can:"Illegal and heavily enforced under Law 92-52 ('Law 52', 1992). Personal use carries mandatory 1-5 yrs; ~70% of 10,000+ drug prisoners (late 2025) jailed for cannabis ('zatla'). 2017 amendment added limited judicial discretion but did not decriminalize.", cbd:"No legal distinction between cannabis and CBD; CBD products are illegal and treated like cannabis. No industrial-hemp framework.", ket:"Registered anaesthetic medicine in hospital use (med); recreational use prohibited under narcotics law.", coc:"Illegal; trafficking heavily prosecuted (10 yrs to life for import/export). Recent 30-year sentences for trafficking rings.", coca:"No traditional use; falls under blanket narcotics prohibition, illegal." } },
  TR: { n:"Turkey", def:'ill', st:{ cbd:'med', ket:'med' }, nt:{ _:"Turkey is a strict prohibition country and party to the UN drug conventions. Classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline), cocaine, and coca leaf are illegal and enforced under Turkish Penal Code Art. 188 (trafficking, 20-30 yrs) and Art. 191 (personal use, with rehabilitative diversion for first offenders). The death penalty was fully abolished in 2004, so no capital code despite severe sentences. Recreational cannabis is illegal. CBD and broader cannabis-derived products are accessible only medically: Sativex has long been prescribable, and July 2025 Law No. 7557 legalized prescription sale of low-THC (<0.3%) medical cannabis products through licensed pharmacies. Ketamine is a registered prescription medicine (recreational use illegal). Ibogaine has no approved/medical status and is treated as a prohibited substance. No religious or indigenous exemptions exist for DMT/mescaline. Confidence medium: cannabis/CBD reform well-documented for 2025, but exact scheduling of individual psychedelics and ibogaine is inferred from Turkey's blanket controlled-substance regime rather than a substance-by-substance government list.", can:"Recreational cannabis illegal and enforced under TPC Art. 188/191. Cultivation tightly state-controlled.", cbd:"Medical CBD by prescription (Sativex long available); July 2025 Law No. 7557 expanded medical cannabis products (<0.3% THC) sold in pharmacies by prescription, jointly overseen by Health + Agriculture ministries. Non-medical CBD remains illegal.", mdma:"Illegal controlled substance under 1971 Convention; no therapeutic access.", dmt:"DMT/ayahuasca illegal; no religious/indigenous exemption in Turkey.", ket:"Registered medicine/anaesthetic, prescription-controlled; recreational use illegal.", coc:"Refined cocaine is an 'aggravated' substance under TPC Art. 188 (penalty +50%); illegal and strongly enforced. Death penalty abolished (2004), so no capital punishment, but trafficking carries 20-30 yrs.", coca:"Coca leaf illegal; no traditional/permitted use." } },
  TM: { n:"Turkmenistan", def:'ill', st:{ ket:'med' }, nt:{ _:"Turkmenistan enforces a strict zero-tolerance drug policy under its Criminal Code with no medical-cannabis, decriminalization, or psychedelic-research framework. All listed substances are illegal and enforced (ill), except ketamine which is treated as a registered medicine (med) per UN psychotropic conventions, with recreational use illegal. Cannabis: personal use up to 5 years, trafficking 3-20 years plus confiscation; CBD not legal. The death penalty was abolished (1999 decree, 2003 Constitution), so no offence is capital today, though trafficking carries severe sentences up to life with amnesty barred. Individual psychedelics (psilocybin, LSD, MDMA, DMT, mescaline, ibogaine) and coca/cocaine are not separately documented for Turkmenistan but fall under the blanket prohibition as a UN-convention state party; these are inferred, hence medium confidence overall.", can:"Illegal, zero-tolerance Criminal Code (1997, amended 2015). Personal use up to 5 yrs; trafficking 3-10 yrs, 12-20 yrs aggravated + property confiscation. No medical/recreational program.", cbd:"No legal CBD/hemp carve-out; treated as cannabis under blanket prohibition.", psi:"No substance-specific TM data; prohibited under blanket zero-tolerance regime as UN-convention Schedule I hallucinogen. No medical/research/religious exemption.", mdma:"Prohibited under blanket zero-tolerance regime; no clinical/research access. Death penalty abolished, so not capital.", ket:"No TM-specific listing found; treated as registered medicine per UN psychotropic conventions (Law 238-II/2004). Recreational use illegal. Inferred (medium confidence).", coc:"Refined cocaine prohibited and enforced as a narcotic; severe trafficking sentences (up to life, amnesty barred). Death penalty abolished 1999/2003 so not capital.", coca:"No traditional coca use; prohibited as a narcotic." } },
  UG: { n:"Uganda", def:'ill', st:{ ket:'med' }, nt:{ _:"Uganda prohibits all listed substances except ketamine (a registered NDA-controlled medicine) and licensed medical/scientific cannabis cultivation-and-export. The governing law is the Narcotic Drugs and Psychotropic Substances (Control) Act, 2024 (Act No. 2/2024), signed by President Museveni on 2 Feb 2024, replacing the 2016 Act that the Constitutional Court nullified on procedural grounds in 2023. Recreational cannabis and all classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline), ibogaine, cocaine and coca leaf are criminally prohibited with no decriminalization or religious/research exemptions. Penalties are harsh — possession of illegal drugs draws 15+ years (reported up to 10–25 years) and trafficking/supply can carry life imprisonment — but the law does NOT impose the death penalty for drug offences (capped at life), so 'cap' is not assigned. Medical cannabis is licensed but export-oriented with minimal domestic patient access; an experimental cultivation licence was granted to Bright Sparks Farm in July 2025.", can:"Recreational cannabis is a criminal offence. However, cultivation/processing/export for medical and scientific use is legal under strict Ministry of Health/NDA licence (Act of 2024); experimental cultivation licence granted to Bright Sparks Farm in July 2025. No domestic patient-access market exists yet — primarily export-oriented.", cbd:"No separate CBD framework. CBD from cannabis falls under the controlled-cannabis regime; accessible only via the medical-cannabis licensing scheme, not as an OTC/wellness product.", psi:"Schedule I psychotropic (UN 1971 Convention), prohibited and criminally enforced. No decrim, no religious/research exemption.", mdma:"Prohibited Schedule I psychotropic; criminally enforced. Possession carries long prison terms.", dmt:"DMT prohibited; no ayahuasca religious/indigenous exemption (not a native Ugandan tradition).", ket:"Registered medicine via the National Drug Authority (controlled prescription medicine, essential anaesthetic). Recreational/non-medical use illegal.", ibo:"No registered medical use; iboga/ibogaine not native to Uganda and not part of an approved program. Falls under controlled-substances prohibition.", coc:"Refined cocaine is an illegal narcotic, actively enforced (Uganda is a known transit country). Trafficking/supply can carry life imprisonment.", coca:"Coca leaf not native, no traditional use; controlled as a prohibited narcotic." } },
  UA: { n:"Ukraine", def:'ill', st:{ can:'med', cbd:'legal', ket:'med' }, nt:{ _:"Ukraine: recreational cannabis illegal but medical cannabis legalized (law effective Aug 2024, products dispensed 2025); CBD isolate from hemp effectively legal. Classic psychedelics (psilocybin, LSD, MDMA, DMT, ibogaine) remain illegal Schedule-1-equivalent substances - a 2025 MoH proposal to reschedule them for scientific/research use is still NOT enacted as of mid-2026, so legal research access does not yet exist; mescaline isn't even in that proposal. Ketamine is a registered medicine (med). Refined cocaine and coca leaf illegal. Private use and small-quantity possession are decriminalized (administrative penalty), but trafficking/larger amounts are criminal (up to 3 yrs); no death penalty.", can:"Recreational cannabis illegal & enforced. Medical cannabis legalized via 'Cannabis Law' effective 16 Aug 2024; first products (Curaleaf full-spectrum oils) added to State Register Jan 2025 and dispensed to veterans/patients in 2025. Possession of small amounts is an administrative offence; larger amounts criminal (up to 3 yrs).", cbd:"CBD isolate from industrial hemp (<=0.08% THC) is excluded from the controlled-substances list and effectively legal; non-medical CBD product market expanding under 2024-25 hemp rules.", psi:"Schedule-equivalent psychotropic, illegal. MoH proposed rescheduling psilocybin/psilocin for scientific & educational use (draft published 2025) but as of May 2026 it remains a proposal, NOT enacted - legal research not yet possible.", lsd:"Illegal (most restrictive list). Included in the 2025 research-rescheduling proposal but not yet approved as of 2026.", mdma:"Illegal. MDMA-assisted therapy for veterans advocated (MAPS trained 55 therapists); included in 2025 rescheduling proposal but not enacted as of mid-2026.", dmt:"DMT/5-MeO-DMT illegal; in 2025 research proposal but not in force. Ayahuasca not specifically permitted.", mes:"Illegal; notably NOT included in the 2025 psychedelic research-rescheduling proposal.", ket:"Registered medicine; legal for medical/surgical/pain use by prescription. Recreational use illegal.", ibo:"Illegal; included in 2025 research-rescheduling proposal but not yet enacted.", coca:"No traditional/indigenous use; treated as a narcotic - illegal." } },
  AE: { n:"United Arab Emirates", def:'ill', st:{ can:'cap', cbd:'med', mdma:'cap', ket:'med', coc:'cap' }, nt:{ _:"UAE operates a zero-tolerance narcotics regime under Federal Decree-Law No. 30/2021, which schedules all listed substances; trafficking can carry the death penalty (cap applied to cannabis, MDMA, cocaine as the principal trafficking-relevant drugs). 2022 reforms and Cabinet Decision No. 43/2024 reduced first-time personal-use penalties (fines/short jail; confiscation for travellers) but did NOT decriminalise any substance. Classic psychedelics (psilocybin, LSD, DMT/ayahuasca, mescaline) and ibogaine remain scheduled criminal offences (ill). Ketamine is a prescription-only controlled medicine (med). The major recent reform: Federal Decree-Law No. 24/2025 (Dec 2025) legalised industrial hemp / CBD for medical and industrial use (<=0.3% THC, licensed), giving CBD a med status, while recreational cannabis and CBD in food/supplements/smoking products stay banned. Coca leaf has no traditional-use exemption (ill).", can:"Illegal & strictly enforced under Federal Decree-Law No. 30/2021; trafficking/promotion can carry the death penalty. 2022 reforms + Cabinet Decision 43/2024 cut first-time personal-use penalties (min 3-month jail or fines; confiscation possible for travellers) but cannabis remains fully prohibited.", cbd:"Federal Decree-Law No. 24/2025 (Dec 2025) legalised industrial hemp/CBD for the first time for MEDICAL products (and industrial uses), capped at <=0.3% THC, licensed/regulated. Recreational use, food, dietary supplements, smoking & most cosmetic products still banned.", psi:"Scheduled prohibited substance under Federal Decree-Law No. 30/2021; criminal offence, strictly enforced (no medical/religious exemption).", lsd:"Scheduled prohibited psychotropic under Federal Decree-Law No. 30/2021; criminal offence, zero-tolerance enforcement.", mdma:"Illegal scheduled psychotropic; trafficking can carry the death penalty under Federal Decree-Law No. 30/2021. Possession is a criminal offence even in trace amounts.", dmt:"Ayahuasca/DMT scheduled and prohibited under Federal Decree-Law No. 30/2021; criminal offence, no religious-use exemption.", mes:"Mescaline (peyote/San Pedro) scheduled and prohibited; criminal offence.", ket:"Registered controlled medicine (Psychotropic Schedule II); legal by prescription/attested medical report, max ~3 months' supply for travellers. Recreational use illegal.", ibo:"Ibogaine scheduled/prohibited; no approved therapeutic access. Criminal offence.", coc:"Illegal & strictly enforced; trafficking can carry the death penalty under Federal Decree-Law No. 30/2021.", coca:"Coca leaf scheduled and prohibited; no traditional-use exemption in the UAE. Criminal offence." } },
  GB: { n:"United Kingdom", def:'ill', st:{ can:'med', cbd:'legal', ket:'med' }, nt:{ _:"UK (MoDA 1971 + MoDR 2001) maintains strict prohibition. Classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline) and cocaine/coca leaf are all Class A / Schedule 1 (coca leaf Sch 1; cocaine Sch 2), illegal and enforced. Cannabis is Class B: recreational illegal, but medical cannabis has been legal since Nov 2018 via specialist prescription (NHS access minimal, mostly private). Ketamine is Class B and a registered medicine; an ACMD review published Jan 2026 recommended it stay Class B rather than be upgraded to Class A. CBD is not controlled and is sold legally as an FSA-regulated Novel Food (THC <=1mg/container). Ibogaine is not in MoDA but its supply/import is banned under the Psychoactive Substances Act 2016. No death penalty; max penalties are 7 years (Class A possession) to life (Class A supply).", can:"Class B, MoDA 1971. Recreational illegal/enforced. Medical cannabis legal since Nov 2018 but only via specialist (mostly private) prescription; NHS access extremely rare.", cbd:"Not controlled. Regulated as Novel Food/food supplement by FSA; legally sold if THC <=1mg per container and a valid Novel Food application is on file.", psi:"Class A, Schedule 1 (fresh and prepared mushrooms). Research only under Home Office licence.", mdma:"Class A, Schedule 1.", dmt:"Class A, Schedule 1. Ayahuasca treated as a DMT preparation; no religious exemption recognised (R v Aziz 2012); UK's first ayahuasca supply conviction secured.", mes:"Class A, Schedule 1 (mescaline; peyote/San Pedro preparations).", ket:"Class B (recreational illegal). Registered anaesthetic/medicine. ACMD review published Jan 2026 recommended ketamine REMAIN Class B, rejecting a proposed upgrade to Class A.", ibo:"Not scheduled under MoDA, but production/supply/import caught by the Psychoactive Substances Act 2016. Simple possession not itself an offence, but no legal route to obtain it.", coc:"Class A, Schedule 2.", coca:"Coca leaf is a Schedule 1 controlled drug, prohibited (listed alongside cocaine/LSD/ecstasy); no traditional-use exemption." } },
  TZ: { n:"United Republic of Tanzania", def:'ill', st:{ ket:'med' }, nt:{ _:"Tanzania prohibits essentially all listed psychoactive substances under the Drug Control and Enforcement Act 2015, with no medical-cannabis or psychedelic-therapy programs and active, harsh enforcement (cultivation min. 30 years; trafficking can reach mandatory life). Cannabis and CBD are treated identically with no hemp exemption. Classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline) are prohibited psychotropics; cocaine and coca leaf are illegal. Ketamine is the lone exception as a TMDA-regulated anaesthetic medicine (recreational use illegal). Capital punishment exists in Tanzania but applies only to murder and treason, NOT drug offences, so no 'cap' classification despite very long sentences.", can:"Completely illegal under the Drug Control and Enforcement Act 2015; no medical cannabis program. Penalties among the harshest in the world: cultivation not less than 30 years; trafficking >50kg mandatory life imprisonment. Tanzania is a major illicit producer with active enforcement.", cbd:"No legal distinction from cannabis; the Act has no hemp/low-THC exemption. CBD oil illegal to possess, sell or import even with a foreign prescription.", ket:"Registered anaesthetic medicine regulated by TMDA (controlled drug requiring consumption reporting); essential for anaesthesia care in Tanzania. Recreational/non-medical use illegal.", ibo:"No medical or research framework and no legal access; not separately named in UN schedules but no permissive pathway exists (lower confidence on exact statutory listing).", coc:"Illegal and enforced; Tanzania is a significant transit corridor for South American cocaine. No death penalty for drug offences (capital punishment reserved for murder/treason), but severe prison terms.", coca:"No traditional/indigenous coca use; prohibited as a narcotic, illegal." } },
  US: { n:"United States", def:'ill', st:{ can:'med', cbd:'legal', psi:'med', dmt:'decrim', ket:'med' }, nt:{ _:"United States, 2026: Federal law keeps most of these substances in Schedule I/II, but real-world access diverges sharply by state and by exemption. Cannabis and hemp-CBD are effectively legal/regulated across much of the country (24 states + DC recreational; medical cannabis moved to Schedule III in April 2026). Psilocybin has genuine regulated/therapeutic access (Oregon, Colorado). LSD, MDMA and ibogaine are Schedule I but accessible via research/clinical trials (LSD and ibogaine now with strong federal/state research momentum). Ayahuasca/DMT and peyote/mescaline have religious/conditional carve-outs (RFRA/NAC exemptions, Colorado decrim). Ketamine is an approved Schedule III medicine. Refined cocaine and coca leaf remain criminalized for general use (cocaine has narrow Schedule II medical use; coca-leaf import is banned).", can:"Federally illegal (Schedule I) but as of March 2026, 24 states + DC have legal recreational use and 40 states medical; April 2026 DOJ order reclassified FDA-approved & state-licensed MEDICAL cannabis to Schedule III, with a broader rescheduling hearing set for June 29, 2026. Recreational still federally prohibited but state-legal markets largely unenforced.", cbd:"Hemp-derived CBD (<0.3% THC) removed from Controlled Substances Act by the 2018 Farm Bill; legal and broadly available. Purified CBD (Epidiolex) FDA-approved for certain seizure disorders since 2018.", psi:"Schedule I federally, but real regulated/therapeutic access exists: Oregon (Measure 109, 100+ licensed service centers) and Colorado (Prop 122, decriminalized + first licensed healing centers opened April 2025). Several cities decriminalized.", lsd:"Schedule I, no approved medical use, but FDA granted Breakthrough Therapy designation for LSD (generalized anxiety disorder) on 25 May 2026; clinical-trial/research access only.", mdma:"Schedule I; FDA rejected Lykos' MDMA-assisted therapy NDA in Aug 2024 (CRL released Sept 2025). Not approved; access limited to research/clinical trials and an additional Phase 3 is being pursued.", dmt:"Schedule I, but ayahuasca (DMT) permitted for religious use under federal RFRA/DEA exemptions for the UDV, Santo Daime, Iowaska Church of Healing and Church of Gaia (first non-litigated DEA exemption granted 2025); also decriminalized in Colorado.", mes:"Schedule I; long-standing federal Native American Church exemption for peyote (members of federally recognized tribes); Colorado decriminalized mescaline (excluding peyote) under Prop 122. San Pedro/synthetic mescaline otherwise illegal.", ket:"Schedule III, FDA-approved as an anesthetic and (as esketamine/Spravato) for treatment-resistant depression; widely used medically incl. off-label IV/clinics. Recreational use illegal.", ibo:"Schedule I, not FDA-approved, but Texas appropriated up to $100M for FDA-supervised clinical trials (SB 2308, 2025; UTHealth/UTMB awarded Dec 2025); IND-authorized human research underway. Access is research-only.", coc:"Schedule II; tightly restricted medical use as a topical/local anesthetic, but recreational possession/supply is a criminal offence that is actively enforced.", coca:"Coca leaf is a Schedule II narcotic; importation into the US is prohibited by CBP/FDA (only decocainized coca products permitted, e.g. for Coca-Cola flavoring). No legal traditional/personal use." } },
  UY: { n:"Uruguay", def:'decrim', st:{ can:'legal', cbd:'legal', ket:'med' }, nt:{ _:"Uruguay has two overlapping regimes. Cannabis is fully legal & state-regulated (Law 19.172, 2013/14): recreational for registered residents 18+ via pharmacies, home grow & social clubs, plus regulated medical cannabis and OTC low-THC CBD. For all other drugs, Uruguay never criminalized personal possession/consumption (Law 14.294, 1974): use is not punished but there is no legal supply and trafficking/sale is an enforced crime, with no statutory quantity threshold (judicial discretion). Hence psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline, refined cocaine and coca leaf are coded decrim (personal use not punished). Ayahuasca additionally enjoys religious-freedom tolerance (Santo Daime). Ketamine is a registered medicine (med). Ibogaine: personal use not punished and reportedly permitted clinically, coded decrim conservatively. A 2023 National Party bill to legalize psychedelics has not passed.", can:"Fully legal & state-regulated since Law 19.172 (2013/14): recreational access for registered residents 18+ via pharmacies, home grow & Cannabis Social Clubs; sales rising (4,290 kg in 2025). Medical cannabis regulated by IRCCA.", cbd:"Legal; low-THC (<1%) hemp/CBD products sold over-the-counter without prescription (one of only ~2 countries with OTC CBD). Medical CBD (e.g. Epifractan) also prescribed.", psi:"Controlled substance; trafficking/sale criminal & enforced, but personal possession & consumption never criminalized (Law 14.294/1974, as amended). No statutory quantity threshold — personal-use vs trafficking left to judicial discretion; no legal supply.", lsd:"Controlled; personal consumption/possession not punished (1974 framework), but production/sale/trafficking criminal. No legal supply.", mdma:"Controlled; personal consumption/possession not punished, trafficking criminal. 2023 National Party bill to legalize psychedelics filed but not passed.", dmt:"DMT controlled but ayahuasca brew in legal grey zone; personal use not punished. Religious-freedom tolerance for Santo Daime (Céu de Luz, Art. 5 constitution); state does not treat ayahuasca as a public-health threat.", mes:"Controlled; personal use/possession not punished, trafficking criminal. No Andean indigenous-use tradition; no approved supply.", ket:"Registered medicine for clinical/anaesthetic use; recreational/non-medical use not permitted.", ibo:"Personal possession/consumption not punished under 1974 framework; some sources list ibogaine as legal/permitted in clinical settings. Conservatively coded decrim — no formally approved therapy/supply.", coc:"Refined cocaine is a controlled substance; trafficking/sale criminal & enforced. Personal possession/consumption de jure not punished (no quantity threshold; judicial discretion).", coca:"No Andean traditional/legal status in Uruguay; personal possession not punished under general 1974 personal-use framework, but no legal commercial supply." } },
  UZ: { n:"Uzbekistan", def:'ill', st:{ ket:'med' }, nt:{ _:"Uzbekistan runs a strict, comprehensively prohibitive drug regime under Cabinet of Ministers Decree No.330 (2015), with substances split into List I (forbidden traffic) and Lists II/III (limited traffic, allowed for medical use). Cannabis and CBD are illegal with no medical program (consumer CBD = cannabis; only industrial hemp <0.2% THC is licensed since 2020). All classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline) plus cocaine and coca leaf are on List I and enforced. Ketamine is a List III controlled medicine (med). Ibogaine has no medical pathway and is treated as prohibited (lower confidence). The death penalty was abolished in 2008, so despite very long sentences and a June 2026 law toughening penalties, no substance warrants 'cap'.", can:"Illegal recreational and medical; no medical-cannabis program. Possession up to ~5 yrs, large-scale 10-20 yrs. Industrial hemp <0.2% THC licensed since March 2020 but consumer products banned.", cbd:"Law makes no distinction between CBD and cannabis; CBD treated as illegal cannabis. No legal consumer CBD market.", psi:"Psilocybin/psilocin on List I (forbidden traffic), Decree No.330/2015. No therapeutic or religious exemption.", lsd:"Listed (d-Lysergide) on List I, forbidden traffic. No research/therapy carve-out.", mdma:"On List I, forbidden traffic.", dmt:"DMT/ayahuasca constituents on List I, forbidden traffic; no ayahuasca religious exemption.", mes:"Mescaline on List I, forbidden traffic; peyote/San Pedro not exempt.", ket:"On List III (psychotropic substances, limited traffic) — controlled but permitted as a registered medicine; recreational use illegal.", ibo:"No specific listing or medical-access pathway found; treated as prohibited under comprehensive zero-tolerance regime. Lower confidence.", coc:"Refined cocaine prohibited under List I.", coca:"Coca bush, coca leaf and ecgonine explicitly on List I (forbidden traffic) — no traditional/Andean exemption (non-producing country). NOTE: death penalty for drug offences ABOLISHED 2008; harsh sentences (to 20 yrs) and a June 2026 law toughening penalties exist, but no capital punishment, so 'cap' not assigned." } },
  VU: { n:"Vanuatu", def:'ill', st:{ ket:'med', ibo:'nodata' }, nt:{ _:"Vanuatu prohibits essentially all listed substances under the Dangerous Drugs Act (CAP 12), which bans cannabis, cocaine and UN-scheduled psychotropics (LSD, MDMA, psilocybin, mescaline, DMT) — all 'ill' and enforced. Ketamine is available as a registered medicine via the Sale of Medicines Act ('med'); recreational use illegal. Cannabis has a notable medical/industrial-hemp regime (Act 31/2021, regulated 2023, amended 2024, licences from 2025) but it is EXPORT-ONLY with explicitly no domestic patient access, so cannabis remains 'ill' for real-world access; CBD has no carve-out (defaults to 'ill', low confidence). Coca leaf has no traditional use and is 'ill'. Ibogaine is unscheduled and unregulated ('nodata'). Vanuatu has NO death penalty (abolished 1973), so 'cap' applies to nothing.", can:"Recreational cannabis illegal & enforced under Dangerous Drugs Act CAP 12 (possession up to ~2 yrs, cultivation up to 7 yrs). A medical cannabis/industrial hemp regime exists (Act 31/2021, regulated 2023, amended 2024, first licences issued by Jan 2025) but is EXPORT-ONLY — officials state it 'will not be grown for locals'; no domestic patient/prescription access.", cbd:"No specific CBD carve-out; legal status 'unclear' and CBD falls under the general cannabis/dangerous-drugs prohibition by default. Low confidence.", dmt:"DMT prohibited as a scheduled psychotropic; ayahuasca plant not specifically named and no religious/indigenous exemption exists in Vanuatu.", ket:"Ketamine handled as a registered/prescription medicine via the Sale of Medicines Act (psychotropics prohibited under CAP 12 'except when separately specified' in Sale of Medicines Act); recreational use illegal.", ibo:"No Vanuatu-specific scheduling of ibogaine and no medical-approval framework found; genuinely indeterminate.", coca:"No traditional/indigenous coca use; treated under the general narcotics prohibition, illegal. No death penalty in Vanuatu (abolished 1973), so no 'cap' applies." } },
  VE: { n:"Venezuela", def:'ill', st:{ can:'decrim', ket:'med', ibo:'nodata' }, nt:{ _:"Venezuela prohibits all listed psychoactives under the Ley Orgánica de Drogas (2010); trafficking/distribution carries 15-25 years and cultivation 10-20 years, but there is NO death penalty (capital punishment is constitutionally abolished), so no 'cap'. Personal-use possession of small quantities (e.g. ~20 g cannabis, ~2 g cocaine) is statutorily treated as non-criminal and diverted to mandatory treatment — hence cannabis is marked 'decrim'. CBD and all cannabis derivatives are explicitly illegal with no medical-cannabis program. Psilocybin, LSD, MDMA, DMT/ayahuasca and mescaline are UN-1971-scheduled and enforced ('ill'); indigenous Amazonian customary entheogen use exists but no codified exemption was found. Ketamine assigned 'med' per regional pharmaceutical norm (no VE-specific source). Coca leaf is 'ill' (Venezuela is not an Andean coca-tradition country). Ibogaine is 'nodata' (no VE-specific legal status located). Confidence medium: cannabis/cocaine/CBD/trafficking framework well-sourced; ketamine, ibogaine, and the entheogens lack Venezuela-specific primary citations.", can:"Illegal under the Ley Orgánica de Drogas, but personal-use possession (up to ~20 g) is treated as non-criminal and routed to mandatory treatment/rehab rather than prison — de-facto decriminalized for personal use. No medical-cannabis program; supply/cultivation remain criminal (trafficking 15-25 yrs).", cbd:"Explicitly illegal: hemp-derived CBD and all cannabis derivatives are prohibited; industrial hemp cultivation is illegal. No medical exemption.", psi:"Psilocybin mushrooms prohibited under UN-1971-based controls; no decrim/medical pathway.", lsd:"Prohibited; no decrim/medical pathway.", mdma:"Prohibited; possession of even small quantities can bring significant charges; no MDMA-therapy pathway.", dmt:"DMT/ayahuasca UN-1971 scheduled and prohibited. Indigenous Amazonian customary use exists and the constitution recognizes indigenous ancestral rights, but no codified legal/religious ayahuasca exemption was found.", mes:"Mescaline (peyote/San Pedro) UN-1971 scheduled and prohibited; no formal traditional/religious exemption identified.", ket:"No Venezuela-specific source found; classified as a registered medical anaesthetic (medical use legal, recreational illegal) per regional norm — lower confidence.", ibo:"No Venezuela-specific legal status found; not separately scheduled or regulated as a medicine. Genuinely unknown.", coc:"Refined cocaine illegal and enforced (major transit country; trafficking 15-25 yrs). Note: the same personal-dose framework as cannabis exists in statute (up to ~2 g treated as non-criminal possession routed to treatment), but supply is heavily criminalized.", coca:"Not an Andean coca-tradition country; no legal traditional chewing. Coca treated as a controlled crop (cultivation 10-20 yrs)." } },
  VN: { n:"Vietnam", def:'ill', st:{ can:'cap', lsd:'cap', mdma:'cap', ket:'med', ibo:'nodata', coc:'cap' }, nt:{ _:"Vietnam retains one of the world's harshest drug regimes. Effective 1 July 2025, the death penalty was removed for illegal drug TRANSPORTATION (existing sentences commuted to life), but it is explicitly RETAINED for illegal drug TRAFFICKING and illegal PRODUCTION of narcotics, which remain among the 10 capital offences. Hence 'cap' for the high-volume illicit drugs (cannabis, LSD, MDMA, cocaine) whose trafficking thresholds sit within the death-penalty framework, and 'ill' used conservatively for plant/research psychedelics (psilocybin, DMT, mescaline) and coca leaf where realistic enforcement is custodial. Ketamine is a controlled medicine (med). CBD oil from low-THC hemp is the one tolerated/legal product. No psychedelic therapy, religious, or decriminalization carve-outs exist; ibogaine has no recognized status.", can:"List I prohibited narcotic, zero tolerance for use/possession/cultivation. Trafficking >=5kg cannabis resin or >=75kg leaves/stems can carry the death penalty (Penal Code Art. 248-252).", cbd:"De-facto exception: CBD oil from industrial hemp <0.3% THC is sold/tolerated. No medical-cannabis program and no THC access; status pragmatic rather than an explicit legalization.", psi:"Schedule/List I prohibited narcotic, criminal offence; no therapy/research access. Capital regime applies in principle but realistic enforcement is custodial.", lsd:"List I prohibited; named among the most dangerous drugs. Large-scale trafficking falls under the capital-punishment quantity framework.", mdma:"List I 'extremely dangerous' narcotic; trafficking subject to capital-punishment thresholds.", dmt:"Prohibited narcotic (incl. ayahuasca); no religious/indigenous exemption. Illegal and enforced.", mes:"Mescaline prohibited narcotic; no peyote/San Pedro religious carve-out. Illegal and enforced.", ket:"Controlled medicine: List III, permitted for medical, scientific and veterinary use under special control. Recreational use illegal and a notable street-drug concern.", ibo:"No evidence of specific scheduling or any clinical/therapeutic availability; not a recognized medicine. Treated as unknown/no-access.", coc:"List I illegal; trafficking >=100g cocaine can carry the death penalty.", coca:"Coca leaf listed as an illegal plant narcotic with its own quantity tiers (25kg/75kg); no traditional/cultural use. Marked ill conservatively (capital threshold very high at >=75kg)." } },
  EH: { n:"Western Sahara", def:'ill', st:{ cbd:'med', ket:'med' }, nt:{ _:"Western Sahara is a disputed territory; the populated ~80% west of the berm is under de-facto Moroccan administration, so Moroccan drug law is the operative framework for patient/researcher access. Recreational cannabis and all classic psychedelics (psilocybin, LSD, MDMA, DMT/ayahuasca, mescaline), ibogaine, refined cocaine and raw coca are illegal and enforced as prohibited narcotics/hallucinogens. CBD/medical cannabis is legal as a regulated industry under Morocco's Law 13-21 (ANRAC), with 141+ registered cannabis-based products including a CBD epilepsy medicine by 2025 (though licensed cultivation sits in mainland Rif, not the territory itself). Ketamine is a registered clinical medicine. Morocco does NOT impose the death penalty for drug offences (de-facto moratorium since 1993), so no 'cap'. Medium confidence due to sparse Western Sahara-specific enforcement data and the slightly more lenient but still-prohibitionist SADR-controlled zone.", can:"Recreational cannabis illegal and enforced. Most of Western Sahara is under de-facto Moroccan administration, so Moroccan law applies (Dahir 1974 / Penal Code): possession/use 2 months-1yr + fine; cultivation/trafficking up to 30 years. SADR/Polisario-held 'Free Zone' is sparsely populated and slightly more lenient/inconsistent but still prohibitionist (not legalized/decrim).", cbd:"Under Moroccan Law 13-21 (2021), CBD/medical & cosmetic cannabis is a legal regulated industry overseen by ANRAC; 141+ cannabis-based products (incl. a CBD epilepsy medicine) registered with Morocco's medicines agency by 2025. Note: licensed cultivation is concentrated in mainland Rif provinces, not the Sahara territory itself; recreational use remains illegal.", dmt:"DMT/ayahuasca, psilocybin, LSD, MDMA and mescaline are all scheduled prohibited hallucinogens/narcotics under Moroccan law; criminal offence to possess/use, no medical or research access. NOTE: Morocco does NOT carry the death penalty for drug offences (moratorium on executions since 1993), so 'cap' does not apply.", ket:"Registered medicine (anesthetic/clinical) under the Moroccan system governing the territory; recreational use illegal.", coc:"Refined cocaine illegal and enforced as a narcotic.", coca:"No traditional/indigenous coca use; treated as a prohibited narcotic." } },
  YE: { n:"Yemen", def:'cap', st:{ cbd:'ill', ket:'med', ibo:'ill', coca:'ill' }, nt:{ _:"Yemen is a strict prohibition state under Law No. 3 of 1993 (Control of Illicit Trafficking in and Abuse of Narcotics and Psychotropic Substances, Arts 33-35) and the 1971 Convention. All internationally scheduled drugs are illegal with no medical/religious carve-outs; drug trafficking carries the death penalty (a sentence was imposed June 2022 for amphetamines + cannabis resin, the first in 11 years), so trafficking-eligible substances are coded 'cap'. CBD, ibogaine and coca leaf are coded 'ill' (prohibited but less likely to anchor a capital trafficking charge). Ketamine functions as a registered WHO essential anaesthetic used in Yemeni hospitals, hence 'med'. Qat/khat (not in scope) is notably legal and widely consumed.", can:"Illegal, no medical/CBD carve-out. Trafficking is death-eligible; a death sentence was imposed in June 2022 for trafficking amphetamines and cannabis resin (HRI/Psychedelic Alpha).", cbd:"No hemp/CBD exemption; treated as a prohibited cannabis derivative.", psi:"Schedule I psychotropic under Law No. 3 of 1993 (1971 Convention); no carve-out, trafficking death-eligible.", lsd:"Controlled under the 1971 Convention / 1993 narcotics law; trafficking death-eligible.", mdma:"Amphetamine-type substance; the June 2022 capital sentence covered amphetamines, so trafficking is genuinely death-eligible.", dmt:"No religious/ayahuasca exemption; prohibited Schedule I substance.", mes:"Prohibited; no indigenous/peyote/San Pedro exemption.", ket:"WHO essential anaesthetic, used clinically in Yemeni hospitals; recreational use prohibited.", ibo:"No approval or carve-out; falls under blanket narcotics prohibition.", coc:"Refined cocaine illegal; trafficking death-eligible under Articles 33-35 of Law No. 3 of 1993.", coca:"No traditional coca use; prohibited under the narcotics law." } },
  ZM: { n:"Zambia", def:'ill', st:{ ket:'med' }, nt:{ _:"Zambia controls cannabis and all classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline), ketamine, cocaine and coca leaf under the Narcotic Drugs and Psychotropic Substances Act 2021 (Sch II narcotics: cocaine, coca leaf; Sch III psychotropics: MDMA, psilocybin, DMT, mescaline, LSD, ketamine, cannabis >0.3% THC). Possession of most drugs carries up to 15 yrs; trafficking 1-25 yrs. Cannabis is the main nuance: medical/export cultivation was legalized in principle (Cannabis Act 2021 via ZAMRA) but no commercial licences have actually been issued, so there is no functional legal market; personal cannabis possession (on admission of guilt) is uniquely penalized by a fine rather than prison, though it remains a criminal offence. Ketamine = 'med' (Essential Medicines List anaesthetic; medical/research use regulated under the Controlled Substances Act 2023, which provides a licensing pathway for medicinal/scientific/research use of scheduled substances). No religious/indigenous exemptions for ayahuasca, peyote, etc. Ibogaine is not separately scheduled but has no legal/medical access. Note: Zambia abolished the death penalty in December 2022, so no drug offence carries capital punishment ('cap' not used).", can:"Schedule III, Narcotic Drugs & Psychotropic Substances Act 2021 (>0.3% THC). Recreational/personal use illegal, but possession of cannabis (and khat) on admission of guilt is penalized by a FINE only (up to 1,200 penalty units, s.18(3)), not the up-to-15-yr term for other drugs. Medical/export cultivation legalized in principle (Cannabis Act 2021, via ZAMRA) but as of 2024-2026 effectively NO commercial licenses issued; no legal domestic supply.", cbd:"No separate CBD law; CBD is not differentiated from cannabis and falls under controlled cannabis products. No legal consumer CBD market. Industrial Hemp Act (<0.3% THC) commenced via 2024/2025 order, but this is industrial/licensed, not a consumer CBD framework.", psi:"Schedule III psychotropic, NDPS Act 2021; illegal. Research/medical only via licence under Controlled Substances Act 2023.", dmt:"Schedule III psychotropic, NDPS Act 2021; illegal. No ayahuasca religious/indigenous exemption.", mes:"Schedule III psychotropic (mescaline listed), NDPS Act 2021; illegal. No peyote/San Pedro exemption.", ket:"Schedule III psychotropic substance, but a registered medicine on Zambia's Essential Medicines List (IV/IM anaesthetic); medical/scientific use regulated under the Controlled Substances Act 2023. Recreational/non-medical use illegal.", coc:"Schedule II narcotic, NDPS Act 2021. Possession up to 15 yrs; trafficking 1-25 yrs. Note: Zambia ABOLISHED the death penalty (Dec 2022), so no capital drug offences.", coca:"Coca leaf explicitly listed in Schedule II (narcotic drugs) of NDPS Act 2021; illegal. No traditional-use exemption." } },
  ZW: { n:"Zimbabwe", def:'ill', st:{ cbd:'med', ket:'med' }, nt:{ _:"Zimbabwe prohibits virtually all recreational/non-medical drug use under the Dangerous Drugs Act [Chapter 15:02], which is actively enforced (custodial sentences for cannabis, crystal meth, cocaine). Recreational cannabis is illegal (up to 12 years) and has NOT been decriminalised, though medical/scientific cannabis has been legal since April 2018 under a licensed regime, and hemp-derived CBD (<=1% THC) has been allowed as a traditional herbal medicine since 2022. Ketamine is a registered medicine via MCAZ (med). The classic psychedelics (psilocybin, LSD, MDMA, DMT, mescaline) and ibogaine have no carve-outs or therapeutic/research access and are prohibited; MDMA and cocaine are explicitly named in the Dangerous Drugs Act schedules. The death penalty was abolished (Act No. 4 of 2024) and was never applied to drug offences, so no substance warrants 'cap'. Higher confidence on cannabis/CBD/ketamine/cocaine/MDMA (directly sourced); the niche psychedelics (psi/lsd/dmt/mes/ibo) and raw coca are inferred from blanket prohibition plus the absence of any reform.", can:"Recreational cannabis illegal and enforced; possession punishable by up to 12 years. Medical/scientific cannabis legalised April 2018 (2nd African country) under licensed regime, but personal/recreational use NOT decriminalised.", cbd:"Hemp-derived CBD permitted as a traditional herbal medicine since 2022 when MCAZ opened the domestic market; hemp defined as <=1% THC. Available as a complementary/herbal medicine.", psi:"No psilocybin reform or exemption; prohibited under the Dangerous Drugs Act and Zimbabwe's UN-convention obligations; drug laws actively enforced.", mdma:"MDMA (methylenedioxymethamphetamine) explicitly listed in Part II of the Schedule to the Dangerous Drugs Act; prohibited and actively prosecuted.", dmt:"No ayahuasca/religious or research carve-out; controlled under the Dangerous Drugs Act as a prohibited substance.", ket:"Ketamine is a registered anaesthetic regulated by the Medicines Control Authority of Zimbabwe (MCAZ); recreational/non-medical use prohibited.", coc:"Cocaine named in the Dangerous Drugs Act (Part IV: medicinal opium, cocaine, morphine); illegal and enforced with custodial sentences. Death penalty abolished (Act No. 4 of 2024) and never applied to drug offences.", coca:"No traditional coca use or exemption in Zimbabwe; treated as a prohibited substance." } },
};

